  function promoCheck(kode, subtotal) {
    var p = db.PROMO.filter(function (x) { return String(x.kode).toUpperCase() === String(kode || '').toUpperCase().trim(); })[0];
    if (!p) return { valid: false, reason: 'Kode promo tidak ditemukan', diskon: 0 };
    if (!num(p.aktif)) return { valid: false, reason: 'Promo sudah tidak aktif', diskon: 0 };
    var today = dayStr();
    if (p.mulai && p.mulai > today) return { valid: false, reason: 'Promo belum dimulai', diskon: 0 };
    if (p.akhir && p.akhir < today) return { valid: false, reason: 'Promo sudah berakhir', diskon: 0 };
    if (num(p.kuota) > 0 && num(p.terpakai) >= num(p.kuota)) return { valid: false, reason: 'Kuota promo habis', diskon: 0 };
    if (num(subtotal) < num(p.min_belanja)) return { valid: false, reason: 'Minimum belanja ' + rp(p.min_belanja), diskon: 0 };
    var d = String(p.tipe).toUpperCase() === 'PERCENT' ? Math.round(num(subtotal) * num(p.nilai) / 100) : num(p.nilai);
    if (num(p.maks_diskon) > 0) d = Math.min(d, num(p.maks_diskon));
    return { valid: true, kode: p.kode, judul: p.judul, tipe: p.tipe, diskon: Math.min(d, num(subtotal)) };
  }
  function hitung(payload) {
    var s = settings(), items = payload.items || [], detail = [], subtotal = 0;
    items.forEach(function (it) {
      var p = db.PRODUCT.filter(function (x) { return x.sku === (it.sku || it.id); })[0];
      if (!p) return;
      var q = Math.max(1, num(it.qty)), harga = num(it.harga) || num(p.harga), line = harga * q;
      subtotal += line;
      detail.push({ id: p.id, sku: p.sku, nama: p.nama, qty: q, harga: harga, hpp: num(p.harga_beli), line: line,
        kategori: p.kategori, tipe: p.tipe, gambar: p.gambar, garansi: p.garansi });
    });
    var promo = payload.promo ? promoCheck(payload.promo, subtotal) : { valid: false, diskon: 0 };
    var dMan = Math.max(0, num(payload.diskon_manual));
    var diskon = Math.min(Math.round(subtotal * .9), (promo.valid ? promo.diskon : 0) + dMan);
    var poinPakai = Math.max(0, num(payload.poin_pakai)), nilai = num(s.poin_nilai) || 1000;
    var batas = Math.round((subtotal - diskon) * (num(s.poin_maks_pct) || 30) / 100);
    var poinRp = poinPakai * nilai;
    if (poinRp > batas) { poinPakai = Math.floor(batas / nilai); poinRp = poinPakai * nilai; }
    var ongkir = Math.max(0, num(payload.ongkir));
    if (num(s.gratis_ongkir) > 0 && subtotal >= num(s.gratis_ongkir)) ongkir = 0;
    var dasar = Math.max(0, subtotal - diskon - poinRp);
    var pajak = Math.round(dasar * num(s.pajak_pct) / 100), total = dasar + ongkir + pajak;
    var bayar = num(payload.bayar);
    var cust = payload.customer_id ? find('CUSTOMER', payload.customer_id) : null;
    return { items: detail, subtotal: subtotal, promo: promo, diskon: diskon, diskon_manual: dMan,
      poin_pakai: poinPakai, poin_rp: poinRp, poin_dapat: Math.floor(dasar / 1000), ongkir: ongkir, pajak: pajak,
      total: total, bayar: bayar, kembali: Math.max(0, bayar - total), kurang: Math.max(0, total - bayar),
      customer: cust, settings: s };
  }
  function struk(o, s) {
    var W = 40, L = [];
    function pad(a, b) { a = String(a); b = String(b); return a + new Array(Math.max(1, W - a.length - b.length) + 1).join(' ') + b; }
    function ctr(t) { t = String(t); return new Array(Math.max(0, Math.floor((W - t.length) / 2)) + 1).join(' ') + t; }
    L.push(ctr(String(s.nama_toko).toUpperCase()), ctr(s.alamat), ctr('WA ' + s.wa), new Array(W + 1).join('-'));
    L.push(pad('No ' + o.id, String(o.tanggal).slice(0, 16)));
    L.push('Kasir : ' + o.kasir);
    if (o.nama) L.push('Pelanggan : ' + o.nama + (o.wa ? ' (' + o.wa + ')' : ''));
    L.push(new Array(W + 1).join('-'));
    (o.items || []).forEach(function (it) {
      L.push(String(it.nama).slice(0, W));
      L.push(pad('  ' + it.qty + ' x ' + rp(it.harga), rp(it.line || num(it.harga) * num(it.qty))));
    });
    L.push(new Array(W + 1).join('-'));
    L.push(pad('Subtotal', rp(o.subtotal)));
    if (num(o.diskon)) L.push(pad('Diskon ' + (o.diskon_kode || ''), '-' + rp(o.diskon)));
    if (num(o.poin_pakai)) L.push(pad('Tukar poin (' + o.poin_pakai + ')', '-' + rp(num(o.poin_pakai) * num(s.poin_nilai))));
    if (num(o.ongkir)) L.push(pad('Ongkir', rp(o.ongkir)));
    L.push(pad('TOTAL', rp(o.total)), pad('Bayar (' + o.metode + ')', rp(o.bayar)), pad('Kembali', rp(o.kembali)));
    L.push(new Array(W + 1).join('-'));
    if (num(o.poin_dapat)) L.push('Poin diperoleh : +' + o.poin_dapat);
    L.push(ctr('Garansi resmi toko - simpan struk ini'), ctr('Terima kasih telah berbelanja!'), '', ctr('Sarinadinet Commerce & POS'));
    return L.join('\n');
  }
  function serviceView(j) {
    var flow = ['MASUK', 'ANTRI', 'DIAGNOSA', 'MENUNGGU_PART', 'DIKERJAKAN', 'SELESAI', 'DIAMBIL'];
    var idx = flow.indexOf(String(j.status));
    return Object.assign({}, j, { parts: j.parts || [], step: idx < 0 ? 0 : idx, total_step: flow.length,
      progres: idx < 0 ? 0 : Math.round((idx + 1) / flow.length * 100) });
  }
  function estimasiTI(p) {
    var s = settings(), harga = num(p.harga_beli_dulu || p.harga), th = num(p.tahun) || new Date().getFullYear();
    var umur = Math.max(0, new Date().getFullYear() - th), fT = .18;
    for (var i = 0; i < TI_FAKTOR.length; i++) if (umur <= TI_FAKTOR[i].max) { fT = TI_FAKTOR[i].f; break; }
    var kd = TI_KONDISI[String(p.kondisi || 'NORMAL').toUpperCase()] || TI_KONDISI.NORMAL;
    var bBrand = /apple|mac|rog|legion|msi|thinkpad|xps/i.test(String(p.brand || '')) ? 1.08 : 1;
    var kat = String(p.kategori || 'laptop').toLowerCase();
    var bKat = kat === 'laptop' ? 1.05 : kat === 'komponen' ? .9 : 1;
    var base = harga * fT * kd.f * bBrand * bKat;
    var lo = Math.round(base * .92 / 1000) * 1000, hi = Math.round(base * 1.06 / 1000) * 1000;
    var bonusPct = num(s.tradein_bonus_pct) || 5, bonusRp = Math.round(hi * bonusPct / 100 / 1000) * 1000;
    return { aktif: true, harga_beli_dulu: harga, umur_tahun: umur, faktor_tahun: fT,
      kondisi: String(p.kondisi || 'NORMAL').toUpperCase(), kondisi_label: kd.label, faktor_kondisi: kd.f,
      estimasi_lo: lo, estimasi_hi: hi, bonus_pct: bonusPct, bonus_rp: bonusRp, nilai_maksimal: hi + bonusRp, rekomendasi: [],
      syarat: ['Unit berfungsi normal sesuai kondisi yang dideklarasikan.',
        'Wajib dilengkapi charger atau aksesori original bila ada.',
        'Harga final ditentukan setelah verifikasi teknisi di toko.',
        'Tidak menerima unit blacklist atau hasil kejahatan (wajib KTP).'] };
