          var om = sum(lz, function (x) { return x.total; }), hp = 0, qtx = 0;
          lz.forEach(function (x) { (x.items || []).forEach(function (it) { hp += num(it.hpp) * num(it.qty); qtx += num(it.qty); }); });
          labels.push(pad2(dd.getDate()) + '/' + pad2(dd.getMonth() + 1));
