        if (p.entitas && p.entitas !== 'ALL') au = au.filter(function (x) { return String(x.entitas).toUpperCase() === String(p.entitas).toUpperCase(); });
        if (p.q) { var q9 = String(p.q).toLowerCase(); au = au.filter(function (x) { return (x.aksi + x.user + x.detail + x.entitas_id).toLowerCase().indexOf(q9) > -1; }); }
        var limA = num(p.limit) || 60, pgA = num(p.page) || 1;
        return { ok: true, data: au.slice((pgA - 1) * limA, pgA * limA),
