})();

/* =========================== 4. LAPISAN API ============================== */
function apiDemo() { return !CONFIG.API_URL || CONFIG.API_URL.indexOf('script.google.com') < 0; }

/** Panggil API GAS: fetch -> fallback JSONP otomatis. */
function api(action, params, opt) {
  params = params || {};
  opt = opt || {};
  var payload = Object.assign({}, params);
  payload.action = action;
  if (S.token && !payload.token) payload.token = S.token;
  if (S.user && S.user.id) payload.userId = S.user.id;

  if (apiDemo()) {
    var res = DEMO.handle(action, payload);
    if (res && res.ok === false) {
      var e = new Error((res.error && res.error.message) || 'Terjadi kesalahan');
      e.code = res.error && res.error.code;
      e.soft = true;
      return Promise.reject(e);   /* selalu async, jangan lempar sinkron */
    }
    return Promise.resolve(res);
  }

  var body = JSON.stringify(payload);
  var ctrl = ('AbortController' in window) ? new AbortController() : null;
  var to = setTimeout(function () { if (ctrl) ctrl.abort(); }, CONFIG.TIMEOUT);
  return fetch(CONFIG.API_URL, {
    method: 'POST', body: body, redirect: 'follow',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    signal: ctrl ? ctrl.signal : undefined
  }).then(function (r) { return r.json(); }).then(function (json) {
    clearTimeout(to);
    if (!json || json.ok === false) {
      var er = new Error((json && json.error && json.error.message) || 'Permintaan gagal');
      er.code = json && json.error && json.error.code;
      throw er;
    }
    return json;
  }).catch(function (err) {
    clearTimeout(to);
    if (!CONFIG.USE_JSONP || err.name === 'AbortError') {
      if (err.name === 'AbortError') throw new Error('Koneksi ke server terlalu lama. Periksa jaringan Anda.');
      return jsonp(action, payload);
    }
    return jsonp(action, payload);
  });
}

/** Fallback JSONP untuk browser/koneksi yang memblokir CORS. */
function jsonp(action, params) {
  return new Promise(function (resolve, reject) {
    var cb = 'sdcb_' + Math.random().toString(36).slice(2, 10);
    var qs = Object.keys(params).map(function (k) {
      var v = params[k]; if (typeof v === 'object') v = JSON.stringify(v);
      return encodeURIComponent(k) + '=' + encodeURIComponent(v);
    }).join('&');
    var s = document.createElement('script');
    var timer = setTimeout(function () { cleanup(); reject(new Error('Koneksi timeout (JSONP).')); }, CONFIG.TIMEOUT);
    function cleanup() {
      clearTimeout(timer);
      delete window[cb];
      if (s.parentNode) s.parentNode.removeChild(s);
    }
    window[cb] = function (json) {
      cleanup();
      if (!json || json.ok === false) { reject(new Error((json && json.error && json.error.message) || 'Permintaan gagal')); return; }
      resolve(json);
    };
    s.onerror = function () { cleanup(); reject(new Error('Gagal menghubungi server. Periksa URL API & koneksi.')); };
    s.src = CONFIG.API_URL + '?' + qs + '&callback=' + cb;
    document.body.appendChild(s);
  });
}

/** Pembungkus dengan indikator loading + toast error otomatis. */
function call(action, params, opt) {
  opt = opt || {};
  var btn = opt.btn;
  if (btn) { btn.classList.add('loading'); btn.disabled = true; }
  return Promise.resolve().then(function () { return api(action, params); })
    .then(function (res) {
      if (btn) { btn.classList.remove('loading'); btn.disabled = false; }
      return res;
    })
    .catch(function (err) {
      if (btn) { btn.classList.remove('loading'); btn.disabled = false; }
      if (opt.silent !== true) toast(err.message || 'Terjadi kesalahan', 'err');
      if (opt.throw) throw err;
      return { ok: false, error: { message: err.message }, data: opt.fallback };
    });
}

/* =========================== 5. TEMA & UI UMUM =========================== */
function applyTheme(t) {
  document.documentElement.setAttribute('data-theme', t === 'dark' ? 'dark' : 'light');
  ls(CONFIG.THEME_KEY, t);
  $$('#themeBtn,#appThemeBtn').forEach(function (b) {
    b.innerHTML = svgI(t === 'dark' ? 'sun' : 'moon');
  });
  var meta = document.querySelector('meta[name=theme-color]');
  if (meta) meta.setAttribute('content', t === 'dark' ? '#070c17' : '#2563eb');
  if (S.page && $('#viewBox') && $('#appShell').classList.contains('on') && (S.page === 'dashboard' || S.page === 'orders') && window.drawCharts) {
    setTimeout(function () { drawCharts(); }, 120);
  }
}
function toggleTheme() { applyTheme(document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark'); }

function initReveal() {
  if (!('IntersectionObserver' in window)) { $$('.rv,.rv-l,.rv-r,.rv-s').forEach(function (e) { e.classList.add('in'); }); return; }
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (!en.isIntersecting) return;
      var el = en.target;
      var d = parseInt(el.getAttribute('data-delay') || '0', 10);
      setTimeout(function () { el.classList.add('in'); }, d);
      io.unobserve(el);
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -40px' });
  observeReveal(io);
}
function observeReveal(io) {
  var obs = io || new IntersectionObserver(function (entries) {
    entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });
  }, { threshold: 0.12 });
  $$('.rv:not(.in),.rv-l:not(.in),.rv-r:not(.in),.rv-s:not(.in)').forEach(function (e, i) {
    if (!e.getAttribute('data-delay')) e.setAttribute('data-delay', String((i % 6) * 70));
    obs.observe(e);
  });
}
function animateCount(el) {
  var target = num(el.getAttribute('data-count'));
  var suffix = el.getAttribute('data-suffix') || '';
  var start = 0, dur = 1400, t0 = null;
  function step(ts) {
    if (!t0) t0 = ts;
    var p = clamp((ts - t0) / dur, 0, 1);
    var eased = 1 - Math.pow(1 - p, 3);
    var val = Math.round(start + (target - start) * eased);
    el.textContent = val.toLocaleString('id-ID') + suffix;
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
function initCounters() {
  var els = $$('[data-count]');
  if (!els.length) return;
  if (!('IntersectionObserver' in window)) { els.forEach(animateCount); return; }
  var io = new IntersectionObserver(function (en) {
    en.forEach(function (e) { if (e.isIntersecting) { animateCount(e.target); io.unobserve(e.target); } });
  }, { threshold: 0.4 });
  els.forEach(function (e) { io.observe(e); });
}
function initNav() {
  var nav = $('#nav');
  var links = $$('.nav-links a');
  var sections = ['beranda', 'katalog', 'rakitan', 'service', 'tradein', 'faq'];
  function onScroll() {
    var y = window.scrollY || window.pageYOffset;
    nav.classList.toggle('stuck', y > 24);
    $('#fabTop').classList.toggle('on', y > 620);
    var cur = 'beranda';
    sections.forEach(function (id) {
      var el = document.getElementById(id);
      if (el && el.getBoundingClientRect().top <= 130) cur = id;
    });
    links.forEach(function (a) { a.classList.toggle('active', a.getAttribute('href') === '#' + cur); });
    $$('.mobile-nav a').forEach(function (a) {
      a.classList.toggle('on', a.getAttribute('href') === '#' + cur);
    });
  }
  on(window, 'scroll', onScroll, { passive: true });
  onScroll();
  on($('#burger'), 'click', function () { $('#drawer').classList.add('open'); document.body.classList.add('no-scroll'); });
  $$('[data-close]').forEach(function (el) {
    on(el, 'click', function () {
      var t = el.getAttribute('data-close');
      if (t === 'drawer') { $('#drawer').classList.remove('open'); if (!$$('.modal.open').length) document.body.classList.remove('no-scroll'); }
      else closeModal(t);
    });
  });
  on($('#fabTop'), 'click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); });
  on($('#drawer'), 'click', function (e) {
    if (e.target.tagName === 'A' || e.target.closest('.dr-link')) {
      var d = $('#drawer'); d.classList.remove('open');
      if (!$$('.modal.open').length) document.body.classList.remove('no-scroll');
    }
  });
  on($('#themeBtn'), 'click', toggleTheme);
  $$('.mobile-nav a[href^="#"]').forEach(function (a) {
    on(a, 'click', function (e) {
      e.preventDefault();
      var t = $(a.getAttribute('href'));
      if (t) t.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });
}
function initTicker() {
  var t = $('#tickerTrack');
  if (t) { t.innerHTML = t.innerHTML + t.innerHTML; }
}
function initFAQ() {
  $$('#faqList .faq-item').forEach(function (item) {
    var q = $('.faq-q', item), a = $('.faq-a', item);
    on(q, 'click', function () {
      var isOpen = item.classList.contains('open');
      $$('#faqList .faq-item.open').forEach(function (o) {
        o.classList.remove('open');
        $('.faq-a', o).style.maxHeight = '0px';
      });
      if (!isOpen) {
        item.classList.add('open');
        a.style.maxHeight = a.scrollHeight + 40 + 'px';
      }
    });
  });
}
function initRateBars() {
  var bars = $$('.rate-bar .track i');
  if (!bars.length) return;
  if (!('IntersectionObserver' in window)) {
    bars.forEach(function (b) { b.style.width = b.getAttribute('data-w') + '%'; });
    return;
  }
  var io = new IntersectionObserver(function (en) {
    en.forEach(function (e) {
      if (e.isIntersecting) {
        e.target.style.width = e.target.getAttribute('data-w') + '%';
        io.unobserve(e.target);
      }
    });
  }, { threshold: 0.4 });
  bars.forEach(function (b) { io.observe(b); });
}

/* =========================== 6. TESTIMONI & FOOTER ======================= */
function renderTestimonials(list) {
  if (!list || !list.length) { $('#tstMarquee').innerHTML = ''; return; }
  function card(t) {
    return '<article class="tst">' +
      '<div class="flex between center">' + starHtml(num(t.rating) || 5) +
      '<span class="prod">' + esc(t.produk || '') + '</span></div>' +
      '<p class="quote">“' + esc(t.pesan) + '”</p>' +
      '<div class="who">' + imgTag(t.avatar, t.nama, '', 'width:40px;height:40px;border-radius:50%') +
      '<div><strong>' + esc(t.nama) + '</strong><small>' + esc(t.kota || '') + ' · Pelanggan Terverifikasi</small></div></div></article>';
  }
  var half = Math.ceil(list.length / 2);
  var r1 = list.slice(0, half), r2 = list.slice(half);
  var dup = function (arr) { return arr.map(card).join('') + arr.map(card).join(''); };
  $('#tstMarquee').innerHTML = '<div class="marquee-row r1">' + dup(r1) + '</div><div class="marquee-row r2">' + dup(r2.length ? r2 : r1) + '</div>';
}
function renderFooter(toko) {
  S.settings = toko || S.settings;
  var s = S.settings;
  var wa = s.wa || CONFIG.WA_DEFAULT;
  $('#navTagline').textContent = s.tagline || 'Laptop & PC Store';
  $('#drawerJam').textContent = s.jam_buka || 'Senin - Sabtu, 09.00 - 21.00';
  $('#ctWaText').textContent = wa;
  $('#ctAlamat').textContent = s.alamat || '';
  $('#ctJam').textContent = s.jam_buka || '';
  $('#fWaText').textContent = wa;
  $('#fEmail').textContent = s.email || '';
  $('#fAlamat').textContent = s.alamat || '';
  $('#fJam').textContent = s.jam_buka || '';
  $('#fYear').textContent = new Date().getFullYear();
  if (s.ig) $('#fIg').href = s.ig;
  if (s.fb) $('#fFb').href = s.fb;
  if (s.tiktok) $('#fTt').href = s.tiktok;
  var m = $('#ctMaps'); if (s.maps) m.href = s.maps;
  $$('#fWa,#fWa2,#fabWa,#mnavWa,#waDrawer,#heroWaBtn').forEach(function (el) {
    var msg = 'Halo ' + (s.nama_toko || 'Sarinadinet') + ', saya ingin bertanya tentang produk laptop / PC. ';
    if (el.tagName === 'A') { el.href = waLink(wa, msg); el.target = '_blank'; }
  });
  var title = (s.nama_toko || 'Sarinadinet') + ' — ' + (s.tagline || '');
  document.title = document.title.replace('Sarinadinet', title.split(' — ')[0]);
}

/* =========================== 7. LANDING: BOOT & HERO ===================== */
var CAT = { q: '', kategori: 'ALL', kondisi: 'ALL', tipe: 'ALL', diskon: 0, tersedia: 0, sort: 'populer', page: 1, limit: 12, total: 0, pages: 1, busy: false };

function bootLanding() {
  call('public.bootstrap', {}, { silent: true }).then(function (res) {
    if (!res || !res.ok) { $('#catCount').textContent = 'Gagal memuat katalog. Coba muat ulang halaman.'; return; }
    var d = res.data;
    S.settings = d.toko;
    renderHero(d);
    renderFooter(d.toko);
    renderTestimonials(d.testimoni);
    initTicker();
    initCounters();
    initFAQ();
    initRateBars();
    loadProducts(true);
    renderBundles();
    initCatalog();
    initTradein(d.toko);
    initTradeinApplyModal();
    initLead();
    initTrackOpeners();
    initCart();
    initServiceForm(0);
    var st = d.statistik || {};
    $('#tickerOnline').textContent = (st.siap_kirim || 0) + ' produk siap kirim hari ini';
  });
}

function renderHero(d) {
  var p = (d.unggulan && d.unggulan[0]) || (d.terbaru && d.terbaru[0]);
  if (!p) return;
  if (p.gambar) { $('#heroImg').src = p.gambar; $('#heroImg').alt = p.nama; }
  $('#heroProdName').textContent = p.nama;
  $('#heroProdSpec').textContent = [p.brand, p.spesifikasi || p.kategori, p.garansi ? 'Garansi ' + p.garansi : ''].filter(Boolean).join(' · ');
  var was = $('#heroProdWas'), now = $('#heroProdPrice');
  if (p.harga_asli && p.harga_asli > p.harga) { was.textContent = rp(p.harga_asli); was.classList.remove('hide'); }
  else was.classList.add('hide');
  now.textContent = rp(p.harga);
  var card = $('#heroCard');
  if (card) {
    card.setAttribute('data-sku', p.sku);
    card.style.cursor = 'pointer';
    on(card, 'click', function () { openProduct(p.sku); });
  }
  var st = d.statistik || {};
  $('#heroRating').textContent = (d.toko && d.toko.rating ? d.toko.rating : '4.9') + '/5';
  $('#heroReviewCount').textContent = (num(d.toko && d.toko.jumlah_ulasan) || 1240).toLocaleString('id-ID') + '+';
  $('#fc1Val').textContent = (st.total_unit || 0).toLocaleString('id-ID') + '+ unit siap kirim';
}

/* ------------------------------ KATALOG -------------------------------- */
function productCard(p) {
  var badges = [];
  if (p.diskon > 0) badges.push('<span class="bdg bdg-disc">-' + p.diskon + '%</span>');
  if (p.tipe === 'BUNDLE') badges.push('<span class="bdg bdg-bundle">Paket Rakitan</span>');
  else if (p.kondisi === 'BEKAS') badges.push('<span class="bdg bdg-used">Bekas Bergaransi</span>');
  if (p.baru) badges.push('<span class="bdg bdg-new">Terbaru</span>');
  if (p.unggulan && p.diskon <= 0 && p.kondisi !== 'BEKAS') badges.push('<span class="bdg bdg-hot">Best Seller</span>');
  var stokCls = p.habis ? 'no' : (p.stok <= (p.stok_min || 3) ? 'low' : 'ok');
  var stokTxt = p.habis ? 'Stok habis' : (stokCls === 'low' ? 'Sisa ' + p.stok : 'Stok ' + p.stok + ' unit');
  var media = p.gambar
    ? '<img alt="' + esc(p.nama) + '" loading="lazy" onload="this.classList.add(\'loaded\')" src="' + esc(p.gambar) + '"/>'
    : '<div class="ph">' + svgI('laptop') + '</div>';
  return '<article class="prod rv in" data-sku="' + esc(p.sku) + '">' +
    '<div class="prod-media">' + media +
    '<div class="prod-badges">' + badges.join('') + '</div>' +
    '<button aria-label="Simpan ke favorit" class="prod-fav" data-fav="' + esc(p.sku) + '" type="button">' + svgI('heart') + '</button>' +
    '<div class="prod-quick">' +
    '<button class="btn btn-light btn-sm" data-detail="' + esc(p.sku) + '" type="button">Lihat Detail</button>' +
    '<button class="btn btn-primary btn-sm" data-add="' + esc(p.sku) + '"' + (p.habis ? ' disabled="disabled"' : '') + ' type="button">' + svgI('cart') + 'Beli</button>' +
    '</div></div>' +
    '<div class="prod-body">' +
    '<span class="prod-cat">' + esc(p.kategori) + (p.brand ? ' · ' + esc(p.brand) : '') + '</span>' +
    '<h3 class="prod-name" data-detail="' + esc(p.sku) + '">' + esc(p.nama) + '</h3>' +
    '<p class="prod-spec">' + esc(p.specShort || p.spesifikasi || '') + '</p>' +
    '<div class="prod-price"><span class="now">' + rp(p.harga) + '</span>' +
    (p.harga_asli > p.harga ? '<span class="was">' + rp(p.harga_asli) + '</span><span class="off">Hemat ' + rpS(p.harga_asli - p.harga) + '</span>' : '') +
    '</div>' +
    '<div class="prod-foot"><span class="stok ' + stokCls + '">' + svgI('box') + stokTxt + '</span>' +
    '<span class="prod-rating">' + svgI('star') + (p.rating || '4.9') + '</span></div>' +
    '</div></article>';
}

function catKey() { return [CAT.q, CAT.kategori, CAT.kondisi, CAT.tipe, CAT.diskon, CAT.tersedia, CAT.sort].join('|'); }

function loadProducts(reset) {
  if (reset) { CAT.page = 1; }
  CAT.busy = true;
  if (reset) $('#catGrid').innerHTML = skeletonCards(CAT.limit > 8 ? 8 : CAT.limit);
  call('public.products', {
    q: CAT.q, kategori: CAT.kategori, kondisi: CAT.kondisi, tipe: CAT.tipe,
    diskon: CAT.diskon, tersedia: CAT.tersedia, sort: CAT.sort, page: CAT.page, limit: CAT.limit
  }, { silent: true }).then(function (res) {
    CAT.busy = false;
    var grid = $('#catGrid');
    if (!res || !res.ok) { grid.innerHTML = emptyState('Katalog gagal dimuat. Periksa koneksi lalu coba lagi.', 'alert'); return; }
    var list = res.data || [], meta = res.meta || {};
    CAT.total = meta.total || list.length; CAT.pages = meta.pages || 1;
    var html = list.map(productCard).join('');
    if (reset) grid.innerHTML = html;
    else grid.insertAdjacentHTML('beforeend', html);
    $('#catCount').innerHTML = '<strong>' + CAT.total + '</strong> produk ditemukan' +
      (CAT.q ? ' untuk “' + esc(CAT.q) + '”' : '') +
      (CAT.pages > CAT.page ? ' · menampilkan ' + (CAT.page * CAT.limit) : '');
    $('#catMoreWrap').innerHTML = CAT.page < CAT.pages
      ? '<button class="btn btn-ghost btn-lg" id="catMore" type="button">Muat ' + (CAT.total - CAT.page * CAT.limit) + ' Produk Lainnya</button>'
      : (CAT.total > CAT.limit ? '<p style="font-size:13px;color:var(--text-3)">Semua produk sudah ditampilkan ✨</p>' : '');
    var more = $('#catMore');
    if (more) on(more, 'click', function () { CAT.page++; loadProducts(false); });
    if (!list.length && reset) grid.innerHTML = emptyState('Tidak ada produk yang cocok. Coba ubah kata kunci atau filter.', 'search');
    observeReveal();
    renderActiveFilters();
  });
}

function renderActiveFilters() {
  var box = $('#catActiveFilters'), chips = [];
  if (CAT.q) chips.push(['q', 'Pencarian: ' + CAT.q]);
  if (CAT.kategori !== 'ALL') chips.push(['kategori', CAT.kategori]);
  if (CAT.kondisi !== 'ALL') chips.push(['kondisi', CAT.kondisi === 'BEKAS' ? 'Unit Bekas' : 'Unit Baru']);
  if (CAT.tipe !== 'ALL') chips.push(['tipe', CAT.tipe === 'BUNDLE' ? 'Paket Rakitan' : 'Produk Satuan']);
  if (CAT.diskon) chips.push(['diskon', 'Sedang diskon']);
  if (CAT.tersedia) chips.push(['tersedia', 'Stok tersedia']);
  box.innerHTML = chips.length
    ? chips.map(function (c) { return '<button class="chip-filter on" data-clear="' + c[0] + '" type="button">' + esc(c[1]) + ' ' + svgI('x') + '</button>'; }).join('') +
      '<button class="chip-filter" id="catClearAll" type="button">Hapus semua filter</button>'
    : '';
  $$('#catActiveFilters [data-clear]').forEach(function (b) {
    on(b, 'click', function () {
      var k = b.getAttribute('data-clear');
      if (k === 'q') { CAT.q = ''; $('#catSearch').value = ''; }
      else if (k === 'diskon' || k === 'tersedia') { CAT[k] = 0; var cb = $('#' + (k === 'diskon' ? 'catDiskon' : 'catTersedia')); if (cb) cb.checked = false; }
      else CAT[k] = 'ALL';
      if (k === 'kategori') setTab('ALL');
      loadProducts(true);
    });
  });
  var all = $('#catClearAll');
  if (all) on(all, 'click', function () { resetCatalog(); });
}

function setTab(kat) {
  $$('#catTabs .tab').forEach(function (t) { t.classList.toggle('on', t.getAttribute('data-kat') === kat); });
}
function resetCatalog() {
  CAT.q = ''; CAT.kategori = 'ALL'; CAT.kondisi = 'ALL'; CAT.tipe = 'ALL'; CAT.diskon = 0; CAT.tersedia = 0; CAT.sort = 'populer';
  $('#catSearch').value = ''; $('#catSort').value = 'populer';
  $('#catDiskon').checked = false; $('#catTersedia').checked = false;
  setTab('ALL');
  loadProducts(true);
}

function initCatalog() {
  on($('#catSearch'), 'input', debounce(function (e) { CAT.q = e.target.value.trim(); loadProducts(true); }, 320));
  on($('#catSort'), 'change', function (e) { CAT.sort = e.target.value; loadProducts(true); });
  on($('#catTabs'), 'click', function (e) {
    var t = e.target.closest('.tab'); if (!t) return;
    CAT.kategori = t.getAttribute('data-kat'); setTab(CAT.kategori); loadProducts(true);
  });
  on($('#catFilterBtn'), 'click', function () {
    var adv = $('#catAdv');
    adv.classList.toggle('hide');
    $('#catFilterBtn').classList.toggle('on', !adv.classList.contains('hide'));
  });
  on($('#catDiskon'), 'change', function (e) { CAT.diskon = e.target.checked ? 1 : 0; loadProducts(true); });
  on($('#catTersedia'), 'change', function (e) { CAT.tersedia = e.target.checked ? 1 : 0; loadProducts(true); });
  on($('#catReset'), 'click', resetCatalog);

  on($('#catGrid'), 'click', function (e) {
    var fav = e.target.closest('[data-fav]');
    if (fav) { e.stopPropagation(); fav.classList.toggle('on'); toast(fav.classList.contains('on') ? 'Ditambahkan ke favorit' : 'Dihapus dari favorit', 'ok'); return; }
    var add = e.target.closest('[data-add]');
    if (add) { e.stopPropagation(); addToCart(add.getAttribute('data-add'), 1); return; }
    var card = e.target.closest('[data-sku]');
    if (card) openProduct(card.getAttribute('data-sku'));
  });
}

/* ------------------------------ RAKITAN -------------------------------- */
function renderBundles() {
  call('public.products', { tipe: 'BUNDLE', limit: 6, sort: 'populer' }, { silent: true }).then(function (res) {
    var box = $('#bundleGrid');
    if (!res || !res.ok || !res.data.length) {
      box.innerHTML = emptyState('Paket rakitan sedang disiapkan tim kami. Hubungi kami untuk request spesifikasi khusus.', 'cpu');
      return;
    }
    box.innerHTML = res.data.map(function (b) {
      return '<article class="card card-pad rv in bundle-card" data-sku="' + esc(b.sku) + '" style="cursor:pointer">' +
        '<div class="flex between center mb4"><span class="bdg bdg-bundle">Paket Hemat</span><span class="stok ' + (b.habis ? 'no' : 'ok') + '">' + svgI('box') + (b.habis ? 'Indent 3 hari' : 'Siap rakit') + '</span></div>' +
        '<h3 style="font-size:17px;margin-bottom:6px">' + esc(b.nama) + '</h3>' +
        '<p style="font-size:13px;color:var(--text-3);line-height:1.65;margin-bottom:14px">' + esc(b.specShort || b.spesifikasi || '') + '</p>' +
        '<div class="flex between center" style="padding-top:12px;border-top:1px dashed var(--line)">' +
        '<div><div class="prod-price" style="margin:0"><span class="now">' + rp(b.harga) + '</span>' +
        (b.harga_asli > b.harga ? '<span class="was">' + rp(b.harga_asli) + '</span>' : '') + '</div>' +
        '<small style="font-size:11.5px;color:var(--text-3)">Hemat ' + rpS((b.harga_asli || b.harga) - b.harga) + ' dari beli terpisah</small></div>' +
        '<button class="btn btn-primary btn-sm" data-add="' + esc(b.sku) + '" type="button">' + svgI('cart') + 'Tambah</button>' +
        '</div></article>';
    }).join('');
    on(box, 'click', function (e) {
      var add = e.target.closest('[data-add]');
      if (add) { e.stopPropagation(); addToCart(add.getAttribute('data-add'), 1); return; }
      var card = e.target.closest('[data-sku]');
      if (card) openProduct(card.getAttribute('data-sku'));
    });
    observeReveal();
  });
}

/* ------------------------ DETAIL PRODUK (MODAL) ------------------------ */
function openProduct(sku) {
  openModal('mProduct');
  $('#pdTitle').textContent = 'Memuat…';
  $('#pdSku').textContent = 'SKU ' + sku;
  $('#pdBody').innerHTML = '<div class="sk sk-lg"></div><div class="sk sk-line mt4"></div><div class="sk sk-line" style="width:70%"></div>';
  $('#pdFoot').innerHTML = '';
  call('public.product', { sku: sku }, { silent: true }).then(function (res) {
    if (!res || !res.ok) { $('#pdBody').innerHTML = emptyState('Produk tidak ditemukan atau sudah tidak aktif.', 'alert'); $('#pdTitle').textContent = 'Detail Produk'; return; }
    var p = res.data, rel = (res.meta && res.meta.terkait) || [];
    $('#pdTitle').textContent = p.nama;
    $('#pdSku').textContent = 'SKU ' + p.sku + ' · ' + p.kategori + (p.brand ? ' · ' + p.brand : '');
    var gal = [p.gambar].concat(p.galeri || []).filter(Boolean);
    var specs = (p.spesifikasi || '').split(/[,;\n]/).map(function (s) { return s.trim(); }).filter(Boolean);
    $('#pdBody').innerHTML =
      '<div class="pd-wrap">' +
      '<div><div class="pd-media">' + (gal[0] ? '<img alt="' + esc(p.nama) + '" id="pdImg" src="' + esc(gal[0]) + '"/>' : '<div class="ph">' + svgI('laptop') + '</div>') + '</div>' +
      (gal.length > 1 ? '<div class="pd-thumbs">' + gal.map(function (g, i) {
        return '<button class="' + (i ? '' : 'on') + '" data-g="' + esc(g) + '" type="button"><img alt="Foto ' + (i + 1) + '" src="' + esc(g) + '"/></button>';
      }).join('') + '</div>' : '') +
      '<div class="detail-grid mt4">' + infoRow('Kondisi', p.kondisi === 'BEKAS' ? 'Bekas — lolos QC 32 titik' : 'Baru — segel resmi') +
      infoRow('Stok', p.tipe === 'BUNDLE' ? 'Bisa dirakit: ' + (p.max_build !== undefined ? p.max_build : p.stok) + ' paket' : (p.habis ? 'Habis' : p.stok + ' unit')) +
      infoRow('Garansi', p.garansi || '1 Tahun') +
      infoRow('Berat', (p.berat || 0) + ' kg') + '</div></div>' +
      '<div><div class="prod-badges" style="position:static;flex-direction:row;margin-bottom:10px">' +
      (p.diskon > 0 ? '<span class="bdg bdg-disc">Diskon ' + p.diskon + '%</span>' : '') +
      (p.tipe === 'BUNDLE' ? '<span class="bdg bdg-bundle">Paket Rakitan</span>' : '') +
      (p.kondisi === 'BEKAS' ? '<span class="bdg bdg-used">Bekas Bergaransi</span>' : '') + '</div>' +
      '<div class="pd-price"><span class="now">' + rp(p.harga) + '</span>' +
      (p.harga_asli > p.harga ? '<span class="was">' + rp(p.harga_asli) + '</span><span class="off">Hemat ' + rp(p.harga_asli - p.harga) + '</span>' : '') + '</div>' +
      '<div class="flex gap2 wrapf mb4"><span class="chip">' + svgI('shield') + 'Garansi Resmi</span><span class="chip">' + svgI('truck') + 'Kirim Cepat</span>' +
      '<span class="chip">' + svgI('wrench') + 'Service Seumur Hidup</span></div>' +
      (specs.length ? '<h4 class="mt4" style="font-size:13px;margin-bottom:8px">Spesifikasi</h4><ul class="list-tick">' +
        specs.map(function (s) { return '<li>' + esc(s) + '</li>'; }).join('') + '</ul>' : '') +
      (p.tipe === 'BUNDLE' && p.komponen ? '<h4 class="mt5" style="font-size:13px;margin-bottom:8px">Isi Paket</h4><div class="bom-list">' +
        p.komponen.map(function (k) {
          return '<div class="bom-row"><span class="nm">' + esc(k.nama) + '</span><span class="qty">' + k.qty + '×</span></div>';
        }).join('') + '</div>' : '') +
      (p.deskripsi ? '<h4 class="mt5" style="font-size:13px;margin-bottom:8px">Deskripsi</h4><p style="font-size:13px;color:var(--text-2);line-height:1.75">' + esc(p.deskripsi) + '</p>' : '') +
      (rel.length ? '<h4 class="mt5" style="font-size:13px;margin-bottom:8px">Produk Terkait</h4><div class="flex gap2 wrapf">' +
        rel.slice(0, 4).map(function (r) {
          return '<button class="chip-filter" data-sku-side="' + esc(r.sku) + '" type="button">' + esc(r.nama.length > 32 ? r.nama.slice(0, 32) + '…' : r.nama) + ' · ' + rpS(r.harga) + '</button>';
        }).join('') + '</div>' : '') +
      '</div></div>';
    $('#pdFoot').innerHTML =
      '<div class="flex between center w-full" style="gap:10px;flex-wrap:wrap">' +
      '<div class="flex gap2"><span class="qty-ctrl"><button data-pdq="-1" type="button">' + svgI('minus') + '</button>' +
      '<input id="pdQty" type="number" value="1" min="1" max="' + Math.max(1, p.stok || 1) + '"/>' +
      '<button data-pdq="1" type="button">' + svgI('plus') + '</button></span></div>' +
      '<div class="flex gap2" style="flex:1;justify-content:flex-end">' +
      '<button class="btn btn-ghost" id="pdWaBtn" type="button">' + svgI('wa') + 'Tanya Stok</button>' +
      '<button class="btn btn-primary" id="pdAddBtn" type="button"' + (p.habis ? ' disabled="disabled"' : '') + '>' + svgI('cart') + (p.habis ? 'Stok Habis' : 'Tambah ke Keranjang') + '</button>' +
      '</div></div>';
    $$('#pdBody [data-g]').forEach(function (b) {
      on(b, 'click', function () { $('#pdImg').src = b.getAttribute('data-g'); $$('#pdBody [data-g]').forEach(function (x) { x.classList.remove('on'); }); b.classList.add('on'); });
    });
    $$('#pdBody [data-sku-side]').forEach(function (b) { on(b, 'click', function () { openProduct(b.getAttribute('data-sku-side')); }); });
    $$('#pdFoot [data-pdq]').forEach(function (b) {
      on(b, 'click', function () { var i = $('#pdQty'); i.value = Math.max(1, num(i.value) + num(b.getAttribute('data-pdq'))); });
    });
    on($('#pdAddBtn'), 'click', function () { addToCart(p.sku, num($('#pdQty').value) || 1); closeModal('mProduct'); });
    on($('#pdWaBtn'), 'click', function () {
      var s = S.settings || {};
      window.open(waLink(s.wa || CONFIG.WA_DEFAULT, 'Halo ' + (s.nama_toko || 'Sarinadinet') + ', saya mau tanya stok *' + p.nama + '* (SKU ' + p.sku + ') harga ' + rp(p.harga) + '. Masih tersedia?'), '_blank');
    });
  });
}

/* =========================== 8. KERANJANG & CHECKOUT ===================== */
function cartLoad() {
  try { S.cart = JSON.parse(ls(CONFIG.CART_KEY) || '[]') || []; } catch (e) { S.cart = []; }
  if (!S.cart.map) S.cart = [];
  return S.cart;
}
function cartSave() {
  ls(CONFIG.CART_KEY, JSON.stringify(S.cart));
  cartBadge();
}
function cartBadge() {
  var n = sum(S.cart, function (i) { return num(i.qty); });
  ['#cartCount', '#mCartCount'].forEach(function (sel) {
    var b = $(sel); if (!b) return;
    b.textContent = n; b.classList.toggle('hide', !n);
  });
  var cc = $('#cartCnt'); if (cc) cc.textContent = n;
}
function cartItem(sku) { return S.cart.filter(function (i) { return i.sku === sku; })[0]; }

function addToCart(sku, qty) {
  qty = Math.max(1, num(qty) || 1);
  var it = cartItem(sku);
  if (!it) {
    it = { sku: sku, qty: 0, nama: sku, harga: 0, gambar: '', stok: 99, tipe: 'UNIT', kategori: '', hpp: 0 };
    S.cart.push(it);
    call('public.product', { sku: sku }, { silent: true }).then(function (res) {
      if (!res || !res.ok) return;
      var p = res.data;
      it.nama = p.nama; it.harga = num(p.harga); it.gambar = p.gambar || '';
      it.stok = p.tipe === 'BUNDLE' ? num(p.max_build !== undefined ? p.max_build : p.stok) : num(p.stok);
      it.tipe = p.tipe; it.kategori = p.kategori; it.hpp = num(p.hpp);
      cartSave();
      if ($('#mCart').classList.contains('open')) renderCart();
    });
  }
  it.qty += qty;
  cartSave();
  var card = $('[data-sku="' + sku + '"]');
  var target = $('#cartBtn') || $('#mnavCart');
  if (card && target) {
    var r = card.getBoundingClientRect(), t = target.getBoundingClientRect();
    var f = document.createElement('div');
    f.className = 'fly';
    f.style.left = (r.left + r.width / 2) + 'px';
    f.style.top = (r.top + 30) + 'px';
    f.innerHTML = '<span>' + svgI('cart') + '</span>';
    document.body.appendChild(f);
    requestAnimationFrame(function () {
      f.style.transform = 'translate(' + (t.left + t.width / 2 - (r.left + r.width / 2)) + 'px,' + (t.top + t.height / 2 - r.top - 30) + 'px) scale(.25)';
      f.style.opacity = '0.2';
    });
    setTimeout(function () { if (f.parentNode) f.parentNode.removeChild(f); }, 750);
  }
  if (target) { target.classList.remove('bump'); void target.offsetWidth; target.classList.add('bump'); }
  toast(qty + '× ' + sku + ' masuk keranjang', 'ok');
  if ($('#mCart').classList.contains('open')) renderCart();
}

function setCartQty(sku, qty) {
  var it = cartItem(sku); if (!it) return;
  it.qty = Math.max(0, num(qty));
  if (it.qty === 0) S.cart = S.cart.filter(function (i) { return i.sku !== sku; });
  else it.qty = Math.min(it.qty, 99);
  cartSave();
  renderCart();
}
function removeCart(sku) { S.cart = S.cart.filter(function (i) { return i.sku !== sku; }); cartSave(); renderCart(); }

function cartTotals(extra) {
  var sub = sum(S.cart, function (i) { return num(i.qty) * num(i.harga || 0); });
  var pr = S.promo && S.promo.valid ? num(S.promo.diskon) : 0;
  var ongkir = extra && extra.ongkir !== undefined ? num(extra.ongkir) : (S.cart.length ? 0 : 0);
  var total = Math.max(0, sub - pr - num(S.ongkirManual || 0) + ongkir);
  return { subtotal: sub, promo: pr, ongkir: ongkir, total: total };
}

function renderCart() {
  var list = $('#cartList'), empty = $('#cartEmpty'), extras = $('#cartExtras');
  cartLoad();
  if (!S.cart.length) {
    list.innerHTML = '';
    empty.classList.remove('hide');
    extras.classList.add('hide');
    $('#cartSummary').textContent = 'Keranjang masih kosong';
    return;
  }
  empty.classList.add('hide');
  extras.classList.remove('hide');
  list.innerHTML = S.cart.map(function (i) {
    var line = num(i.harga) * num(i.qty);
    return '<div class="cart-item" data-sku="' + esc(i.sku) + '">' +
      '<img alt="' + esc(i.nama) + '" src="' + esc(i.gambar || '') + '" onerror="this.style.display=\'none\'"/>' +
      '<div class="info"><div class="nm">' + esc(i.nama) + '</div>' +
      '<div class="pr">' + rp(i.harga) + ' × ' + i.qty + ' = ' + rp(line) + '</div>' +
      '<div class="mt4 flex between center"><span class="qty-ctrl"><button data-q="-1" type="button">' + svgI('minus') + '</button>' +
      '<input data-qi type="number" value="' + i.qty + '" min="0" max="99"/>' +
      '<button data-q="1" type="button">' + svgI('plus') + '</button></span>' +
      '<small style="font-size:11.5px;color:var(--text-3)">' + (i.stok !== undefined ? 'Stok ' + i.stok : '') + '</small></div></div>' +
      '<button aria-label="Hapus item" class="rm" data-rm="' + esc(i.sku) + '" type="button">' + svgI('trash') + '</button></div>';
  }).join('');
  var t = cartTotals();
  $('#cartSummary').textContent = S.cart.length + ' jenis produk · ' + sum(S.cart, function (i) { return num(i.qty); }) + ' unit';
  var freeShip = num((S.settings || {}).ongkir_min) || 1500000;
  $('#cartTotals').innerHTML =
    '<div class="info-row"><span>Subtotal</span><strong>' + rp(t.subtotal) + '</strong></div>' +
    (t.promo ? '<div class="info-row" style="color:var(--emerald-600)"><span>Diskon promo ' + esc(S.promo.kode) + '</span><strong>- ' + rp(t.promo) + '</strong></div>' : '') +
    (S.ongkirManual ? '<div class="info-row" style="color:var(--emerald-600)"><span>Diskon tambahan</span><strong>- ' + rp(S.ongkirManual) + '</strong></div>' : '') +
    '<div class="info-row big"><span>Total</span><strong>' + rp(t.total) + '</strong></div>' +
    '<p style="font-size:11.8px;color:var(--text-3);margin-top:8px">' +
    (t.subtotal >= freeShip ? '🎉 Anda mendapat GRATIS ONGKIR se-Indonesia!' : 'Belanja ' + rp(freeShip - t.subtotal) + ' lagi untuk gratis ongkir.') +
    ' Poin didapat: <b>' + int(t.subtotal / 1000) + '</b></p>';
  checkStock();
  $$('#cartList [data-q]').forEach(function (b) {
    on(b, 'click', function () {
      var sku = b.closest('[data-sku]').getAttribute('data-sku');
      var it = cartItem(sku); if (!it) return;
      setCartQty(sku, num(it.qty) + num(b.getAttribute('data-q')));
    });
  });
  $$('#cartList [data-qi]').forEach(function (inp) {
    on(inp, 'change', function () { setCartQty(inp.closest('[data-sku]').getAttribute('data-sku'), inp.value); });
  });
  $$('#cartList [data-rm]').forEach(function (b) {
    on(b, 'click', function () { removeCart(b.getAttribute('data-rm')); toast('Item dihapus dari keranjang', 'warn'); });
  });
}

function checkStock() {
  if (!S.cart.length) return;
  call('public.stock.check', { items: S.cart.map(function (i) { return { sku: i.sku, qty: i.qty }; }) }, { silent: true }).then(function (res) {
    if (!res || !res.ok) return;
    (res.data.items || []).forEach(function (r) {
      var el = $('#cartList [data-sku="' + r.sku + '"]');
      if (!el) return;
      el.style.borderColor = r.ok ? '' : '#fecdd3';
      if (!r.ok) {
        el.classList.add('shake');
        setTimeout(function () { el.classList.remove('shake'); }, 700);
        var w = el.querySelector('.info');
        if (w && !w.querySelector('.warn-stok')) w.insertAdjacentHTML('beforeend', '<small class="warn-stok" style="color:#e11d48;font-weight:700;font-size:11.5px">⚠ ' + esc(r.pesan) + ' — silakan kurangi jumlah</small>');
      }
    });
  });
}

function applyPromo() {
  var kode = ($('#cartPromo').value || '').toUpperCase().trim();
  var msg = $('#cartPromoMsg');
  if (!kode) { msg.style.color = '#e11d48'; msg.textContent = 'Masukkan kode promo terlebih dahulu.'; return; }
  var sub = cartTotals().subtotal;
  call('public.promo.check', { kode: kode, subtotal: sub }, { btn: $('#cartPromoBtn') }).then(function (res) {
    if (!res || !res.ok) return;
    var d = res.data;
    if (d && d.valid) {
      S.promo = d;
      msg.style.color = '#059669';
      msg.textContent = '✓ ' + (d.keterangan || d.kode) + ' — hemat ' + rp(d.diskon);
      toast('Kode promo diterapkan', 'ok');
    } else {
      S.promo = null;
      msg.style.color = '#e11d48';
      msg.textContent = '✕ ' + ((d && (d.pesan || d.keterangan)) || 'Kode promo tidak berlaku.');
    }
    renderCart();
  });
}

function initCart() {
  cartLoad(); cartBadge();
  on($('#cartBtn'), 'click', openCart);
  on($('#mnavCart'), 'click', function (e) { e.preventDefault(); openCart(); });
  on($('#cartPromoBtn'), 'click', applyPromo);
  on($('#cartPromo'), 'keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); applyPromo(); } });
  on($('#cartCheckoutBtn'), 'click', function () {
    if (!S.cart.length) { toast('Keranjang masih kosong', 'warn'); return; }
    closeModal('mCart');
    setTimeout(openCheckout, 120);
  });
  on($('#cartEmptyGo'), 'click', function () { closeModal('mCart'); setTimeout(function () { var k = $('#katalog'); if (k) k.scrollIntoView({ behavior: 'smooth' }); }, 150); });
  on($('#coSubmitBtn'), 'click', submitOrder);
}

function openCart() { renderCart(); openModal('mCart'); }

function openCheckout() {
  var t = cartTotals();
  var u = ls(CONFIG.USER_KEY);
  if (typeof u === 'string') { try { u = JSON.parse(u); } catch (e) { u = null; } }
  if (u && u.id && $('#coNama') && !$('#coNama').value) {
    $('#coNama').value = u.nama || '';
    $('#coWa').value = u.wa || '';
  }
  $('#coRingkas').innerHTML = '<div class="info-row"><span>Jumlah item</span><strong>' + S.cart.length + ' jenis</strong></div>' +
    '<div class="info-row"><span>Subtotal</span><strong>' + rp(t.subtotal) + '</strong></div>' +
    (t.promo ? '<div class="info-row" style="color:var(--emerald-600)"><span>Promo ' + esc(S.promo.kode) + '</span><strong>- ' + rp(t.promo) + '</strong></div>' : '') +
    '<div class="info-row big"><span>Total bayar</span><strong>' + rp(t.total) + '</strong></div>' +
    '<p style="font-size:11.8px;color:var(--text-3);margin-top:8px">Harga final dikonfirmasi ulang oleh tim kami sebelum pembayaran.</p>';
  openModal('mCheckout');
}

function submitOrder() {
  var nama = $('#coNama').value.trim(), wa = $('#coWa').value.trim(), alamat = $('#coAlamat').value.trim();
  if (nama.length < 3) { toast('Isi nama lengkap Anda', 'warn'); $('#coNama').focus(); return; }
  if (waNum(wa).length < 10) { toast('Nomor WhatsApp tidak valid', 'warn'); $('#coWa').focus(); return; }
  if (alamat.length < 8) { toast('Alamat pengiriman belum lengkap', 'warn'); $('#coAlamat').focus(); return; }
  if (!$('#coSetuju').checked) { toast('Mohon setujui persetujuan kontak WhatsApp', 'warn'); return; }
  var payload = {
    nama: nama, wa: wa, alamat: alamat, kota: $('#coKota').value.trim(), metode: $('#coMetode').value,
    catatan: $('#coCatatan').value.trim(), promo: S.promo ? S.promo.kode : '',
    items: S.cart.map(function (i) { return { sku: i.sku, qty: i.qty }; })
  };
  call('public.order.create', payload, { btn: $('#coSubmitBtn') }).then(function (res) {
    if (!res || !res.ok) return;
    var d = res.data, o = d.order;
    S.cart = []; S.promo = null; cartSave();
    $('#cartPromo').value = ''; $('#cartPromoMsg').textContent = '';
    closeModal('mCheckout');
    successBox('Pesanan ' + o.id + ' dibuat!', 'Terima kasih ' + nama + '. Tim kami akan mengonfirmasi ketersediaan, ongkir, dan total akhir via WhatsApp dalam beberapa menit.',
      [['Kode Pesanan', o.id], ['Total Estimasi', rp(o.total)], ['Metode', o.metode], ['Status', o.status]],
      d.wa, 'Kirim Rincian via WhatsApp');
  });
}

function successBox(title, text, rows, waHref, waLabel) {
  if (title && typeof title === 'object') { var o = title; title = o.title; text = o.text; rows = o.rows; waHref = o.wa || o.waHref; waLabel = o.waLabel; }
  $('#msTitle').textContent = title || 'Berhasil!';
  $('#msText').textContent = text || '';
  var box = $('#msKode');
  if (rows && rows.length) {
    box.classList.remove('hide');
    box.innerHTML = rows.map(function (r) { return '<div class="info-row"><span>' + esc(r[0]) + '</span><strong>' + esc(r[1]) + '</strong></div>'; }).join('');
  } else box.classList.add('hide');
  var b = $('#msWaBtn');
  if (waHref) { b.classList.remove('hide'); b.textContent = ''; b.insertAdjacentHTML('beforeend', svgI('wa') + (waLabel || 'Buka WhatsApp')); b.onclick = function () { window.open(waHref, '_blank'); }; }
  else b.classList.add('hide');
  openModal('mSuccess');
}

/* ------------------------------ LACAK ---------------------------------- */
function initTrackOpeners() {
  var openers = ['#trackBtn', '#trackDrawerBtn', '#ctTrackBtn', '#trackOpenBtn'];
  openers.forEach(function (sel) {
    on($(sel), 'click', function () {
      if ($('#drawer').classList.contains('open')) { $('#drawer').classList.remove('open'); document.body.classList.remove('no-scroll'); }
      openModal('mTrack');
      setTimeout(function () { $('#trackInput').focus(); }, 200);
    });
  });
  on($('#trackGoBtn'), 'click', doTrack);
  on($('#trackInput'), 'keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); doTrack(); } });
}
function doTrack() {
  var q = $('#trackInput').value.trim();
  if (q.length < 4) { toast('Masukkan kode pesanan atau nomor WhatsApp', 'warn'); return; }
  var out = $('#trackOut');
  out.innerHTML = '<div class="sk sk-line" style="height:70px"></div><div class="sk sk-line mt4"></div>';
  call('public.track', { q: q }, { btn: $('#trackGoBtn') }).then(function (res) {
    if (!res || !res.ok) return;
    var d = res.data;
    if (!d.orders.length && !d.services.length && !d.tradein.length) {
      out.innerHTML = emptyState('Belum ada data untuk “' + esc(q) + '”. Pastikan kode/nomor sudah benar, atau hubungi kami via WhatsApp.', 'search');
      return;
    }
    var html = '';
    d.orders.forEach(function (o) {
      html += trackCard('Pesanan ' + o.id, (o.tipe || 'JUAL') + ' · ' + rp(o.total), o.status, o.tanggal,
        (o.items || []).map(function (i) { return i.nama + ' ×' + i.qty; }).join(', '),
        [['Status', o.status], ['Metode', o.metode], ['Poin didapat', o.poin_dapat]]);
    });
    d.services.forEach(function (s) {
      html += trackCard('Service ' + s.id, s.perangkat, s.status, s.tanggal, s.keluhan,
        [['Progres', s.progres + '%'], ['Estimasi biaya', rp(s.biaya || s.estimasi)], ['Teknisi', s.teknisi || 'menunggu assign']], s.progres);
    });
    d.tradein.forEach(function (t) {
      html += trackCard('Tukar Tambah ' + t.id, t.perangkat, t.status, t.tanggal,
        'Estimasi ' + rp(t.estimasi_lo) + ' — ' + rp(t.estimasi_hi),
        [['Penawaran', rp(t.penawaran)], ['Kondisi', t.kondisi]]);
    });
    out.innerHTML = html;
  });
}
function trackCard(title, sub, status, tgl, body, rows, prog) {
  return '<div class="card card-pad mb4 rv in" style="border-radius:var(--r-lg)">' +
    '<div class="flex between center wrapf mb2"><div><strong style="font-size:14.5px">' + esc(title) + '</strong>' +
    '<div style="font-size:12.3px;color:var(--text-3)">' + esc(sub) + ' · ' + esc(tgl || '') + '</div></div>' +
    '<span class="chip" style="background:var(--brand-50);border-color:var(--brand-100);color:var(--brand-700);font-weight:750">' + esc(status) + '</span></div>' +
    (prog ? '<div class="progress mb4"><i style="width:' + prog + '%"></i></div>' : '') +
    (body ? '<p style="font-size:13px;color:var(--text-2);line-height:1.7;margin-bottom:10px">' + esc(body) + '</p>' : '') +
    '<div>' + (rows || []).filter(function (r) { return r[1] !== undefined && r[1] !== ''; })
      .map(function (r) { return '<div class="info-row"><span>' + esc(r[0]) + '</span><strong>' + esc(r[1]) + '</strong></div>'; }).join('') + '</div></div>';
}

/* --------------------------- FORM SERVICE ------------------------------ */
function initServiceForm() {
  var openers = ['#svcOpenBtn', '#svcCtaBtn'];
  openers.forEach(function (sel) { on($(sel), 'click', function () { openModal('mService'); }); });
  on($('#svcSubmitBtn'), 'click', function () {
    var nama = $('#svcNama').value.trim(), wa = $('#svcWa').value.trim(),
        perangkat = $('#svcPerangkat').value.trim(), keluhan = $('#svcKeluhan').value.trim();
    if (nama.length < 3) { toast('Isi nama Anda', 'warn'); $('#svcNama').focus(); return; }
    if (waNum(wa).length < 10) { toast('Nomor WhatsApp tidak valid', 'warn'); $('#svcWa').focus(); return; }
    if (perangkat.length < 3) { toast('Isi jenis perangkat Anda', 'warn'); $('#svcPerangkat').focus(); return; }
    if (keluhan.length < 8) { toast('Jelaskan keluhan minimal 8 karakter', 'warn'); $('#svcKeluhan').focus(); return; }
    call('public.service.apply', {
      nama: nama, wa: wa, perangkat: perangkat, keluhan: keluhan, kategori: $('#svcKategori').value,
      mode: $('#svcMode').value, garansi: $('#svcGaransi').value, budget: num($('#svcBudget').value)
    }, { btn: $('#svcSubmitBtn') }).then(function (res) {
      if (!res || !res.ok) return;
      closeModal('mService');
      var d = res.data, sv = d.service || d;
      successBox('Tiket service ' + sv.id + ' dibuat', 'Terima kasih ' + nama + '. Tim teknisi kami akan menghubungi Anda untuk penjadwalan dan diagnosa awal.',
        [['No. Tiket', sv.id], ['Perangkat', perangkat], ['Status', sv.status], ['Garansi Service', sv.garansi || '-']], d.wa, 'Chat Teknisi');
      ['#svcNama', '#svcWa', '#svcPerangkat', '#svcKeluhan', '#svcBudget'].forEach(function (i) { $(i).value = ''; });
    });
  });
}

/* ---------------------------- TRADE-IN --------------------------------- */
function initTradein(toko) {
  var sel = $('#tiTahun'), y = new Date().getFullYear();
  sel.innerHTML = '';
  for (var i = y; i >= y - 12; i--) sel.insertAdjacentHTML('beforeend', '<option value="' + i + '">' + i + '</option>');
  sel.value = y - 2;
  var deb = debounce(function () { hitungTI(); }, 420);
  ['#tiBrand', '#tiPerangkat', '#tiHarga'].forEach(function (s0) { on($(s0), 'input', deb); });
  ['#tiKategori', '#tiTahun', '#tiKondisi'].forEach(function (s0) { on($(s0), 'change', function () { hitungTI(true); }); });
  on($('#tiResetBtn'), 'click', function () {
    $('#tiBrand').value = ''; $('#tiPerangkat').value = ''; $('#tiHarga').value = '';
    $('#tiKategori').value = 'laptop'; $('#tiTahun').value = y - 2; $('#tiKondisi').value = 'NORMAL';
    $('#tiOut').classList.add('hide'); $('#tiEmpty').classList.remove('hide');
  });
  on($('#tiCalcForm'), 'submit', function (e) { e.preventDefault(); hitungTI(true); });
  on($('#tiSubmitBtn'), 'click', openTradeinApply);
  on($('#tiWaBtn'), 'click', function () {
    var s = S.settings || {};
    window.open(waLink(s.wa || CONFIG.WA_DEFAULT, 'Halo ' + (s.nama_toko || 'Sarinadinet') + ', saya ingin tukar tambah ' + ($('#tiPerangkat').value || 'perangkat saya') + '.'), '_blank');
  });
}
function tiPayload() {
  return {
    kategori: $('#tiKategori').value, brand: $('#tiBrand').value.trim(), perangkat: $('#tiPerangkat').value.trim(),
    tahun: num($('#tiTahun').value), kondisi: $('#tiKondisi').value, harga_beli_dulu: num($('#tiHarga').value)
  };
}
var TI_LAST = null;
function hitungTI(force) {
  var p = tiPayload();
  if (!num(p.harga_beli_dulu) && !force) { return; }
  if (num(p.harga_beli_dulu) < 100000) {
    if (force) toast('Masukkan perkiraan harga beli dulu minimal Rp100.000', 'warn');
    return;
  }
  call('public.tradein.estimate', p, { silent: true }).then(function (res) {
    if (!res || !res.ok) return;
    var e = res.data; TI_LAST = { p: p, e: e };
    $('#tiEmpty').classList.add('hide');
    $('#tiOut').classList.remove('hide');
    $('#tiLo').textContent = rp(e.estimasi_lo);
    $('#tiHi').textContent = rp(e.estimasi_hi);
    $('#tiBonus').textContent = rp(e.bonus_rp) + ' (' + e.bonus_pct + '%)';
    $('#tiTotal').textContent = rp(e.nilai_maksimal);
    $('#tiNote').textContent = 'Umur perangkat ' + e.umur_tahun + ' tahun · faktor ' + Math.round(e.faktor_tahun * 100) + '% · kondisi ' + e.kondisi_label +
      '. Nilai maksimal bila ditukar dengan unit baru hari ini: ' + rp(e.nilai_maksimal) + '.';
    $('#tiFactors').innerHTML = [['Faktor tahun', Math.round(e.faktor_tahun * 100) + '%'], ['Faktor kondisi', Math.round(e.faktor_kondisi * 100) + '%'],
      ['Bonus tukar tambah', e.bonus_pct + '%']].map(function (f) {
        return '<div class="ti-factor"><span>' + f[0] + '</span><strong>' + f[1] + '</strong></div>';
      }).join('');
    $('#tiOut').classList.remove('rv');
    if (force) toast('Estimasi diperbarui ✓', 'ok');
  });
}
function openTradeinApply() {
  var p = tiPayload(), s = S.settings || {};
  if (num(p.harga_beli_dulu) < 100000) { toast('Hitung estimasi dulu: isi harga beli perangkat minimal Rp100.000', 'warn'); $('#tiHarga').focus(); return; }
  if (!TI_LAST) { hitungTI(true); }
  var e = TI_LAST ? TI_LAST.e : null;
  $('#tiSummary').innerHTML =
    '<div class="info-row"><span>Perangkat</span><strong>' + esc(p.perangkat || '(belum diisi)') + '</strong></div>' +
    '<div class="info-row"><span>Kategori / Tahun</span><strong>' + esc(p.kategori.toUpperCase()) + ' · ' + p.tahun + '</strong></div>' +
    '<div class="info-row"><span>Kondisi</span><strong>' + esc(p.kondisi) + '</strong></div>' +
    '<div class="info-row"><span>Harga beli dulu</span><strong>' + rp(p.harga_beli_dulu) + '</strong></div>' +
    (e ? '<div class="info-row big"><span>Estimasi tukar tambah</span><strong>' + rp(e.estimasi_lo) + ' — ' + rp(e.estimasi_hi) + '</strong></div>' +
      '<div class="info-row"><span>Bonus tukar tambah (' + e.bonus_pct + '%)</span><strong>' + rp(e.bonus_rp) + '</strong></div>' : '');
  if (!p.perangkat) $('#tiPerangkat').value = $('#tiPerangkat').value || '';
  openModal('mTradein');
}
function applyTradein() {
  var p = tiPayload();
  var nama = $('#tiNama') ? $('#tiNama').value.trim() : '';
  var wa = $('#tiWa') ? $('#tiWa').value.trim() : '';
  var s = S.settings || {};
  var teks = 'Halo ' + (s.nama_toko || 'Sarinadinet') + ', saya mau mengajukan tukar tambah:\n' +
    '• Perangkat: ' + (p.perangkat || '-') + ' (' + (p.brand || '-') + ')\n' +
    '• Tahun: ' + p.tahun + ' · Kondisi: ' + $('#tiKondisi').value + '\n' +
    '• Harga beli dulu: ' + rp(p.harga_beli_dulu) + '\n' +
    (TI_LAST ? '• Estimasi mesin: ' + rp(TI_LAST.e.estimasi_lo) + ' - ' + rp(TI_LAST.e.estimasi_hi) + '\n' : '') +
    '• Nama: ' + (nama || '(belum diisi)') + '\nMohon penilaiannya, terima kasih.';
  window.open(waLink(s.wa || CONFIG.WA_DEFAULT, teks), '_blank');
}
function initTradeinApplyModal() {
  on($('#tiSubmitApplyBtn'), 'click', function () {
    var p = tiPayload();
    var nama = $('#tiNama').value.trim(), wa = $('#tiWa').value.trim();
    if (nama.length < 3) { toast('Isi nama Anda', 'warn'); return; }
    if (waNum(wa).length < 10) { toast('Nomor WhatsApp tidak valid', 'warn'); return; }
    if (!p.perangkat) { toast('Isi tipe perangkat Anda', 'warn'); return; }
    var data = Object.assign({}, p, { nama: nama, wa: wa, catatan: $('#tiCatatan') ? $('#tiCatatan').value : '' });
    call('public.tradein.apply', data, { btn: $('#tiSubmitApplyBtn') }).then(function (res) {
      if (!res || !res.ok) return;
      closeModal('mTradein');
      var d = res.data;
      successBox('Pengajuan ' + d.tradein.id + ' diterima', 'Estimasi awal ' + rp(d.estimasi.estimasi_lo) + ' — ' + rp(d.estimasi.estimasi_hi) + '. Kami verifikasi maksimal 1×24 jam kerja.',
        [['Kode', d.tradein.id], ['Perangkat', d.tradein.perangkat], ['Estimasi', rp(d.estimasi.estimasi_hi)], ['Bonus', rp(d.estimasi.bonus_rp)]],
        d.wa, 'Kirim Data via WhatsApp');
    });
  });
}

/* ------------------------------ LEAD FORM ------------------------------ */
function initLead() {
  var f = $('#leadForm');
  if (!f) return;
  on(f, 'submit', function (e) {
    e.preventDefault();
    var nama = $('#leadNama').value.trim(), wa = $('#leadWa').value.trim();
    if (waNum(wa).length < 10) { toast('Nomor WhatsApp tidak valid', 'warn'); $('#leadWa').focus(); return; }
    var minat = $('#leadMinat') ? $('#leadMinat').value : 'Umum';
    call('public.lead', { nama: nama || 'Calon pembeli', wa: wa, minat: minat, sumber: 'landing' }, { btn: $('#leadBtn') }).then(function (res) {
      if (!res || !res.ok) return;
      f.reset();
      successBox('Terima kasih sudah mendaftar!', 'Tim kami akan mengirim katalog terbaru, promo minggu ini, dan bonus aksesoris khusus untuk Anda lewat WhatsApp.',
        [['Minat', minat], ['WhatsApp', waNum(wa)]], null);
    });
  });
  var nf = $('#footNews');
  if (nf) on(nf, 'submit', function (e) {
    e.preventDefault();
    var wa = $('#footNewsWa').value.trim();
    if (waNum(wa).length < 10) { toast('Nomor WhatsApp tidak valid', 'warn'); return; }
    call('public.lead', { nama: 'Subscriber', wa: wa, minat: 'Newsletter', sumber: 'footer' }, {}).then(function (res) {
      if (res && res.ok) { nf.reset(); toast('Berhasil berlangganan info promo 🎉', 'ok'); }
    });
  });
}

/* =========================== 9. SESI & APP SHELL ========================= */
function setSession(d) {
  S.token = d.token; S.user = d.user; S.exp = d.exp;
  ls(CONFIG.TOKEN_KEY, String(d.token));
  ls(CONFIG.USER_KEY, JSON.stringify(d.user));
}
function clearSession() { S.token = null; S.user = null; lsDel(CONFIG.TOKEN_KEY); lsDel(CONFIG.USER_KEY); }
function restoreSession() {
  var t = ls(CONFIG.TOKEN_KEY), u = ls(CONFIG.USER_KEY);
  if (!t || !u) return false;
  try { S.user = typeof u === 'string' ? JSON.parse(u) : u; } catch (e) { S.user = null; }
  if (!S.user) return false;
  S.token = t;
  return true;
}
function roleNow() { return (S.user && S.user.role) || 'GUEST'; }
function initForm() { return $('.side-brand small'); }

