  dashboard: ['OWNER', 'ADMIN', 'KASIR', 'GUDANG', 'TEKNISI'],
  pos: ['OWNER', 'ADMIN', 'KASIR'],
  orders: ['OWNER', 'ADMIN', 'KASIR'],
  service: ['OWNER', 'ADMIN', 'KASIR', 'TEKNISI'],
  tradein: ['OWNER', 'ADMIN', 'KASIR', 'TEKNISI'],
  products: ['OWNER', 'ADMIN', 'GUDANG'],
  bundles: ['OWNER', 'ADMIN', 'GUDANG'],
  stock: ['OWNER', 'ADMIN', 'GUDANG', 'KASIR'],
  po: ['OWNER', 'ADMIN', 'GUDANG'],
  customers: ['OWNER', 'ADMIN', 'KASIR'],
  promo: ['OWNER', 'ADMIN'],
  content: ['OWNER', 'ADMIN'],
  staff: ['OWNER', 'ADMIN'],
  settings: ['OWNER', 'ADMIN'],
  audit: ['OWNER', 'ADMIN']
};
var PAGE_TITLE = {
  dashboard: 'Dashboard', pos: 'Kasir POS', orders: 'Transaksi & Pesanan', service: 'Papan Kerja Service',
  tradein: 'Tukar Tambah', products: 'Katalog Produk', bundles: 'Bundling PC Rakitan', stock: 'Stok & Opname',
  po: 'Pembelian (PO)', customers: 'CRM Pelanggan', promo: 'Promo & Voucher', content: 'Konten Situs',
  staff: 'Staf & Hak Akses', settings: 'Pengaturan Sistem', audit: 'Audit Trail'
};
function canSee(page) { var r = ROLES_PAGE[page] || []; return r.indexOf(roleNow()) > -1; }

/* ------------------------------ LOGIN ---------------------------------- */
var LOGIN_BG = null;
function showLogin() {
  var ls2 = $('#loginScreen');
  if (!LOGIN_BG) { var bg = ls2.querySelector('.hero-bg'); LOGIN_BG = bg ? bg.outerHTML : '<div class="hero-bg" style="position:absolute;inset:0"></div>'; }
  $('#appShell').classList.remove('on');
  ls2.style.display = 'flex';
  ls2.innerHTML = '';
  document.body.classList.add('no-scroll');
  ls2.insertAdjacentHTML('afterbegin', loginCard());
  var demo = apiDemo();
  $('#lgDemoHint').innerHTML = demo
    ? 'Mode <b>DEMO</b> aktif (API_URL belum diisi). PIN coba cepat: <b>123456</b> Owner · <b>1111</b> Kasir · <b>2222</b> Teknisi · <b>3333</b> Gudang.'
    : 'Hubungkan ke Google Spreadsheet melalui <b>CONFIG.API_URL</b>. Lupa PIN? Hubungi Owner untuk reset.';
  on($('#loginForm'), 'submit', function (e) { e.preventDefault(); doLogin(); });
  $$('#lgPad button').forEach(function (b) {
    on(b, 'click', function () {
      var k = b.getAttribute('data-k'), i = $('#lgPin');
      if (k === 'clear') i.value = '';
      else if (k === 'back') i.value = i.value.slice(0, -1);
      else if (i.value.length < 8) i.value += k;
      i.focus();
    });
  });
  on($('#lgBack'), 'click', function () { hideLogin(); });
  setTimeout(function () { $('#lgNama').focus(); }, 260);
}
function loginCard() {
  return LOGIN_BG +
    '<div class="card card-pad rv in" style="position:relative;width:100%;max-width:430px;border-radius:var(--r-2xl);padding:26px">' +
    '<div class="tc mb6"><span class="logo-mark" style="width:52px;height:52px;font-size:24px;margin:0 auto 12px">S</span>' +
    '<h2 style="font-size:21px">Masuk ke Sarinadinet POS</h2>' +
    '<p style="font-size:13px;color:var(--text-3);margin-top:6px">Gunakan PIN staf untuk mengakses kasir, gudang, dan back-office.</p></div>' +
    '<form id="loginForm" novalidate="novalidate">' +
    '<label class="field"><span class="lbl">Nama Staf</span>' +
    '<input autocomplete="off" class="inp" id="lgNama" placeholder="Kosongkan untuk deteksi otomatis" type="text"/></label>' +
    '<label class="field"><span class="lbl">PIN</span>' +
    '<input autocomplete="off" class="inp mono" id="lgPin" inputmode="numeric" maxlength="8" placeholder="••••••" ' +
    'style="letter-spacing:.35em;font-size:19px;font-weight:700" type="password"/>' +
    '<span class="hint" id="lgHint">4-8 digit. Hubungi Owner bila PIN terlupa.</span></label>' +
    '<div class="numpad mb4" id="lgPad">' +
    '<button data-k="1" type="button">1</button><button data-k="2" type="button">2</button><button data-k="3" type="button">3</button>' +
    '<button data-k="4" type="button">4</button><button data-k="5" type="button">5</button><button data-k="6" type="button">6</button>' +
    '<button data-k="7" type="button">7</button><button data-k="8" type="button">8</button><button data-k="9" type="button">9</button>' +
    '<button data-k="clear" type="button">C</button><button data-k="0" type="button">0</button>' +
    '<button data-k="back" type="button">⌫</button></div>' +
    '<button class="btn btn-primary btn-block btn-lg" id="lgBtn" type="submit">' + svgI('lock') + 'Masuk Sistem</button>' +
    '</form>' +
    '<div class="divider mt6"><span>atau</span></div>' +
    '<p style="font-size:12px;color:var(--text-3);line-height:1.6;text-align:center" id="lgDemoHint">—</p>' +
    '<button class="btn btn-ghost btn-block mt4" id="lgBack" type="button">' + svgI('arrowr') + 'Kembali ke Situs</button>' +
    '</div>';
}
function hideLogin() {
  $('#loginScreen').style.display = 'none';
  document.body.classList.remove('no-scroll');
}
function doLogin() {
  var nama = $('#lgNama').value.trim(), pin = $('#lgPin').value.trim();
  if (pin.length < 4) { toast('PIN minimal 4 digit', 'warn'); $('#lgPin').focus(); return; }
  call('auth.login', { nama: nama, pin: pin }, { btn: $('#lgBtn') }).then(function (res) {
    if (!res || !res.ok) return;
    setSession(res.data);
    S.settings = res.data.toko || S.settings;
    toast('Selamat bekerja, ' + S.user.nama + ' 👋', 'ok');
    hideLogin();
    enterApp();
  });
}
function logoutApp() {
  confirmBox('Keluar dari sistem?', 'Sesi Anda akan diakhiri. Keranjang yang belum dibayar tetap tersimpan.', function () {
    call('auth.logout', {}, { silent: true }).then(function () { });
    clearSession();
    $('#appShell').classList.remove('on');
    document.body.classList.remove('no-scroll');
    toast('Anda telah keluar. Sampai jumpa!', 'ok');
  }, 'Ya, Keluar');
}
function enterApp() {
  var shell = $('#appShell');
  shell.classList.add('on');
  document.body.classList.remove('no-scroll');
  $('#userName').textContent = S.user.nama;
  $('#userRole').textContent = (S.user.role || '') + ' · ' + ((DEMO.roleDesc && DEMO.roleDesc()[S.user.role]) || 'Staf');
  $('#userAv').textContent = initials(S.user.nama);
  $('#offlineChip').classList.toggle('hide', !apiDemo());
  $$('.side-link[data-page]').forEach(function (b) {
    b.classList.toggle('hide', !canSee(b.getAttribute('data-page')));
    on(b, 'click', function () { nav(b.getAttribute('data-page')); closeSide(); });
  });
  on($('#sideToggle'), 'click', function () { $('#sidebar').classList.toggle('open'); });
  on($('#sideScrim'), 'click', closeSide);
  on($('#appLogout'), 'click', logoutApp);
  on($('#appBackSite'), 'click', function () {
    $('#appShell').classList.remove('on');
    document.body.classList.remove('no-scroll');
    toast('Kembali ke situs publik. Sesi POS masih aktif.', 'ok');
  });
  on($('#appThemeBtn'), 'click', toggleTheme);
  on($('#appRefreshBtn'), 'click', function () { nav(S.page || 'dashboard', null, true); toast('Data dimuat ulang', 'ok'); });
  on(window, 'keydown', function (e) {
    if (e.key === 'Escape' && !$$('.modal.open').length) closeSide();
  });
  tickClock();
  var first = canSee('dashboard') ? 'dashboard' : 'pos';
  nav(first);
}
function closeSide() { var s = $('#sidebar'); if (s) s.classList.remove('open'); }
function tickClock() {
  var el = $('#appClock'); if (!el) return;
  function t() {
    var d = new Date();
    el.textContent = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'][d.getDay()] + ', ' + tgl(d) + ' · ' + jam(d);
  }
  t(); setInterval(t, 30000);
}

/* ------------------------------ ROUTER --------------------------------- */
var NAVSTACK = [];
function nav(page, param, force) {
  if (!page) page = 'dashboard';
  if (!canSee(page)) { toast('Peran ' + roleNow() + ' tidak memiliki akses ke halaman ini.', 'warn'); page = canSee('dashboard') ? 'dashboard' : 'pos'; }
  if (S.page === page && !force && !param && $('#viewBox').querySelector('.page[data-page]')) { refreshBadges(); return; }
  S.page = page; S.param = param || null;
  $('#pageTitle').textContent = PAGE_TITLE[page] || page;
  $$('.side-link[data-page]').forEach(function (b) { b.classList.toggle('on', b.getAttribute('data-page') === page); });
  window.scrollTo(0, 0);
  var box = $('#viewBox');
  box.innerHTML = '<div class="page" data-page="' + page + '">' + pageSkeleton() + '</div>';
  var fn = window['page_' + page];
  if (typeof fn === 'function') {
    Promise.resolve().then(function () { return fn(param); }).catch(function (e) {
      box.innerHTML = '<div class="page">' + emptyState('Gagal memuat halaman: ' + (e.message || e), 'alert') + '</div>';
    });
  } else {
    box.innerHTML = '<div class="page">' + emptyState('Halaman belum tersedia.', 'alert') + '</div>';
  }
  refreshBadges();
}
function pageSkeleton() {
  return '<div class="page-head"><div><h1>Memuat…</h1><p>Menyiapkan data dari server</p></div></div>' +
    '<div class="kpi-grid">' + [1, 2, 3, 4].map(function () { return '<div class="kpi"><div class="sk sk-line" style="width:60%"></div><div class="sk sk-line"></div></div>'; }).join('') + '</div>' +
    '<div class="panel mt6"><div class="panel-body"><div class="sk" style="height:210px"></div></div></div>';
}
function refreshBadges() {
  if (!S.user) return;
  call('dash.stats', {}, { silent: true }).then(function (res) {
    if (!res || !res.ok) return;
    var d = res.data;
    var lowN = (d.stok_rendah || []).length || (d.inventori && d.inventori.rendah) || 0;
    setBadge('#sideLowCnt', lowN);
    setBadge('#sideSvcCnt', (d.service && d.service.aktif) || 0);
    setBadge('#sideTiCnt', (d.tradein && d.tradein.baru) || 0);
    setBadge('#sideCartCnt', sum(S.posCart || [], function (i) { return 1; }));
  });
}
function setBadge(sel, n) { var b = $(sel); if (!b) return; b.textContent = n; b.classList.toggle('hide', !num(n)); }

/* =========================== 10. DASHBOARD ============================== */
function page_dashboard() {
  return Promise.all([
    call('dash.stats', {}, { silent: true }),
    call('dash.charts', {}, { silent: true }),
    call('order.list', { limit: 6 }, { silent: true }),
    call('stock.low', {}, { silent: true })
  ]).then(function (r) {
    var st = (r[0] && r[0].data) || {};
    var ch = (r[1] && r[1].data) || {};
    var or = (r[2] && r[2].data) || [];
    var low = (r[3] && r[3].data) || [];
    S.dash = { st: st, ch: ch };
    var hi = st.hari_ini || {}, km = st.kemarin || {}, bl = st.bulan_ini || {}, inv = st.inventori || {};
    var delta = function (a, b) {
      if (!b) return ['flat', '—'];
      var p = Math.round(((a - b) / b) * 100);
      return [p >= 0 ? 'up' : 'down', (p >= 0 ? '+' : '') + p + '% vs kemarin'];
    };
    var d1 = delta(num(hi.omzet), num(km.omzet));
    var d2 = delta(num(hi.trx), num(km.trx));
    var d3 = delta(num(hi.laba), num(km.laba));
    function kpi(ic, color, lbl, val, delta, sub) {
      return '<div class="kpi rv in"><div class="top"><span class="ic" style="background:' + color + '">' + svgI(ic) + '</span>' +
        '<span class="delta ' + delta[0] + '">' + delta[1] + '</span></div>' +
        '<div class="lbl">' + lbl + '</div><div class="val">' + val + '</div>' +
        '<div style="font-size:11.8px;color:var(--text-3)">' + sub + '</div></div>';
    }
    var html = '<div class="page">' +
      '<div class="page-head"><div><h1>Selamat datang, ' + esc((S.user.nama || '').split(' ')[0]) + ' 👋</h1>' +
      '<p>Ringkasan operasional ' + esc((S.settings || {}).nama_toko || 'Sarinadinet') + ' hari ini (' + dayStr() + ').</p></div>' +
      '<div class="flex gap2 wrapf">' +
      '<button class="btn btn-ghost btn-sm" data-go="pos" type="button">' + svgI('wallet') + 'Buka POS</button>' +
      '<button class="btn btn-primary btn-sm" data-act="dash-refresh" type="button">' + svgI('refresh') + 'Segarkan</button></div></div>' +
      '<div class="kpi-grid">' +
      kpi('trend', 'var(--grad-brand)', 'Omzet Hari Ini', rp(num(hi.omzet)), d1, hi.trx + ' transaksi · rata-rata ' + rp(num(hi.rata))) +
      kpi('receipt', 'linear-gradient(135deg,#8b5cf6,#7c3aed)', 'Transaksi', int(num(hi.trx)), d2, int(num(hi.qty)) + ' unit barang terjual') +
      kpi('chart', 'linear-gradient(135deg,#10b981,#059669)', 'Laba Kotor', rp(num(hi.laba)), d3, 'Margin ' + (hi.margin_pct || 0) + '%') +
      kpi('package', 'linear-gradient(135deg,#f59e0b,#d97706)', 'Nilai Inventori', rp(num(inv.nilai_modal)), ['flat', int(num(inv.sku)) + ' SKU aktif'], int(num(inv.unit)) + ' unit stok') +
      '</div>' +
      '<div class="grid-dash w2 mt6">' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Tren Penjualan 14 Hari</h3><p>Omzet vs laba kotor harian</p></div>' +
      '<span class="chip">Bulan ini ' + rp(num(bl.omzet)) + '</span></div>' +
      '<div class="panel-body"><div class="chart-wrap" style="height:280px"><canvas id="chTren"></canvas></div></div></div>' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Metode Pembayaran</h3><p>Distribusi nilai transaksi</p></div></div>' +
      '<div class="panel-body"><div class="chart-wrap" style="height:280px"><canvas id="chMetode"></canvas></div></div></div>' +
      '</div>' +
      '<div class="grid-dash w3 mt6">' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Kategori Terlaris</h3><p>Berdasarkan nilai penjualan</p></div></div>' +
      '<div class="panel-body"><div class="chart-wrap" style="height:250px"><canvas id="chKategori"></canvas></div></div></div>' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Produk Terlaris</h3><p>Top 8 berdasarkan unit terjual</p></div></div>' +
      '<div class="panel-body tight"><div class="list-plain">' + ((ch.top_produk || []).length
        ? ch.top_produk.map(function (p, i) {
            return '<div class="list-row"><span class="num-badge">' + (i + 1) + '</span>' +
              '<div style="flex:1;min-width:0"><div class="ttl">' + esc(p.nama) + '</div>' +
              '<div class="sub">' + p.qty + ' unit · omzet ' + rp(p.omzet) + '</div></div>' +
              '<span style="font-size:12.5px;font-weight:750;color:var(--emerald-600)">' + rp(p.laba) + '</span></div>';
          }).join('') : emptyState('Belum ada penjualan tercatat.', 'chart')) + '</div></div></div>' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Performa Staf</h3><p>Total omzet per kasir</p></div></div>' +
      '<div class="panel-body tight"><div class="list-plain">' + ((ch.staf || []).length
        ? ch.staf.slice(0, 6).map(function (s0) {
            return '<div class="list-row"><span class="av-sm">' + initials(s0.nama) + '</span>' +
              '<div style="flex:1"><div class="ttl">' + esc(s0.nama) + '</div><div class="sub">' + s0.trx + ' transaksi</div></div>' +
              '<span style="font-size:12.5px;font-weight:750">' + rp(s0.omzet) + '</span></div>';
          }).join('') : emptyState('Belum ada transaksi staf.', 'users')) + '</div></div></div>' +
      '</div>' +
      '<div class="grid-dash w2 mt6">' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Peringatan Stok Rendah</h3><p>' + low.length + ' produk perlu segera ditambah</p></div>' +
      '<button class="btn btn-ghost btn-sm" data-go="po" type="button">Buat PO</button></div>' +
      '<div class="panel-body tight"><div class="list-plain">' + (low.length
        ? low.slice(0, 7).map(function (p) {
            return '<div class="list-row"><span class="av-sm" style="background:var(--surface-2);font-size:0">' +
              (p.gambar ? '<img alt="" src="' + esc(p.gambar) + '" style="width:100%;height:100%;object-fit:cover;border-radius:inherit"/>' : svgI('box')) + '</span>' +
              '<div style="flex:1;min-width:0"><div class="ttl">' + esc(p.nama) + '</div><div class="sub">' + esc(p.sku) + ' · min ' + (p.stok_min || 3) + '</div></div>' +
              '<span class="chip ' + (p.habis ? 'chip-rose' : 'chip-amber') + '">' + (p.habis ? 'HABIS' : 'Sisa ' + p.stok) + '</span></div>';
          }).join('') : emptyState('Semua stok dalam kondisi aman 👍', 'check')) + '</div></div></div>' +
      '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Transaksi Terbaru</h3><p>6 pesanan terakhir</p></div>' +
      '<button class="btn btn-ghost btn-sm" data-go="orders" type="button">Lihat semua</button></div>' +
      '<div class="panel-body tight"><div class="list-plain">' + (or.length
        ? or.map(function (o) {
            return '<div class="list-row" data-order="' + esc(o.id) + '" style="cursor:pointer"><span class="av-sm" style="background:var(--brand-50);color:var(--brand-700)">' + svgI('receipt') + '</span>' +
              '<div style="flex:1;min-width:0"><div class="ttl">' + esc(o.id) + ' · ' + esc(o.nama) + '</div>' +
              '<div class="sub">' + esc(o.tanggal) + ' · ' + esc(o.metode) + '</div></div>' +
              '<div style="text-align:right"><div style="font-size:12.5px;font-weight:750">' + rp(o.total) + '</div>' +
              '<span class="chip ' + (o.status === 'LUNAS' ? 'chip-emerald' : o.status === 'VOID' ? 'chip-rose' : 'chip-amber') + '" style="font-size:10px">' + esc(o.status) + '</span></div></div>';
          }).join('') : emptyState('Belum ada transaksi.', 'receipt')) + '</div></div></div>' +
      '</div></div>';
    $('#viewBox').innerHTML = html;
    $$('#viewBox [data-go]').forEach(function (b) { on(b, 'click', function () { nav(b.getAttribute('data-go')); }); });
    on($('[data-act="dash-refresh"]'), 'click', function () { nav('dashboard', null, true); });
    $$('#viewBox [data-order]').forEach(function (r) { on(r, 'click', function () { openOrderDetail(r.getAttribute('data-order')); }); });
    loadChartJS().then(function () { drawCharts(); });
  });
}

var CHART_READY = null;
function loadChartJS() {
  if (window.Chart) return Promise.resolve(true);
  if (CHART_READY) return CHART_READY;
  CHART_READY = new Promise(function (res) {
    var s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js';
    s.onload = function () { res(true); };
    s.onerror = function () { res(false); };
    document.head.appendChild(s);
    setTimeout(function () { res(!!window.Chart); }, 6000);
  });
  return CHART_READY;
}
function cssVar(n, fb) {
  var v = getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  return v || fb;
}
function drawCharts() {
  if (!window.Chart || !S.dash) return;
  var ch = S.dash.ch, c = window.Chart;
  var gr = cssVar('--grad-brand', '#2563eb');
  var txt = cssVar('--text-3', '#64748b'), grid = 'rgba(120,130,150,.13)';
  c.defaults.font.family = cssVar('--f-body', 'Inter, system-ui, sans-serif');
  c.defaults.font.size = 11.5;
  ['chTren', 'chMetode', 'chKategori'].forEach(function (id) {
    var ex = c.getChart(id); if (ex) ex.destroy();
  });
  var t = $('#chTren');
  if (t) {
    var ctx = t.getContext('2d');
    var g = ctx.createLinearGradient(0, 0, 0, 280);
    g.addColorStop(0, 'rgba(37,99,235,.34)');
    g.addColorStop(1, 'rgba(37,99,235,0)');
    new c(ctx, {
      type: 'line',
      data: {
        labels: ch.tren.labels,
        datasets: [
          { label: 'Omzet', data: ch.tren.data.map(function (x) { return x.omzet; }), borderColor: '#2563eb', backgroundColor: g, fill: true, tension: .38, borderWidth: 2.4, pointRadius: 0, pointHoverRadius: 5 },
          { label: 'Laba', data: ch.tren.data.map(function (x) { return x.laba; }), borderColor: '#10b981', backgroundColor: 'transparent', tension: .38, borderWidth: 2, borderDash: [5, 4], pointRadius: 0, pointHoverRadius: 5 }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false, interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: { position: 'bottom', labels: { boxWidth: 10, boxHeight: 10, usePointStyle: true, padding: 14, color: txt } },
          tooltip: { callbacks: { label: function (x) { return x.dataset.label + ': ' + rp(x.parsed.y); } }, backgroundColor: 'rgba(9,14,26,.92)', padding: 11, cornerRadius: 10, displayColors: false }
        },
        scales: {
          x: { grid: { display: false }, ticks: { color: txt, maxRotation: 0, autoSkipPadding: 12 } },
          y: { grid: { color: grid }, border: { display: false }, ticks: { color: txt, callback: function (v) { return rpS(v); } } }
        }
      }
    });
  }
  var m = $('#chMetode');
  if (m) {
    new c(m, {
      type: 'doughnut',
      data: {
        labels: (ch.metode || []).map(function (x) { return x.label; }),
        datasets: [{ data: (ch.metode || []).map(function (x) { return x.value; }),
          backgroundColor: ['#2563eb', '#8b5cf6', '#10b981', '#f59e0b', '#f43f5e', '#06b6d4', '#64748b'], borderWidth: 0, hoverOffset: 8 }]
      },
      options: {
        responsive: true, maintainAspectRatio: false, cutout: '62%',
        plugins: {
          legend: { position: 'bottom', labels: { boxWidth: 9, boxHeight: 9, usePointStyle: true, padding: 12, color: txt } },
          tooltip: { callbacks: { label: function (x) { return x.label + ': ' + rp(x.parsed); } }, backgroundColor: 'rgba(9,14,26,.92)', cornerRadius: 10, padding: 11 }
        }
      }
    });
  }
  var k = $('#chKategori');
  if (k) {
    new c(k, {
      type: 'bar',
      data: {
        labels: (ch.kategori || []).map(function (x) { return x.label; }),
        datasets: [{ label: 'Penjualan', data: (ch.kategori || []).map(function (x) { return x.value; }),
          backgroundColor: ['#2563eb', '#8b5cf6', '#10b981', '#f59e0b', '#06b6d4', '#f43f5e'], borderRadius: 9, maxBarThickness: 42 }]
      },
      options: {
        responsive: true, maintainAspectRatio: false, indexAxis: 'y',
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (x) { return rp(x.parsed.x); } }, backgroundColor: 'rgba(9,14,26,.92)', cornerRadius: 10, padding: 11, displayColors: false } },
        scales: { x: { grid: { color: grid }, border: { display: false }, ticks: { color: txt, callback: function (v) { return rpS(v); } } }, y: { grid: { display: false }, ticks: { color: txt } } }
      }
    });
  }
}

/* =========================== 11. KASIR (POS) ============================ */
var POS = { q: '', tab: 'ALL', res: [], cart: [], metode: 'TUNAI', bayar: 0, promo: null, manual: 0, cust: null, scan: '', scanT: 0, tunaiPas: true };

function page_pos() {
  POS.cart = POS.cart.length ? POS.cart : [];
  $('#viewBox').innerHTML =
    '<div class="page" style="height:calc(100vh - 110px);display:flex;flex-direction:column">' +
    '<div class="page-head" style="margin-bottom:12px"><div><h1>Kasir POS</h1>' +
    '<p>Scan barcode, cari SKU, atau ketuk produk. Tekan <b>F2</b> untuk cari, <b>F9</b> untuk bayar.</p></div>' +
    '<div class="flex gap2 wrapf">' +
    '<button class="btn btn-ghost btn-sm" id="posHoldBtn" type="button">' + svgI('clipboard') + 'Simpan / Ambil</button>' +
    '<button class="btn btn-ghost btn-sm" id="posClearBtn" type="button">' + svgI('trash') + 'Kosongkan</button>' +
    '</div></div>' +
    '<div class="pos-wrap" style="grid-template-columns:1fr;flex:1;min-height:0">' +
    '<div class="pos-left">' +
    '<div class="pos-search"><div class="search-box">' + svgI('search') +
    '<input autocomplete="off" class="inp" id="posSearch" placeholder="Scan barcode / ketik nama atau SKU produk…" type="text"/>' +
    '</div><span class="kbd" style="position:absolute;right:12px;top:-26px">F2</span></div>' +
    '<div class="pos-tabs" id="posTabs">' + ['ALL', 'Laptop', 'PC Rakitan', 'Komponen', 'Monitor', 'Aksesoris'].map(function (k) {
      return '<button class="pos-tab ' + (k === 'ALL' ? 'on' : '') + '" data-tab="' + k + '" type="button">' + (k === 'ALL' ? 'Semua Produk' : k) + '</button>';
    }).join('') + '</div>' +
    '<div class="pos-grid" id="posGrid"></div>' +
    '</div>' +
    '<aside class="pos-right" id="posRight">' +
    '<div class="cart-head"><h3>Keranjang</h3>' +
    '<span class="chip" id="posItemCnt">0 item</span>' +
    '<button class="mini-btn danger" id="posClearMini" type="button" aria-label="Kosongkan">' + svgI('trash') + '</button></div>' +
    '<div class="cart-lines" id="posLines"></div>' +
    '<div class="cart-foot" id="posFoot"></div>' +
    '</aside></div></div>';
  on($('#posSearch'), 'input', debounce(function (e) { POS.q = e.target.value.trim(); posLoadGrid(); }, 260));
  on($('#posSearch'), 'keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      var v = e.target.value.trim();
      if (!v) return;
      call('pos.lookup', { q: v, limit: 1 }, { silent: true }).then(function (r) {
        var it = r && r.data && r.data[0];
        if (it && (String(it.sku).toLowerCase() === v.toLowerCase())) { posAdd(it); e.target.value = ''; POS.q = ''; posLoadGrid(); }
        else { toast('Kode “' + v + '” tidak ditemukan. Tekan Enter lagi untuk melihat hasil pencarian.', 'warn'); posLoadGrid(); }
      });
    }
  });
  on($('#posTabs'), 'click', function (e) {
    var t = e.target.closest('.pos-tab'); if (!t) return;
    POS.tab = t.getAttribute('data-tab');
    $$('#posTabs .pos-tab').forEach(function (x) { x.classList.toggle('on', x === t); });
    posLoadGrid();
  });
  on($('#posGrid'), 'click', function (e) {
    var b = e.target.closest('[data-sku]'); if (!b) return;
    var it = POS.res.filter(function (x) { return x.sku === b.getAttribute('data-sku'); })[0];
    if (it) posAdd(it);
  });
  on($('#posHoldBtn'), 'click', posHoldDialog);
  on($('#posClearBtn'), 'click', posClearAll);
  on($('#posClearMini'), 'click', posClearAll);
  posLoadGrid();
  posRenderCart();
  posScanner();
  setTimeout(function () { var s = $('#posSearch'); if (s) s.focus(); }, 200);
  if (!S._posHotkeys) { on(window, 'keydown', posHotkeys); S._posHotkeys = true; }
}
function posHotkeys(e) {
  if (S.page !== 'pos') return;
  if (e.key === 'F2') { e.preventDefault(); var s = $('#posSearch'); if (s) { s.focus(); s.select(); } }
  if (e.key === 'F9') { e.preventDefault(); posCheckout(); }
}
function posScanner() {
  if (S._scannerOn) return;
  S._scannerOn = true;
  on(window, 'keydown', function (e) {
    if (S.page !== 'pos') return;
    var tag = (document.activeElement || {}).tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
    if ($$('.modal.open').length) return;
    var now = Date.now();
    if (now - POS.scanT > 120) POS.scan = '';
    POS.scanT = now;
    if (e.key === 'Enter') {
      var code = POS.scan.trim();
      POS.scan = '';
      if (code.length >= 4) { e.preventDefault(); posScanAdd(code); }
      return;
    }
    if (e.key.length === 1) POS.scan += e.key;
  });
}
function posScanAdd(code) {
  call('pos.lookup', { q: code, limit: 1 }, { silent: true }).then(function (r) {
    var it = r && r.data && r.data[0];
    if (it && String(it.sku).toLowerCase() === code.toLowerCase()) { posAdd(it); toast('Scan: ' + it.nama, 'ok'); }
    else { toast('Barcode “' + code + '” tidak dikenali', 'warn'); }
  });
}
function posLoadGrid() {
  var grid = $('#posGrid');
  if (!grid) return;
  grid.innerHTML = [1, 2, 3, 4, 5, 6].map(function () { return '<div class="sk" style="height:120px"></div>'; }).join('');
  call('pos.lookup', { q: POS.q, limit: 60 }, { silent: true }).then(function (r) {
    if (!grid.parentNode) return;
    var list = (r && r.data) || [];
    if (POS.tab !== 'ALL') list = list.filter(function (x) { return x.kategori === POS.tab; });
    POS.res = list;
    if (!list.length) { grid.innerHTML = emptyState('Produk tidak ditemukan. Coba kata kunci lain atau tambah produk baru.', 'package'); return; }
    grid.innerHTML = list.map(function (p) {
      var bisa = p.tipe === 'BUNDLE' ? (p.max_buildable !== undefined ? p.max_buildable : p.stok) : p.stok;
      return '<button class="pos-item ' + (bisa <= 0 ? 'dis' : '') + '" data-sku="' + esc(p.sku) + '" type="button">' +
        (p.gambar ? '<img alt="" class="thumb" loading="lazy" src="' + esc(p.gambar) + '"/>' : '<div class="thumb" style="display:grid;place-items:center;color:var(--ink-300)">' + svgI('laptop') + '</div>') +
        '<span class="nm">' + esc(p.nama) + '</span>' +
        '<span class="pr">' + rp(p.harga) + '</span>' +
        '<span class="st">' + esc(p.sku) + ' · ' + (bisa > 0 ? 'stok ' + bisa : 'habis') + (p.tipe === 'BUNDLE' ? ' (rakitan)' : '') + '</span></button>';
    }).join('');
  });
}
function posAdd(p) {
  var existing = POS.cart.filter(function (x) { return x.sku === p.sku; })[0];
  var max = p.tipe === 'BUNDLE' ? (p.max_buildable !== undefined ? p.max_buildable : p.stok) : p.stok;
  if (existing) {
    if (existing.qty + 1 > max) { toast('Stok ' + p.nama + ' hanya ' + max + ' unit', 'warn'); return; }
    existing.qty++;
  } else {
    if (max <= 0) { toast(p.nama + ' sedang habis', 'warn'); return; }
    POS.cart.push({ sku: p.sku, nama: p.nama, harga: num(p.harga), qty: 1, stok: max, kategori: p.kategori, tipe: p.tipe, hpp: num(p.hpp) });
  }
  posRenderCart();
  var ln = $('#posLines');
  if (ln) ln.scrollTop = 0;
  onPosChange();
}
function posQty(sku, d) {
  var it = POS.cart.filter(function (x) { return x.sku === sku; })[0]; if (!it) return;
  it.qty += d;
  if (it.qty > it.stok) { it.qty = it.stok; toast('Sisa stok ' + it.stok + ' unit', 'warn'); }
  if (it.qty <= 0) POS.cart = POS.cart.filter(function (x) { return x.sku !== sku; });
  posRenderCart(); onPosChange();
}
function posSetQty(sku, v) {
  var it = POS.cart.filter(function (x) { return x.sku === sku; })[0]; if (!it) return;
  it.qty = clamp(num(v), 0, it.stok);
  if (!it.qty) POS.cart = POS.cart.filter(function (x) { return x.sku !== sku; });
  posRenderCart(); onPosChange();
}
function posClearAll() {
  if (!POS.cart.length) return;
  confirmBox('Kosongkan keranjang?', POS.cart.length + ' jenis produk akan dihapus dari keranjang kasir.', function () {
    POS.cart = []; POS.promo = null; POS.manual = 0; POS.bayar = 0; POS.cust = null;
    posRenderCart(); onPosChange(); toast('Keranjang dikosongkan', 'warn');
  }, 'Ya, Kosongkan');
}
function posSubtotal() { return sum(POS.cart, function (i) { return i.harga * i.qty; }); }
function posTotals() {
  var sub = posSubtotal();
  var promo = POS.promo && POS.promo.valid ? num(POS.promo.diskon) : 0;
  var man = clamp(num(POS.manual), 0, Math.max(0, sub - promo));
  var total = Math.max(0, sub - promo - man);
  var kembali = num(POS.bayar) - total;
  return { sub: sub, promo: promo, manual: man, total: total, kembali: kembali };
}
function posRenderCart() {
  var lines = $('#posLines'), foot = $('#posFoot');
  if (!lines) return;
  var cnt = sum(POS.cart, function (i) { return i.qty; });
  $('#posItemCnt').textContent = cnt + ' item';
  if (!POS.cart.length) {
    lines.innerHTML = '<div class="empty-mini">' + svgI('cart') + '<p style="font-weight:650;margin-bottom:4px">Keranjang kosong</p>' +
      '<p>Scan barcode atau pilih produk untuk memulai transaksi.</p></div>';
  } else {
    lines.innerHTML = POS.cart.map(function (i) {
      return '<div class="cart-line" data-sku="' + esc(i.sku) + '">' +
        '<div class="info"><div class="nm">' + esc(i.nama) + '</div>' +
        '<div class="pr">' + rp(i.harga) + ' × ' + i.qty + ' = <b>' + rp(i.harga * i.qty) + '</b></div>' +
        '<div class="mt4"><span class="qty-ctrl"><button data-d="-1" type="button">' + svgI('minus') + '</button>' +
        '<input data-q type="number" value="' + i.qty + '" style="width:38px"/>' +
        '<button data-d="1" type="button">' + svgI('plus') + '</button></span></div></div>' +
        '<button class="mini-btn danger" data-rm="1" type="button" aria-label="Hapus">' + svgI('trash') + '</button></div>';
    }).join('');
    $$('#posLines [data-d]').forEach(function (b) {
      on(b, 'click', function () { var sku = b.closest('[data-sku]').getAttribute('data-sku'); posQty(sku, num(b.getAttribute('data-d'))); });
    });
    $$('#posLines [data-q]').forEach(function (i2) {
      on(i2, 'change', function () { posSetQty(i2.closest('[data-sku]').getAttribute('data-sku'), i2.value); });
    });
    $$('#posLines [data-rm]').forEach(function (b) {
      on(b, 'click', function () { var sku = b.closest('[data-sku]').getAttribute('data-sku'); posSetQty(sku, 0); });
    });
  }
  var t = posTotals();
  foot.innerHTML =
    '<div class="flex between center mb2"><span class="chip" id="posCustChip" style="cursor:pointer">' +
    svgI('user') + (POS.cust ? esc(POS.cust.nama) : 'Pelanggan Umum') + '</span>' +
    '<button class="mini-btn" id="posPromoBtn" type="button" data-tip="Kode promo">' + svgI('tag') + '</button></div>' +
    '<div class="tot-row"><span>Subtotal</span><span class="v">' + rp(t.sub) + '</span></div>' +
    (t.promo ? '<div class="tot-row" style="color:var(--emerald-600)"><span>Promo ' + esc(POS.promo.kode) + '</span><span class="v">- ' + rp(t.promo) + '</span></div>' : '') +
    (t.manual ? '<div class="tot-row" style="color:var(--emerald-600)"><span>Diskon manual</span><span class="v">- ' + rp(t.manual) + '</span></div>' : '') +
    '<div class="tot-row grand"><span>TOTAL</span><span class="v">' + rp(t.total) + '</span></div>' +
    '<div class="pay-methods mt4" id="posMethods">' + [['TUNAI', 'Tunai'], ['TRANSFER', 'Transfer'], ['QRIS', 'QRIS'], ['DEBIT', 'Debit'], ['KREDIT', 'Kredit'], ['CICILAN', 'Cicilan']].map(function (m) {
      return '<button class="pay-m ' + (POS.metode === m[0] ? 'on' : '') + '" data-m="' + m[0] + '" type="button">' + m[1] + '</button>';
    }).join('') + '</div>' +
    (POS.metode === 'TUNAI' ? '<div class="mt4"><div class="quick-cash mb2">' +
      [50000, 100000, 200000, 500000, 1000000].map(function (v) { return '<button data-cash="' + v + '" type="button">' + rpS(v) + '</button>'; }).join('') +
      '<button data-cash="pas" type="button">Uang Pas</button></div>' +
      '<div class="inp-group mb2"><span class="addon">Rp</span><input class="inp num" id="posBayar" inputmode="numeric" placeholder="Nominal diterima" type="number" value="' + (POS.bayar || '') + '"/></div>' +
      '<div class="change-box ' + (t.kembali < 0 ? 'less' : '') + '" id="posChange"><span class="lbl">' + (t.kembali < 0 ? 'Kurang bayar' : 'Kembalian') + '</span>' +
      '<span class="v">' + rp(Math.abs(t.kembali)) + '</span></div></div>' : '') +
    '<button class="btn btn-primary btn-block btn-lg mt4" id="posPayBtn" type="button"' + (POS.cart.length ? '' : ' disabled="disabled"') + '>' +
    svgI('checkc') + 'Bayar ' + rp(t.total) + '</button>' +
    '<div class="flex gap2 mt2"><button class="btn btn-ghost btn-sm" id="posHoldSaveBtn" style="flex:1" type="button">' + svgI('pause') + 'Hold</button>' +
    '<button class="btn btn-ghost btn-sm" id="posPreorderBtn" style="flex:1" type="button">' + svgI('clock') + 'Pre-Order</button></div>';
  on($('#posMethods'), 'click', function (e) {
    var b = e.target.closest('.pay-m'); if (!b) return;
    POS.metode = b.getAttribute('data-m'); posRenderCart();
  });
  $$('#posFoot [data-cash]').forEach(function (b) {
    on(b, 'click', function () {
      var v = b.getAttribute('data-cash');
      POS.bayar = v === 'pas' ? posTotals().total : num(v);
      posRenderCart();
    });
  });
  var bayarInp = $('#posBayar');
  if (bayarInp) on(bayarInp, 'input', function () {
    POS.bayar = num(bayarInp.value);
    var t2 = posTotals(), box = $('#posChange');
    if (box) {
      box.classList.toggle('less', t2.kembali < 0);
      $('.lbl', box).textContent = t2.kembali < 0 ? 'Kurang bayar' : 'Kembalian';
      $('.v', box).textContent = rp(Math.abs(t2.kembali));
    }
  });
  on($('#posPayBtn'), 'click', posCheckout);
  on($('#posHoldSaveBtn'), 'click', posHoldSave);
  on($('#posPreorderBtn'), 'click', function () { posCheckout('PRE_ORDER'); });
  on($('#posPromoBtn'), 'click', posPromoDialog);
  on($('#posCustChip'), 'click', posCustomerDialog);
}
function onPosChange() { setBadge('#sideCartCnt', sum(POS.cart, function (i) { return i.qty; })); }
function posPromoDialog() {
  formModal({
    title: 'Kode Promo & Diskon Manual', sub: 'Subtotal saat ini ' + rp(posSubtotal()), size: 'sm',
    fields: [
      { k: 'kode', l: 'Kode Promo', t: 'text', ph: 'HEMAT10', def: POS.promo ? POS.promo.kode : '' },
      { k: 'manual', l: 'Diskon Manual (Rp)', t: 'money', def: POS.manual, hint: 'Potongan tambahan di luar promo, mis. nego pembulatan.' }
    ],
    submitLabel: 'Terapkan',
    onSubmit: function (v, act) {
      POS.manual = num(v.manual);
      var kode = String(v.kode || '').toUpperCase().trim();
      if (!kode) { POS.promo = null; act.close(); posRenderCart(); toast('Diskon manual diperbarui', 'ok'); return; }
      call('public.promo.check', { kode: kode, subtotal: posSubtotal() }, { btn: act.button }).then(function (r) {
        var d = r && r.data;
        if (d && d.valid) { POS.promo = d; toast('Promo ' + d.kode + ' aktif — hemat ' + rp(d.diskon), 'ok'); }
        else { POS.promo = null; toast((d && (d.pesan || d.keterangan)) || 'Kode promo tidak valid', 'err'); }
        act.close(); posRenderCart();
      });
    }
  });
}
function posCustomerDialog() {
  call('customer.list', { q: '', limit: 40 }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    var opts = [{ v: '', l: '— Pelanggan Umum —' }].concat(list.map(function (c) {
      return { v: c.id, l: c.nama + ' · ' + c.wa + ' · ' + c.tier };
    }));
    formModal({
      title: 'Pilih Pelanggan', sub: 'Poin dan tier otomatis diperbarui setelah pembayaran.', size: 'sm',
      fields: [{ k: 'customer_id', l: 'Pelanggan', t: 'select', opts: opts, def: POS.cust ? POS.cust.id : '' }],
      submitLabel: 'Pilih',
      onSubmit: function (v, act) {
        if (!v.customer_id) { POS.cust = null; act.close(); posRenderCart(); return; }
        call('customer.get', { id: v.customer_id }, { silent: true }).then(function (r2) {
          POS.cust = (r2 && r2.data) || null;
          act.close(); posRenderCart();
          if (POS.cust) toast('Pelanggan: ' + POS.cust.nama + ' · poin ' + POS.cust.poin, 'ok');
        });
      }
    });
  });
}

function posCheckout(tipe) {
  if (!POS.cart.length) { toast('Keranjang masih kosong', 'warn'); return; }
  var t = posTotals();
  if (POS.metode === 'TUNAI' && num(POS.bayar) < t.total && !POS.tunaiPas) {
    POS.bayar = t.total;
  }
  var payload = {
    tipe: tipe || 'JUAL', items: POS.cart.map(function (i) { return { sku: i.sku, qty: i.qty }; }),
    metode: POS.metode, bayar: tipe === 'PRE_ORDER' ? 0 : (num(POS.bayar) || t.total),
    promo: POS.promo ? POS.promo.kode : '', diskon_manual: t.manual,
    nama: POS.cust ? POS.cust.nama : 'Pelanggan Umum', wa: POS.cust ? POS.cust.wa : '',
    customer_id: POS.cust ? POS.cust.id : '', poin_pakai: num(POS.poinPakai) || 0
  };
  call('pos.checkout', payload, { btn: $('#posPayBtn') }).then(function (res) {
    if (!res || !res.ok) return;
    var d = res.data;
    POS.cart = []; POS.promo = null; POS.manual = 0; POS.bayar = 0; POS.cust = null; POS.poinPakai = 0;
    posRenderCart(); onPosChange();
    showReceipt(d.order, d.struk, d.wa_struk);
    refreshBadges();
  });
}
function showReceipt(order, struk, waHref, sub) {
  $('#rcSub').textContent = order.id + ' · ' + order.nama + ' · ' + order.tanggal;
  $('#rcBody').innerHTML = '<pre class="struk-pre">' + esc(struk || DEMO.struk(order, S.settings || {})) + '</pre>';
  S._lastStruk = struk || DEMO.struk(order, S.settings || {});
  S._lastOrder = order;
  on($('#rcPrintBtn'), 'click', function () { printStruk(); });
  on($('#rcCopyBtn'), 'click', function () {
    copyText(S._lastStruk).then(function () { toast('Nota disalin ke clipboard', 'ok'); });
  });
  on($('#rcWaBtn'), 'click', function () {
    var link = waHref || waLink(order.wa || (S.settings || {}).wa, S._lastStruk);
    if (!order.wa) { toast('Pelanggan tanpa nomor WhatsApp — nota dibuka untuk dibagikan manual.', 'warn'); }
    window.open(link, '_blank');
  });
  openModal('mReceipt');
}
function printStruk() {
  var w = window.open('', '_blank', 'width=380,height=640');
  if (!w) { toast('Popup diblokir browser. Izinkan popup untuk mencetak nota.', 'warn'); return; }
  w.document.write('<html><head><title>Nota</title><style>body{margin:0;padding:10px;font-family:ui-monospace,Menlo,monospace;font-size:11.5px;color:#000}' +
    'pre{white-space:pre-wrap;word-break:break-word;margin:0;line-height:1.45}</style></head><body><pre>' +
    String(S._lastStruk || '').replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre></body></html>');
  w.document.close();
  setTimeout(function () { w.focus(); w.print(); }, 350);
}

/* --------------------------- HOLD CART --------------------------------- */
function posHoldSave() {
  if (!POS.cart.length) { toast('Keranjang kosong, tidak ada yang disimpan', 'warn'); return; }
  formModal({
    title: 'Simpan Keranjang (Hold)', sub: 'Transaksi dapat dilanjutkan kapan saja oleh kasir mana pun.', size: 'sm',
    fields: [
      { k: 'nama', l: 'Nama / Meja / Catatan Pelanggan', t: 'text', req: true, ph: 'Contoh: Pak Andi — ambil charger dulu', def: POS.cust ? POS.cust.nama : '' },
      { k: 'catatan', l: 'Keterangan Tambahan', t: 'text', ph: 'Opsional' }
    ],
    submitLabel: 'Simpan Keranjang',
    onSubmit: function (v, act) {
      call('pos.hold.save', { nama: v.nama, catatan: v.catatan, items: POS.cart, diskon: POS.manual, wa: POS.cust ? POS.cust.wa : '' }, { btn: act.button })
        .then(function (r) {
          if (!r || !r.ok) return;
          act.close();
          POS.cart = []; POS.promo = null; POS.manual = 0; POS.bayar = 0;
          posRenderCart(); onPosChange();
          toast('Keranjang disimpan sebagai ' + r.data.id, 'ok');
        });
    }
  });
}
function posHoldDialog() {
  call('pos.hold.list', {}, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    var html = '<div class="page-head" style="margin-bottom:14px"><div><h1>Keranjang Ditahan</h1>' +
      '<p>' + list.length + ' keranjang tersimpan. Ambil untuk melanjutkan transaksi.</p></div></div>';
    if (!list.length) html += emptyState('Belum ada keranjang yang ditahan. Gunakan tombol Hold pada kasir untuk menyimpan transaksi sementara.', 'clipboard');
    else html += '<div class="grid-dash w3">' + list.map(function (h) {
      return '<div class="panel"><div class="panel-body">' +
        '<div class="flex between center mb2"><span class="chip chip-amber">' + esc(h.id) + '</span><span style="font-size:11.5px;color:var(--text-3)">' + esc(h.tanggal) + '</span></div>' +
        '<h3 style="font-size:15px;margin-bottom:4px">' + esc(h.nama) + '</h3>' +
        '<p style="font-size:12.4px;color:var(--text-3);line-height:1.6;margin-bottom:10px">' + h.jumlah_item + ' item · kasir ' + esc(h.kasir) + (h.catatan ? ' · ' + esc(h.catatan) : '') + '</p>' +
        '<div class="flex gap2"><button class="btn btn-primary btn-sm" data-take="' + esc(h.id) + '" style="flex:1" type="button">Ambil</button>' +
        '<button class="mini-btn danger" data-del="' + esc(h.id) + '" type="button">' + svgI('trash') + '</button></div>' +
        '</div></div>';
    }).join('') + '</div>';
    formModal({ title: 'Simpan / Ambil Keranjang', sub: 'Hold cart', size: 'xl', fields: [{ k: 'x', t: 'custom', html: html }], submitLabel: 'Tutup', onSubmit: function (v, act) { act.close(); } });
    $$('#fmForm [data-take]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-take');
        var h = list.filter(function (x) { return x.id === id; })[0];
        closeModal('mForm');
        POS.cart = (h.items || []).map(function (i) { return Object.assign({}, i, { stok: i.stok || i.qty || 1, kategori: i.kategori || '' }); });
        POS.manual = num(h.diskon); POS.bayar = 0;
        posRenderCart(); onPosChange();
        call('pos.hold.delete', { id: id }, { silent: true });
        toast('Keranjang ' + id + ' diambil kembali', 'ok');
      });
    });
    $$('#fmForm [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-del');
        confirmBox('Hapus keranjang tersimpan?', 'Keranjang ' + id + ' akan dihapus permanen.', function () {
          call('pos.hold.delete', { id: id }, { silent: true }).then(function () { closeModal('mForm'); toast('Keranjang ' + id + ' dihapus', 'warn'); });
        }, 'Ya, Hapus');
      });
    });
  });
}

/* =========================== 12. TRANSAKSI ============================== */
var ORD = { q: '', status: 'ALL', tipe: 'ALL', dari: '', sampai: '', page: 1, limit: 15, pages: 1, total: 0 };

function page_orders(param) {
  if (param && param.q) ORD.q = param.q;
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Transaksi & Pesanan</h1><p>Riwayat penjualan, pelunasan, cetak nota, dan void (pembatalan).</p></div>' +
    '<div class="flex gap2 wrapf">' +
    '<button class="btn btn-ghost btn-sm" id="ordExport" type="button">' + svgI('download') + 'Ekspor CSV</button>' +
    '<button class="btn btn-primary btn-sm" data-go-pos="1" type="button">' + svgI('plus') + 'Transaksi Baru</button></div></div>' +
    '<div class="panel mb6"><div class="panel-body">' +
    '<div class="toolbar"><div class="search-box" style="flex:1;min-width:220px">' + svgI('search') +
    '<input class="inp" id="ordQ" placeholder="Cari kode invoice, nama pelanggan, WA, atau kasir…" type="text" value="' + esc(ORD.q) + '"/></div>' +
    '<select class="sel-mini" id="ordStatus">' + ['ALL', 'LUNAS', 'MENUNGGU', 'VOID'].map(function (s0) {
      return '<option value="' + s0 + '"' + (ORD.status === s0 ? ' selected="selected"' : '') + '>' + (s0 === 'ALL' ? 'Semua Status' : s0) + '</option>';
    }).join('') + '</select>' +
    '<select class="sel-mini" id="ordTipe">' + [['ALL', 'Semua Tipe'], ['JUAL', 'Penjualan'], ['PRE_ORDER', 'Pre-Order'], ['SERVICE', 'Service'], ['TRADEIN', 'Tukar Tambah']].map(function (x) {
      return '<option value="' + x[0] + '"' + (ORD.tipe === x[0] ? ' selected="selected"' : '') + '>' + x[1] + '</option>';
    }).join('') + '</select>' +
    '<input class="inp" id="ordDari" type="date" value="' + ORD.dari + '" style="max-width:150px"/>' +
    '<input class="inp" id="ordSampai" type="date" value="' + ORD.sampai + '" style="max-width:150px"/>' +
    '<button class="btn btn-ghost btn-sm" id="ordReset" type="button">' + svgI('undo') + 'Reset</button>' +
    '</div><div class="mt4 grid-dash w4" id="ordRingkas"></div></div></div>' +
    '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Daftar Transaksi</h3><p id="ordCount">Memuat…</p></div></div>' +
    '<div class="panel-body tight" id="ordTable"></div></div>' +
    '<div class="tc mt6" id="ordPager"></div></div>';
  on($('#ordQ'), 'input', debounce(function (e) { ORD.q = e.target.value.trim(); ORD.page = 1; loadOrders(); }, 300));
  on($('#ordStatus'), 'change', function (e) { ORD.status = e.target.value; ORD.page = 1; loadOrders(); });
  on($('#ordTipe'), 'change', function (e) { ORD.tipe = e.target.value; ORD.page = 1; loadOrders(); });
  on($('#ordDari'), 'change', function (e) { ORD.dari = e.target.value; ORD.page = 1; loadOrders(); });
  on($('#ordSampai'), 'change', function (e) { ORD.sampai = e.target.value; ORD.page = 1; loadOrders(); });
  on($('#ordReset'), 'click', function () {
    ORD = { q: '', status: 'ALL', tipe: 'ALL', dari: '', sampai: '', page: 1, limit: 15, pages: 1, total: 0 };
    nav('orders', null, true);
  });
  on($('#ordExport'), 'click', function () { exportOrdersCSV(); });
  $$('[data-go-pos]').forEach(function (b) { on(b, 'click', function () { nav('pos'); }); });
  return loadOrders();
}
function loadOrders() {
  var box = $('#ordTable');
  box.innerHTML = '<div style="padding:18px"><div class="sk sk-line"></div><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  return call('order.list', { q: ORD.q, status: ORD.status, tipe: ORD.tipe, dari: ORD.dari, sampai: ORD.sampai, page: ORD.page, limit: ORD.limit }, { silent: true })
    .then(function (res) {
      if (!res || !res.ok) { box.innerHTML = emptyState('Gagal memuat transaksi.', 'alert'); return; }
      var list = res.data || [], meta = res.meta || {}, rg = meta.ringkas || {};
      ORD.total = meta.total || list.length; ORD.pages = meta.pages || 1;
      $('#ordCount').innerHTML = '<strong>' + ORD.total + '</strong> transaksi ditemukan · halaman ' + (meta.page || 1) + '/' + (meta.pages || 1);
      $('#ordRingkas').innerHTML = [['Total Transaksi', int(rg.trx), 'receipt'], ['Omzet (tanpa void)', rp(rg.omzet), 'trend'],
        ['Sudah Lunas', int(rg.lunas), 'checkc'], ['Void', int(rg.void), 'alert']].map(function (k) {
        return '<div class="kpi" style="padding:14px"><div class="lbl">' + k[0] + '</div><div class="val" style="font-size:19px">' + k[1] + '</div></div>';
      }).join('');
      if (!list.length) { box.innerHTML = emptyState('Tidak ada transaksi sesuai filter. Coba ubah kata kunci atau rentang tanggal.', 'receipt'); $('#ordPager').innerHTML = ''; return; }
      S.ordList = list;
      box.innerHTML = '<div class="table-wrap"><table class="dt"><thead><tr>' +
        '<th>Invoice</th><th>Tanggal</th><th>Pelanggan</th><th class="num">Total</th><th>Metode</th><th>Status</th><th>Kasir</th><th></th>' +
        '</tr></thead><tbody>' + list.map(function (o) {
          return '<tr data-order="' + esc(o.id) + '">' +
            '<td><strong style="font-family:var(--f-mono);font-size:12.5px">' + esc(o.id) + '</strong>' +
            '<div style="font-size:11px;color:var(--text-3)">' + esc(o.tipe) + '</div></td>' +
            '<td style="font-size:12.4px;color:var(--text-2)">' + esc(o.tanggal) + '</td>' +
            '<td><div style="font-weight:650;font-size:13px">' + esc(o.nama) + '</div>' +
            (o.wa ? '<a href="' + waLink(o.wa, 'Halo ' + o.nama + ', terima kasih telah berbelanja.') + '" rel="noopener" target="_blank" style="font-size:11.5px;color:var(--brand-600)">' + esc(o.wa) + '</a>' : '') + '</td>' +
            '<td class="num" style="font-weight:750">' + rp(o.total) + '</td>' +
            '<td><span class="chip">' + esc(o.metode) + '</span></td>' +
            '<td><span class="chip ' + (o.status === 'LUNAS' ? 'chip-emerald' : o.status === 'VOID' ? 'chip-rose' : 'chip-amber') + '">' + esc(o.status) + '</span></td>' +
            '<td style="font-size:12.4px">' + esc(o.kasir) + '</td>' +
            '<td><div class="row-actions">' +
            '<button class="mini-btn" data-view="' + esc(o.id) + '" data-tip="Detail" type="button">' + svgI('eye') + '</button>' +
            '<button class="mini-btn" data-print="' + esc(o.id) + '" data-tip="Cetak nota" type="button">' + svgI('printer') + '</button>' +
            '</div></td></tr>';
        }).join('') + '</tbody></table></div>';
      $('#ordPager').innerHTML = ORD.pages > 1
        ? '<div class="pager"><button class="btn btn-ghost btn-sm" ' + (ORD.page <= 1 ? 'disabled="disabled"' : '') + ' data-pg="-1" type="button">' + svgI('chevl') + 'Sebelumnya</button>' +
          '<span style="font-size:12.5px;color:var(--text-3);font-weight:650">Halaman ' + ORD.page + ' dari ' + ORD.pages + '</span>' +
          '<button class="btn btn-ghost btn-sm" ' + (ORD.page >= ORD.pages ? 'disabled="disabled"' : '') + ' data-pg="1" type="button">Berikutnya' + svgI('chevrt') + '</button></div>'
        : '';
      $$('#ordPager [data-pg]').forEach(function (b) {
        on(b, 'click', function () { ORD.page = clamp(ORD.page + num(b.getAttribute('data-pg')), 1, ORD.pages); loadOrders(); });
      });
      $$('#ordTable [data-view]').forEach(function (b) { on(b, 'click', function () { openOrderDetail(b.getAttribute('data-view')); }); });
      $$('#ordTable [data-print]').forEach(function (b) {
        on(b, 'click', function () {
          call('order.receipt', { id: b.getAttribute('data-print') }, { silent: true }).then(function (r2) {
            if (r2 && r2.ok) showReceipt(r2.data, r2.meta.struk, r2.meta.wa_struk);
          });
        });
      });
      $$('#ordTable tr[data-order]').forEach(function (tr, i) {
        on(tr, 'click', function (e) { if (e.target.closest('button,a')) return; openOrderDetail(tr.getAttribute('data-order')); });
      });
    });
}
function openOrderDetail(id) {
  call('order.get', { id: id }, { silent: true }).then(function (res) {
    if (!res || !res.ok) { toast('Transaksi tidak ditemukan', 'err'); return; }
    var o = res.data;
    var html = '<div style="display:flex;flex-direction:column;gap:14px;min-height:0">' +
      '<div class="detail-grid">' +
      infoRow('Invoice', o.id) + infoRow('Tanggal', o.tanggal) + infoRow('Tipe', o.tipe) +
      infoRow('Status', o.status) + infoRow('Pelanggan', o.nama + (o.wa ? ' · ' + o.wa : '')) +
      infoRow('Kasir', o.kasir) + infoRow('Metode', o.metode) +
      infoRow('Diskon', rp(o.diskon) + (o.diskon_kode ? ' (' + o.diskon_kode + ')' : '')) +
      '</div>' +
      (o.alamat ? '<div class="card card-pad soft" style="border-radius:var(--r-md)"><div class="lbl">Alamat pengiriman</div>' +
        '<p style="font-size:13px;color:var(--text-2)">' + esc(o.alamat) + '</p></div>' : '') +
      '<div class="table-wrap"><table class="dt"><thead><tr><th>Produk</th><th class="num">Harga</th><th class="num">Qty</th><th class="num">Subtotal</th></tr></thead><tbody>' +
      (o.items || []).map(function (i2) {
        return '<tr><td><div style="font-weight:650">' + esc(i2.nama) + '</div><div style="font-size:11px;color:var(--text-3)">' + esc(i2.sku) + '</div></td>' +
          '<td class="num">' + rp(i2.harga) + '</td><td class="num">' + i2.qty + '</td><td class="num" style="font-weight:700">' + rp(i2.line) + '</td></tr>';
      }).join('') + '</tbody></table></div>' +
      '<div class="card card-pad soft" style="border-radius:var(--r-md)">' +
      '<div class="tot-row"><span>Subtotal</span><span class="v">' + rp(o.subtotal) + '</span></div>' +
      '<div class="tot-row"><span>Diskon</span><span class="v">- ' + rp(o.diskon) + '</span></div>' +
      '<div class="tot-row"><span>Poin dipakai / didapat</span><span class="v">' + int(o.poin_pakai) + ' / ' + int(o.poin_dapat) + '</span></div>' +
      '<div class="tot-row grand"><span>Total</span><span class="v">' + rp(o.total) + '</span></div>' +
      (o.bayar ? '<div class="tot-row"><span>Dibayar</span><span class="v">' + rp(o.bayar) + '</span></div>' +
        '<div class="tot-row"><span>Kembalian</span><span class="v">' + rp(o.kembali) + '</span></div>' : '') +
      '</div>' +
      (o.catatan ? '<p style="font-size:12.5px;color:var(--text-3)">Catatan: ' + esc(o.catatan) + '</p>' : '') + '</div>';
    formModal({
      title: 'Detail ' + o.id, sub: o.nama + ' · ' + rp(o.total), size: 'lg',
      fields: [{ k: 'x', t: 'custom', html: html }],
      submitLabel: 'Cetak Nota', onSubmit: function (v, act) { act.close(); showReceipt(o, res.meta.struk, res.meta.wa_struk); }
    });
    var foot = $('.modal-panel', $('#mForm')).querySelector('.modal-foot');
    var actions = '<button class="btn btn-ghost" data-act="wa" type="button">' + svgI('wa') + 'Kirim WA</button>' +
      (o.status === 'MENUNGGU' ? '<button class="btn btn-primary" data-act="pay" type="button">' + svgI('checkc') + 'Tandai Lunas</button>' : '') +
      (o.status !== 'VOID' && o.status !== 'MENUNGGU' ? '<button class="btn btn-danger" data-act="void" type="button">' + svgI('alert') + 'Void</button>' : '');
    foot.insertAdjacentHTML('afterbegin', actions);
    on(foot.querySelector('[data-act="wa"]'), 'click', function () {
      window.open(waLink(o.wa || (S.settings || {}).wa, 'Halo ' + o.nama + ', berikut rincian pesanan ' + o.id + ' dengan total ' + rp(o.total) + '. Terima kasih!'), '_blank');
    });
    if (foot.querySelector('[data-act="pay"]')) on(foot.querySelector('[data-act="pay"]'), 'click', function () {
      var b = this;
      confirmBox('Tandai transaksi lunas?', 'Stok akan otomatis dikurangi sesuai item pada invoice ' + o.id + '.', function () {
        call('order.pay', { id: o.id, bayar: o.total }, { btn: b }).then(function (r2) {
          if (!r2 || !r2.ok) return;
          closeModal('mForm');
          toast('Pembayaran ' + o.id + ' tercatat lunas', 'ok');
          showReceipt(r2.data.order, r2.data.struk, r2.data.wa_struk);
          loadOrders();
        });
      }, 'Ya, Lunas');
    });
    if (foot.querySelector('[data-act="void"]')) on(foot.querySelector('[data-act="void"]'), 'click', function () {
      var b = this;
      formModal({
        title: 'Batalkan Transaksi (Void)', sub: 'Stok akan dikembalikan. Tindakan ini tercatat di audit trail.', size: 'sm',
        fields: [{ k: 'alasan', l: 'Alasan pembatalan', t: 'textarea', req: true, ph: 'Contoh: salah input metode bayar' }],
        submitLabel: 'Void Transaksi',
        onSubmit: function (v, act) {
          call('order.void', { id: o.id, alasan: v.alasan }, { btn: act.button }).then(function (r2) {
            if (!r2 || !r2.ok) return;
            act.close();
            toast('Transaksi ' + o.id + ' dibatalkan (VOID)', 'warn');
            loadOrders(); refreshBadges();
          });
        }
      });
    });
  });
}
function exportOrdersCSV() {
  var list = S.ordList || [];
  if (!list.length) { toast('Tidak ada data untuk diekspor', 'warn'); return; }
  var head = ['Invoice', 'Tanggal', 'Tipe', 'Nama', 'WA', 'Metode', 'Status', 'Subtotal', 'Diskon', 'Total', 'Kasir'];
  var rows = list.map(function (o) {
    return [o.id, o.tanggal, o.tipe, o.nama, o.wa, o.metode, o.status, o.subtotal, o.diskon, o.total, o.kasir];
  });
  downloadCSV('transaksi-' + dayStr() + '.csv', head, rows);
}
function downloadCSV(nama, head, rows) {
  var csv = [head].concat(rows).map(function (r) {
    return r.map(function (c) { return '"' + String(c === undefined || c === null ? '' : c).replace(/"/g, '""') + '"'; }).join(';');
  }).join('\r\n');
  var blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
  var a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = nama;
  document.body.appendChild(a); a.click();
  setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 400);
  toast('File ' + nama + ' berhasil diunduh', 'ok');
}

/* =========================== 13. PRODUK & BUNDLING ====================== */
var PRD = { q: '', kategori: 'ALL', tipe: 'ALL', kondisi: 'ALL', status: 'AKTIF', sort: 'nama', menipis: 0, page: 1, limit: 15, pages: 1, total: 0, sel: [] };

function page_products() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
