    '<select class="sel-mini" id="prdKondisi"><option value="ALL">Baru &amp; Bekas</option><option value="BARU">Baru</option><option value="BEKAS">Bekas</option></select>' +
    '<select class="sel-mini" id="prdStatus"><option value="AKTIF">Aktif</option><option value="ALL">Semua Status</option><option value="ARSIP">Arsip</option></select>' +
    '<select class="sel-mini" id="prdSort">' + [['nama', 'Nama A-Z'], ['terbaru', 'Terbaru'], ['stok', 'Stok Terkecil'], ['margin', 'Margin Terbesar'], ['harga', 'Harga Tertinggi']].map(function (s0) {
