    }).join('') + '</select>' +
    '<label class="check" style="font-size:12.5px"><input id="prdMenipis" type="checkbox"/><span>Stok menipis saja</span></label>' +
    '</div><div class="mt4 tc" style="text-align:left"><span class="chip" id="prdInfo">Memuat…</span></div></div></div>' +
    '<div class="panel"><div class="bulkbar" id="prdBulk">' +
    '<span style="font-size:13px;font-weight:700" id="prdBulkCnt">0 dipilih</span>' +
    '<div class="flex gap2"><button class="btn btn-ghost btn-sm" id="prdBulkExport" type="button">' + svgI('download') + 'Ekspor</button>' +
    '<button class="btn btn-danger btn-sm" id="prdBulkDelete" type="button">' + svgI('trash') + 'Hapus</button></div></div>' +
    '<div class="panel-body tight" id="prdTable"></div></div>' +
    '<div class="tc mt6" id="prdPager"></div></div>';
  on($('#prdQ'), 'input', debounce(function (e) { PRD.q = e.target.value.trim(); PRD.page = 1; loadProducts2(); }, 300));
  ['#prdKat: kategori', '#prdTipe: tipe', '#prdKondisi: kondisi', '#prdStatus: status', '#prdSort: sort'].forEach(function (x) {
    var pair = x.split(': '), sel = pair[0], key = pair[1];
    on($(sel), 'change', function (e) { PRD[key] = e.target.value; PRD.page = 1; loadProducts2(); });
  });
  on($('#prdMenipis'), 'change', function (e) { PRD.menipis = e.target.checked ? 1 : 0; PRD.page = 1; loadProducts2(); });
  on($('#prdNew'), 'click', function () { productForm(null); });
  on($('#prdExport'), 'click', doExportProducts);
  on($('#prdImport'), 'click', openImportModal);
  on($('#prdBulkDelete'), 'click', bulkDelete);
  on($('#prdBulkExport'), 'click', function () {
    var rows = (S.prdList || []).filter(function (x) { return PRD.sel.indexOf(x.id) > -1; });
    if (!rows.length) return;
