          '<td class="num" style="font-size:12.5px;color:var(--text-3)">' + rp(p.harga_beli) + '</td>' +
          '<td class="num"><span class="chip ' + (p.margin_pct >= 15 ? 'chip-emerald' : p.margin_pct >= 7 ? 'chip-amber' : 'chip-rose') + '">' +
          rpS(p.margin) + ' · ' + p.margin_pct + '%</span></td>' +
          '<td class="num"><span class="stok ' + (p.habis ? 'no' : p.tipis ? 'low' : 'ok') + '">' +
          (p.tipe === 'BUNDLE' ? int(p.max_buildable) + ' paket' : int(p.stok) + ' ' + esc(p.satuan || 'unit')) + '</span></td>' +
          '<td><span class="chip ' + (p.status === 'AKTIF' ? 'chip-emerald' : '') + '">' + esc(p.status) + '</span></td>' +
          '<td><div class="row-actions">' +
