          (p.tipe === 'BUNDLE' ? '<button class="mini-btn" data-bom="' + esc(p.id) + '" data-tip="Susunan BOM" type="button">' + svgI('layers') + '</button>' : '') +
          '<button class="mini-btn" data-move="' + esc(p.sku) + '" data-tip="Kartu stok" type="button">' + svgI('list') + '</button>' +
          '<button class="mini-btn danger" data-del="' + esc(p.id) + '" data-tip="Hapus" type="button">' + svgI('trash') + '</button>' +
          '</div></td></tr>';
      }).join('') + '</tbody></table></div>';
    on($('#prdAll'), 'change', function () {
      PRD.sel = $('#prdAll').checked ? list.map(function (p) { return p.id; }) : [];
      $$('#prdTable [data-chk]').forEach(function (c) { c.checked = $('#prdAll').checked; });
