    $$('#prdTable [data-edit]').forEach(function (b) { on(b, 'click', function () { productForm(b.getAttribute('data-edit')); }); });
    $$('#prdTable [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-del');
        var p = list.filter(function (x) { return x.id === id; })[0] || {};
        confirmBox('Hapus produk?', '“' + (p.nama || '') + '” akan dihapus permanen dari katalog. Riwayat transaksi tetap tersimpan.', function () {
          call('product.delete', { id: id }, {}).then(function (r2) {
            if (r2 && r2.ok) { toast('Produk dihapus', 'ok'); loadProducts2(); refreshBadges(); }
          });
        }, 'Ya, Hapus');
      });
    });
    $$('#prdTable [data-bom]').forEach(function (b) { on(b, 'click', function () { nav('bundles', { id: b.getAttribute('data-bom') }); }); });
    $$('#prdTable [data-move]').forEach(function (b) { on(b, 'click', function () { stockCard(b.getAttribute('data-move')); }); });
    $('#prdPager').innerHTML = PRD.pages > 1 ? '<div class="pager">' +
      '<button class="btn btn-ghost btn-sm" ' + (PRD.page <= 1 ? 'disabled="disabled"' : '') + ' data-pg="-1" type="button">Sebelumnya</button>' +
      '<span style="font-size:12.5px;color:var(--text-3);font-weight:650">Halaman ' + PRD.page + ' / ' + PRD.pages + '</span>' +
      '<button class="btn btn-ghost btn-sm" ' + (PRD.page >= PRD.pages ? 'disabled="disabled"' : '') + ' data-pg="1" type="button">Berikutnya</button></div>' : '';
    $$('#prdPager [data-pg]').forEach(function (b) {
      on(b, 'click', function () { PRD.page = clamp(PRD.page + num(b.getAttribute('data-pg')), 1, PRD.pages); loadProducts2(); });
    });
    bulkBar();
  });
}
function bulkBar() {
  var bar = $('#prdBulk');
  if (!bar) return;
  bar.classList.toggle('on', !!PRD.sel.length);
  var c = $('#prdBulkCnt'); if (c) c.textContent = PRD.sel.length + ' produk dipilih';
}
function bulkDelete() {
  if (!PRD.sel.length) return;
  confirmBox('Hapus ' + PRD.sel.length + ' produk?', 'Produk yang dipakai paket rakitan akan ditolak server. Tindakan tercatat di audit trail.', function () {
    call('product.bulkDelete', { ids: PRD.sel }, {}).then(function (r) {
      if (!r || !r.ok) return;
      toast(r.data.terhapus + ' produk dihapus', 'ok');
      PRD.sel = []; loadProducts2();
    });
  }, 'Ya, Hapus Semua');
}
function productForm(id) {
