        { k: 'brand', l: 'Brand / Merek', t: 'text', ph: 'ASUS', half: true },
        { k: 'tipe', l: 'Tipe', t: 'select', opts: [{ v: 'UNIT', l: 'Unit Tunggal' }, { v: 'BUNDLE', l: 'Paket Rakitan (BOM)' }], half: true },
        { k: 'kondisi', l: 'Kondisi', t: 'select', opts: [{ v: 'BARU', l: 'Baru' }, { v: 'BEKAS', l: 'Bekas / Refurbished' }], half: true },
        { k: 'harga_beli', l: 'Harga Modal (Rp)', t: 'money', req: true, half: true },
        { k: 'harga', l: 'Harga Jual (Rp)', t: 'money', req: true, half: true },
        { k: 'harga_coret', l: 'Harga Coret / Sebelum Diskon', t: 'money', half: true, hint: 'Kosongkan bila tidak ada diskon' },
        { k: 'stok', l: 'Stok', t: 'number', half: true, def: isNew ? 0 : p.stok },
        { k: 'stok_min', l: 'Stok Minimum', t: 'number', half: true, def: p.stok_min || 3, hint: 'Peringatan muncul di dashboard' },
        { k: 'garansi', l: 'Garansi', t: 'text', ph: '1 Tahun Resmi', half: true },
        { k: 'poin', l: 'Poin Bonus', t: 'number', half: true, def: p.poin || 0 },
        { k: 'gambar', l: 'URL Gambar Utama', t: 'text', ph: 'https://…' },
        { k: 'tags', l: 'Tag Pencarian', t: 'text', ph: 'gaming, ringan, kuliah' },
        { k: 'deskripsi', l: 'Deskripsi', t: 'textarea', ph: 'Keunggulan produk, kelengkapan, kondisi fisik…' },
        { k: 'status', l: 'Status', t: 'select', opts: [{ v: 'AKTIF', l: 'Aktif (tampil di web)' }, { v: 'ARSIP', l: 'Arsip (disembunyikan)' }], half: true },
        { k: 'unggulan', l: 'Tampilkan sebagai produk unggulan', t: 'switch', hint: 'Tampilkan di beranda', def: p.unggulan }
      ],
      submitLabel: isNew ? 'Simpan Produk' : 'Simpan Perubahan',
      onSubmit: function (v, act) {
        v.id = id;
        v._stokLama = p.stok;
        v.bom = p.bom || [];
        call('product.save', v, { btn: act.button }).then(function (r) {
          if (!r || !r.ok) return;
          act.close();
          toast('Produk “' + r.data.nama + '” tersimpan', 'ok');
          loadProducts2(); refreshBadges();
        });
      }
    });
  });
}
function doExportProducts() {
  call('product.export', {}, { btn: $('#prdExport') }).then(function (r) {
    if (!r || !r.ok) return;
    var blob = new Blob([r.data.csv], { type: 'text/csv;charset=utf-8;' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = r.data.nama_file;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 400);
    toast(r.data.jumlah + ' produk diekspor ke CSV', 'ok');
  });
}
function openImportModal() {
  formModal({
    title: 'Impor Produk Massal', sub: 'Tempel data dari Excel/Google Sheets atau unggah file CSV.', size: 'lg',
    fields: [
      { k: 'petunjuk', t: 'info', html: '<b>Format kolom (baris pertama = judul):</b><br>' +
        '<code style="font-size:11.5px">nama, sku, kategori, brand, harga, harga_beli, stok, garansi</code><br>' +
        '<span style="font-size:12px;color:var(--text-3)">Pemisah kolom: koma, titik-koma, atau TAB. SKU yang sudah ada akan diperbarui.</span>' },
      { k: 'mode', l: 'Sumber Data', t: 'select', opts: [{ v: 'paste', l: 'Tempel / ketik data' }, { v: 'file', l: 'Unggah file CSV' }] },
      { k: 'file', l: 'File CSV', t: 'custom', html: '<div class="drop-zone" id="impArea"><input accept=".csv,.txt" id="impFile" type="file" style="display:none"/>' +
        svgI('upload') + '<b style="display:block;font-size:14px">Tarik &amp; lepas file di sini</b>' +
        '<small style="display:block;font-size:12px;color:var(--text-3);margin-top:4px">atau ketuk untuk memilih file .csv / .txt</small></div>' },
      { k: 'data', l: 'Data Tempel', t: 'textarea', style: 'min-height:150px;font-family:var(--f-mono);font-size:12px',
        ph: 'nama,sku,kategori,brand,harga,harga_beli,stok\nASUS Vivobook 14,LPT-ASU-V14,Laptop,ASUS,6499000,5950000,5' }
    ],
    submitLabel: 'Impor Sekarang',
    onSubmit: function (v, act) {
      if (!v.data || v.data.trim().length < 8) { toast('Tempel data atau pilih file terlebih dahulu', 'warn'); return; }
      var rows = parseTable(v.data);
      if (!rows.length) { toast('Tidak ada baris valid yang bisa diimpor', 'warn'); return; }
      call('product.import', { rows: rows }, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        var extra = (r.data.error || []).length ? '<br><span style="color:#e11d48;font-size:12px">' + (r.data.error || []).slice(0, 5).map(esc).join('<br>') + '</span>' : '';
        successBox('Impor selesai', r.data.sukses + ' produk berhasil diimpor, ' + r.data.gagal + ' baris gagal.' + extra, null, null);
        loadProducts2();
      });
    }
  });
  setTimeout(function () {
    var area = $('#impArea'), file = $('#impFile');
    if (!area) return;
    on(area, 'click', function () { file.click(); });
    ['dragenter', 'dragover'].forEach(function (ev) { on(area, ev, function (e) { e.preventDefault(); area.classList.add('over'); }); });
    ['dragleave', 'drop'].forEach(function (ev) { on(area, ev, function (e) { e.preventDefault(); area.classList.remove('over'); }); });
    on(area, 'drop', function (e) {
      if (e.dataTransfer.files && e.dataTransfer.files[0]) readCSVFile(e.dataTransfer.files[0]);
    });
    on(file, 'change', function () { if (file.files[0]) readCSVFile(file.files[0]); });
    function readCSVFile(f) {
      var rd = new FileReader();
      rd.onload = function () {
        var txt = String(rd.result || '');
        var ta = $('#fm_data');
        if (ta) ta.value = txt;
        var sel = $('#fm_mode');
        if (sel) sel.value = 'paste';
        toast('File ' + f.name + ' dimuat — periksa lalu klik Impor', 'ok');
      };
      rd.readAsText(f);
    }
  }, 120);
}
function parseTable(txt) {
  var lines = String(txt).replace(/\r/g, '').split('\n').filter(function (l) { return l.trim().length; });
  if (!lines.length) return [];
  var sep = lines[0].indexOf('\t') > -1 ? '\t' : (lines[0].split(';').length > lines[0].split(',').length ? ';' : ',');
  function split(l) {
    var out = [], cur = '', q = false;
    for (var i = 0; i < l.length; i++) {
      var ch = l[i];
      if (ch === '"') { q = !q; continue; }
      if (ch === sep && !q) { out.push(cur); cur = ''; continue; }
      cur += ch;
    }
    out.push(cur);
    return out.map(function (x) { return x.trim(); });
  }
  var head = split(lines[0]).map(function (h) { return h.toLowerCase().replace(/\s+/g, '_'); });
  if (head.indexOf('nama') < 0 && head.indexOf('name') > -1) head[head.indexOf('name')] = 'nama';
  var body = lines.slice(1);
  if (head.indexOf('nama') < 0) { head = ['nama', 'sku', 'kategori', 'brand', 'harga', 'harga_beli', 'stok', 'garansi'].slice(0, head.length); body = lines; }
  return body.map(function (l) {
    var cells = split(l), o = {};
    head.forEach(function (h, i) { if (h) o[h] = cells[i] === undefined ? '' : cells[i]; });
    return o;
  }).filter(function (o) { return o.nama; });
}

/* ------------------------------ BUNDLING ------------------------------- */
var BOM = { id: null, items: [], max: 0, mat: [] };
function page_bundles(param) {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Bundling PC Rakitan</h1><p>Susun Bill of Materials (BOM). Stok paket dihitung otomatis dari komponen paling langka.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="bomPick" type="button">' + svgI('package') + 'Pilih Paket</button>' +
    '<button class="btn btn-primary btn-sm" id="bomNew" type="button">' + svgI('plus') + 'Paket Baru</button></div></div>' +
    '<div class="bundle-hero mb6"><div style="flex:1;min-width:240px">' +
    '<span class="bdg bdg-bundle">Kalkulator Rakitan</span>' +
    '<h3 style="font-size:clamp(19px,3.4vw,25px);margin:10px 0 8px" id="bomTitle">— Pilih paket rakitan —</h3>' +
    '<p style="font-size:13.5px;color:var(--text-3);line-height:1.7" id="bomSub">Pilih paket di kanan atau buat paket baru, lalu tambahkan komponen untuk menghitung HPP dan batas rakitan.</p></div>' +
    '<div class="build-max"><span class="n" id="bomMax">0</span><span><b>paket siap rakit</b><br><small id="bomHpp">HPP ideal Rp0</small></span></div></div>' +
    '<div class="grid-dash w2">' +
    '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Bill of Materials</h3><p id="bomCount">Belum ada komponen</p></div>' +
    '<button class="btn btn-ghost btn-sm" id="bomAdd" type="button">' + svgI('plus') + 'Tambah Komponen</button></div>' +
    '<div class="panel-body tight"><div id="bomList"></div></div></div>' +
    '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Kesiapan Komponen</h3><p>Komponen yang menghambat perakitan</p></div></div>' +
    '<div class="panel-body tight"><div id="bomReady"></div></div></div></div>' +
    '<div class="tc mt6 flex gap2" style="justify-content:center;flex-wrap:wrap">' +
    '<button class="btn btn-ghost" id="bomSave" type="button">' + svgI('save') + 'Simpan Perubahan BOM</button>' +
    '<button class="btn btn-ghost" id="bomPreview" type="button">' + svgI('eye') + 'Pratinjau di Website</button>' +
    '</div></div>';
  on($('#bomNew'), 'click', function () { nav('products'); setTimeout(function () { productForm(null); }, 260); });
  on($('#bomPick'), 'click', bomPickDialog);
  on($('#bomAdd'), 'click', bomAddDialog);
  on($('#bomSave'), 'click', bomSave);
  on($('#bomPreview'), 'click', function () {
    if (!BOM.sku) { toast('Pilih paket terlebih dahulu', 'warn'); return; }
    openProduct(BOM.sku);
  });
  return loadBundle(param && param.id);
}
function loadBundle(id) {
  call('bundle.materials', {}, { silent: true }).then(function (r) { BOM.mat = (r && r.data) || []; });
  var box = $('#bomList');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  if (!id) {
    return call('product.list', { tipe: 'BUNDLE', limit: 50 }, { silent: true }).then(function (r) {
      var list = (r && r.data) || [];
      if (!list.length) { box.innerHTML = emptyState('Belum ada paket rakitan. Buat produk bertipe BUNDLE terlebih dahulu.', 'layers'); return; }
      if (list[0]) return loadBundleById(list[0].id);
    });
  }
  return loadBundleById(id);
}
function loadBundleById(id) {
  return call('bundle.explode', { id: id }, { silent: true }).then(function (res) {
    if (!res || !res.ok) { $('#bomList').innerHTML = emptyState('Paket tidak ditemukan.', 'alert'); return; }
    var d = res.data;
    BOM.id = d.produk.id; BOM.sku = d.produk.sku; BOM.items = (d.komponen || []).map(function (k) {
      return { sku: k.sku, nama: k.nama, qty: num(k.qty), stok: num(k.stok), harga_beli: num(k.harga_beli) };
    });
    $('#bomTitle').textContent = d.produk.nama;
    $('#bomSub').innerHTML = 'SKU <b>' + esc(d.produk.sku) + '</b> · harga jual ' + rp(d.produk.harga) +
      ' · margin ' + rp(d.produk.harga - d.hpp_ideal) + ' (' + (d.hpp_ideal ? Math.round((d.produk.harga - d.hpp_ideal) / d.hpp_ideal * 100) : 0) + '%)';
    renderBom();
  });
}
function renderBom() {
  var hpp = sum(BOM.items, function (i) { return num(i.harga_beli) * num(i.qty); });
  var max = BOM.items.length ? Math.min.apply(null, BOM.items.map(function (i) { return Math.floor(num(i.stok) / Math.max(1, num(i.qty))); })) : 0;
  BOM.max = max;
  $('#bomMax').textContent = max;
  $('#bomHpp').textContent = 'HPP ideal ' + rp(hpp);
  $('#bomCount').textContent = BOM.items.length + ' komponen · HPP ' + rp(hpp);
  var box = $('#bomList');
  if (!BOM.items.length) { box.innerHTML = emptyState('Belum ada komponen. Klik “Tambah Komponen” untuk menyusun rakitan.', 'layers'); $('#bomReady').innerHTML = ''; return; }
  box.innerHTML = '<div class="bom-list">' + BOM.items.map(function (i, ix) {
    var cukup = num(i.stok) >= num(i.qty);
    return '<div class="bom-row" data-ix="' + ix + '">' +
      '<span class="av-sm" style="background:var(--surface-2)">' + svgI('cpu') + '</span>' +
      '<div style="flex:1;min-width:0"><div class="nm">' + esc(i.nama) + '</div>' +
      '<div style="font-size:11.2px;color:var(--text-3)">' + esc(i.sku) + ' · modal ' + rp(i.harga_beli) +
      ' · <span style="color:' + (cukup ? 'var(--emerald-600)' : 'var(--rose-600)') + '">stok ' + i.stok + '</span></div>' +
      '<div class="bom-bar"><i style="width:' + clamp(num(i.stok) / Math.max(1, num(i.qty) * (BOM.max || 1)) * 100, 4, 100) + '%"></i></div></div>' +
      '<span class="qty-ctrl"><button data-bq="-1" type="button">' + svgI('minus') + '</button>' +
      '<input data-bi type="number" value="' + i.qty + '" style="width:36px"/>' +
      '<button data-bq="1" type="button">' + svgI('plus') + '</button></span>' +
      '<button class="mini-btn danger" data-bdel="1" type="button">' + svgI('trash') + '</button></div>';
  }).join('') + '</div>';
  $$('#bomList [data-bq]').forEach(function (b) {
    on(b, 'click', function () {
      var ix = num(b.closest('[data-ix]').getAttribute('data-ix'));
      BOM.items[ix].qty = Math.max(1, num(BOM.items[ix].qty) + num(b.getAttribute('data-bq')));
      renderBom();
    });
  });
  $$('#bomList [data-bi]').forEach(function (i2) {
    on(i2, 'change', function () {
      var ix = num(i2.closest('[data-ix]').getAttribute('data-ix'));
      BOM.items[ix].qty = Math.max(1, num(i2.value));
      renderBom();
    });
  });
  $$('#bomList [data-bdel]').forEach(function (b) {
    on(b, 'click', function () {
      var ix = num(b.closest('[data-ix]').getAttribute('data-ix'));
      BOM.items.splice(ix, 1); renderBom();
    });
  });
  var kurang = BOM.items.filter(function (i) { return num(i.stok) < num(i.qty); });
  $('#bomReady').innerHTML = kurang.length
    ? '<div class="list-plain">' + kurang.map(function (i) {
        return '<div class="list-row"><span class="av-sm" style="background:#fff1f2;color:#e11d48">' + svgI('alert') + '</span>' +
          '<div style="flex:1"><div class="ttl">' + esc(i.nama) + '</div><div class="sub">Butuh ' + i.qty + ', tersedia ' + i.stok + '</div></div>' +
          '<button class="mini-btn" data-bo="' + esc(i.sku) + '" data-tip="Buat PO" type="button">' + svgI('plus') + '</button></div>';
      }).join('') + '</div>'
    : '<div class="list-plain"><div class="list-row"><span class="av-sm" style="background:#ecfdf5;color:#059669">' + svgI('checkc') + '</span>' +
      '<div style="flex:1"><div class="ttl">Semua komponen siap</div><div class="sub">' + BOM.max + ' paket dapat dirakit hari ini</div></div></div></div>';
  $$('#bomReady [data-bo]').forEach(function (b) {
    on(b, 'click', function () { nav('po', { sku: b.getAttribute('data-bo') }); });
  });
}
function bomPickDialog() {
  call('product.list', { tipe: 'BUNDLE', limit: 50 }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    formModal({
      title: 'Pilih Paket Rakitan', sub: 'Kelola susunan komponen (BOM) dari paket yang sudah ada.', size: 'md',
      fields: [{ k: 'id', l: 'Paket', t: 'select', opts: list.map(function (p) { return { v: p.id, l: p.nama + ' · ' + rp(p.harga) }; }) }],
      submitLabel: 'Buka Paket',
      onSubmit: function (v, act) { act.close(); loadBundleById(v.id); }
    });
  });
}
function bomAddDialog() {
  if (!BOM.id) { toast('Pilih paket rakitan terlebih dahulu', 'warn'); return; }
  var opts = BOM.mat.map(function (m) {
    return { v: m.sku, l: m.nama + ' · stok ' + m.stok + ' · ' + rp(m.harga_beli) };
  });
  formModal({
    title: 'Tambah Komponen', sub: 'Pilih komponen yang dipakai untuk merakit paket ini.', size: 'md',
    fields: [
      { k: 'sku', l: 'Komponen', t: 'select', req: true, opts: [{ v: '', l: '— pilih komponen —' }].concat(opts) },
      { k: 'qty', l: 'Jumlah per Paket', t: 'number', req: true, def: 1 },
      { k: 'info', t: 'info', html: 'Komponen yang dipakai di paket lain tetap dapat digunakan bersama. Stok paket = nilai terkecil dari (stok komponen ÷ kebutuhan).' }
    ],
    submitLabel: 'Tambahkan',
    onSubmit: function (v, act) {
      var m = BOM.mat.filter(function (x) { return x.sku === v.sku; })[0];
      if (!m) { toast('Komponen tidak ditemukan', 'err'); return; }
      var ada = BOM.items.filter(function (x) { return x.sku === m.sku; })[0];
      if (ada) ada.qty += num(v.qty);
      else BOM.items.push({ sku: m.sku, nama: m.nama, qty: num(v.qty), stok: m.stok, harga_beli: m.harga_beli });
      act.close(); renderBom();
      toast(m.nama + ' ditambahkan ke BOM', 'ok');
    }
  });
}
function bomSave() {
  if (!BOM.id) { toast('Tidak ada paket yang dipilih', 'warn'); return; }
  call('product.get', { id: BOM.id }, { silent: true }).then(function (r) {
    if (!r || !r.ok) return;
    var p = r.data;
    var payload = Object.assign({}, p, { id: p.id, bom: BOM.items.map(function (i) { return { sku: i.sku, qty: num(i.qty) }; }), _stokLama: p.stok });
    call('product.save', payload, { btn: $('#bomSave') }).then(function (r2) {
      if (!r2 || !r2.ok) return;
      toast('BOM paket “' + r2.data.nama + '” tersimpan. Maksimal ' + BOM.max + ' paket siap rakit.', 'ok');
      renderBom();
    });
  });
}
function stockCard(sku) {
  call('stock.moves', { sku: sku, limit: 80 }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    var html = '<div class="flex between center mb4 wrapf"><div><b style="font-size:15px">' + esc(sku) + '</b>' +
      '<div style="font-size:12.3px;color:var(--text-3)">' + list.length + ' mutasi terakhir</div></div>' +
      '<span class="chip">Masuk ' + int(sum(list.filter(function (m) { return num(m.qty) > 0; }), function (m) { return m.qty; })) +
      ' · Keluar ' + int(sum(list.filter(function (m) { return num(m.qty) < 0; }), function (m) { return -m.qty; })) + '</span></div>';
    html += list.length ? '<div class="table-wrap"><table class="dt"><thead><tr><th>Waktu</th><th>Tipe</th><th class="num">Qty</th>' +
      '<th class="num">Stok</th><th>Ref</th><th>Oleh</th></tr></thead><tbody>' + list.map(function (m) {
        return '<tr><td style="font-size:12.2px">' + esc(m.tanggal) + '</td>' +
          '<td><span class="chip ' + (num(m.qty) > 0 ? 'chip-emerald' : 'chip-rose') + '">' + esc(m.tipe) + '</span></td>' +
          '<td class="num" style="font-weight:750;color:' + (num(m.qty) > 0 ? 'var(--emerald-600)' : 'var(--rose-600)') + '">' +
          (num(m.qty) > 0 ? '+' : '') + int(m.qty) + '</td>' +
          '<td class="num">' + int(m.sebelum) + ' → <b>' + int(m.sesudah) + '</b></td>' +
          '<td style="font-size:12px">' + esc(m.ref) + '<div style="color:var(--text-3);font-size:11px">' + esc(m.catatan || '') + '</div></td>' +
          '<td style="font-size:12px">' + esc(m.oleh) + '</td></tr>';
      }).join('') + '</tbody></table></div>' : emptyState('Belum ada mutasi stok untuk SKU ini.', 'box');
    formModal({ title: 'Kartu Stok', sub: 'Kartu stok ' + sku, size: 'xl', fields: [{ k: 'x', t: 'custom', html: html }], submitLabel: 'Tutup', onSubmit: function (v, act) { act.close(); } });
  });
}

/* =========================== 14. STOK & PEMBELIAN ======================= */
var STK = { tab: 'opname', q: '', tipe: 'ALL', rows: [], catatan: '', mode: 'SET' };
function page_stock(param) {
  STK.tab = (param && param.tab) || 'opname';
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Stok &amp; Opname</h1><p>Penyesuaian stok fisik, kartu stok, dan peringatan komponen.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="stkLow" type="button">' + svgI('alert') + 'Stok Menipis</button>' +
    '<button class="btn btn-primary btn-sm" id="stkPost" type="button">' + svgI('checkc') + 'Posting Opname</button></div></div>' +
    '<div class="tabs-app mb6" id="stkTabs">' +
    '<button class="tab on" data-t="opname">Sesi Opname</button>' +
    '<button class="tab" data-t="kartu">Kartu Stok</button>' +
    '<button class="tab" data-t="low">Peringatan Stok</button></div>' +
    '<div id="stkBody"></div></div>';
  on($('#stkTabs'), 'click', function (e) {
    var t = e.target.closest('.tab'); if (!t) return;
    STK.tab = t.getAttribute('data-t');
    $$('#stkTabs .tab').forEach(function (x) { x.classList.toggle('on', x === t); });
    renderStock();
  });
  on($('#stkLow'), 'click', function () { STK.tab = 'low'; $$('#stkTabs .tab').forEach(function (x) { x.classList.toggle('on', x.getAttribute('data-t') === 'low'); }); renderStock(); });
  on($('#stkPost'), 'click', postOpname);
  return renderStock();
}
function renderStock() {
  var box = $('#stkBody');
  if (STK.tab === 'opname') return renderOpname(box);
  if (STK.tab === 'kartu') return renderKartu(box);
  return renderLow(box);
}
function renderOpname(box) {
  box.innerHTML = '<div class="panel mb4"><div class="panel-body">' +
    '<div class="flex gap3 wrapf mb4">' +
    '<label class="field" style="flex:1;min-width:220px;margin:0"><span class="lbl">Catatan Opname <span class="req">*</span></span>' +
    '<input class="inp" id="stkCatatan" placeholder="Contoh: opname rutin akhir bulan, gudang belakang" value="' + esc(STK.catatan) + '"/></label>' +
    '<label class="field" style="width:180px;margin:0"><span class="lbl">Mode Input</span>' +
    '<select class="sel" id="stkMode"><option value="SET">SET — isi stok akhir</option><option value="DELTA">DELTA — tambah / kurang</option></select></label>' +
    '<div style="align-self:flex-end"><button class="btn btn-ghost" id="stkAddRow" type="button">' + svgI('plus') + 'Tambah Baris</button></div></div>' +
    '<div class="search-box mb4">' + svgI('search') + '<input class="inp" id="stkFind" placeholder="Cari produk untuk ditambahkan cepat…" type="text"/></div>' +
    '<div id="stkSug"></div>' +
    '</div></div>' +
    '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Baris Penyesuaian</h3><p id="stkRowCnt">0 baris</p></div>' +
    '<button class="btn btn-ghost btn-sm" id="stkClearRow" type="button">Kosongkan</button></div>' +
    '<div class="panel-body tight" id="stkRows"></div></div>';
  on($('#stkCatatan'), 'input', function (e) { STK.catatan = e.target.value; });
  on($('#stkMode'), 'change', function (e) { STK.mode = e.target.value; renderRows(); });
  on($('#stkAddRow'), 'click', function () { STK.rows.push({ sku: '', nama: '', stok: 0, qty: 0, mode: STK.mode }); renderRows(); });
  on($('#stkClearRow'), 'click', function () { STK.rows = []; renderRows(); });
  on($('#stkFind'), 'input', debounce(function (e) {
    var q = e.target.value.trim();
    if (q.length < 2) { $('#stkSug').innerHTML = ''; return; }
    call('pos.lookup', { q: q, limit: 8 }, { silent: true }).then(function (r) {
      var list = (r && r.data) || [];
      $('#stkSug').innerHTML = list.length ? '<div class="flex gap2 wrapf">' + list.map(function (p) {
        return '<button class="chip-filter" data-addsku="' + esc(p.sku) + '" type="button">' + svgI('plus') + esc(p.nama) +
          ' <span style="color:var(--text-3)">· stok ' + p.stok + '</span></button>';
      }).join('') + '</div>' : '<p style="font-size:12.5px;color:var(--text-3)">Produk tidak ditemukan.</p>';
      $$('#stkSug [data-addsku]').forEach(function (b) {
        on(b, 'click', function () {
          var p = list.filter(function (x) { return x.sku === b.getAttribute('data-addsku'); })[0];
          if (STK.rows.filter(function (x) { return x.sku === p.sku; }).length) { toast('SKU sudah ada di daftar', 'warn'); return; }
          STK.rows.push({ sku: p.sku, nama: p.nama, stok: num(p.stok), qty: num(p.stok), mode: STK.mode });
          renderRows(); $('#stkSug').innerHTML = ''; $('#stkFind').value = '';
        });
      });
    });
  }, 280));
  renderRows();
}
function renderRows() {
  var box = $('#stkRows');
  if (!box) return;
  $('#stkRowCnt').textContent = STK.rows.length + ' baris siap diposting';
  if (!STK.rows.length) { box.innerHTML = emptyState('Belum ada baris. Cari produk di atas atau klik “Tambah Baris”.', 'list'); return; }
  box.innerHTML = '<div class="table-wrap"><table class="dt"><thead><tr><th>Produk</th><th class="num">Stok Sistem</th>' +
    '<th class="num">' + (STK.mode === 'SET' ? 'Stok Fisik (SET)' : 'Selisih (DELTA)') + '</th><th class="num">Hasil</th><th></th></tr></thead><tbody>' +
    STK.rows.map(function (r, ix) {
      var hasil = STK.mode === 'SET' ? num(r.qty) : num(r.stok) + num(r.qty);
      var selisih = hasil - num(r.stok);
      return '<tr><td><div style="font-weight:650;font-size:13px">' + esc(r.nama || '(pilih produk)') + '</div>' +
        '<div style="font-size:11px;color:var(--text-3)">' + esc(r.sku) + '</div></td>' +
        '<td class="num">' + int(r.stok) + '</td>' +
        '<td class="num"><input class="inp num" data-ix="' + ix + '" style="max-width:120px;text-align:right" type="number" value="' + num(r.qty) + '"/></td>' +
        '<td class="num" style="font-weight:750;color:' + (selisih === 0 ? 'var(--text-3)' : selisih > 0 ? 'var(--emerald-600)' : 'var(--rose-600)') + '">' +
        int(hasil) + (selisih ? ' (' + (selisih > 0 ? '+' : '') + int(selisih) + ')' : '') + '</td>' +
        '<td><button class="mini-btn danger" data-rm="' + ix + '" type="button">' + svgI('trash') + '</button></td></tr>';
    }).join('') + '</tbody></table></div>';
  $$('#stkRows [data-ix]').forEach(function (i2) {
    on(i2, 'input', function () { STK.rows[num(i2.getAttribute('data-ix'))].qty = num(i2.value); renderRows(); });
  });
  $$('#stkRows [data-rm]').forEach(function (b) {
    on(b, 'click', function () { STK.rows.splice(num(b.getAttribute('data-rm')), 1); renderRows(); });
  });
}
function postOpname() {
  if (!STK.rows.length) { toast('Belum ada baris penyesuaian', 'warn'); return; }
  if (String(STK.catatan).trim().length < 5) { toast('Catatan opname wajib diisi (min. 5 karakter) untuk audit trail', 'warn'); var i = $('#stkCatatan'); if (i) i.focus(); return; }
  var items = STK.rows.map(function (r) { return { sku: r.sku, qty: num(r.qty), mode: STK.mode }; });
  confirmBox('Posting opname sekarang?', STK.rows.length + ' produk akan disesuaikan. Setiap perubahan tercatat di kartu stok dan audit trail.', function () {
    call('stock.opname', { items: items, catatan: STK.catatan, mode: STK.mode }, { btn: $('#stkPost') }).then(function (r) {
      if (!r || !r.ok) return;
      STK.rows = []; renderRows();
      successBox('Opname berhasil diposting', r.data.sukses + ' produk disesuaikan, ' + r.data.gagal + ' gagal.', null, null);
      refreshBadges();
    });
  }, 'Ya, Posting');
}
function renderKartu(box) {
  box.innerHTML = '<div class="panel mb4"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') +
    '<input class="inp" id="stkQ" placeholder="Cari SKU, nama produk, atau nomor referensi…" type="text" value="' + esc(STK.q) + '"/></div>' +
    '<select class="sel-mini" id="stkTipe"><option value="ALL">Semua Mutasi</option>' +
    ['IN', 'OUT', 'ADJUST', 'OPNAME', 'PO_IN', 'TRADEIN_IN', 'RETUR'].map(function (t) { return '<option value="' + t + '">' + t + '</option>'; }).join('') +
    '</select></div></div></div>' +
    '<div class="panel"><div class="panel-body tight" id="stkMoveBox"></div></div>';
  on($('#stkQ'), 'input', debounce(function (e) { STK.q = e.target.value.trim(); loadMoves(); }, 300));
  on($('#stkTipe'), 'change', function (e) { STK.tipe = e.target.value; loadMoves(); });
  loadMoves();
}
function loadMoves() {
  var box = $('#stkMoveBox');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  call('stock.moves', { q: STK.q, tipe: STK.tipe, limit: 80 }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [], rg = (r && r.meta && r.meta.ringkas) || {};
    if (!list.length) { box.innerHTML = emptyState('Belum ada mutasi stok yang cocok.', 'box'); return; }
    box.innerHTML = '<div class="flex gap3 wrapf mb2" style="padding:14px 18px 0">' +
      '<span class="chip chip-emerald">Masuk ' + int(rg.masuk) + ' unit</span>' +
      '<span class="chip chip-rose">Keluar ' + int(rg.keluar) + ' unit</span>' +
      '<span class="chip">' + int(rg.total) + ' mutasi</span></div>' +
      '<div class="table-wrap"><table class="dt"><thead><tr><th>Waktu</th><th>Produk</th><th>Tipe</th><th class="num">Qty</th>' +
      '<th class="num">Stok</th><th>Ref / Catatan</th><th>Oleh</th></tr></thead><tbody>' + list.map(function (m) {
        return '<tr><td style="font-size:12.2px;white-space:nowrap">' + esc(m.tanggal) + '</td>' +
          '<td><div style="font-weight:650;font-size:12.8px">' + esc(m.nama) + '</div><div style="font-size:11px;color:var(--text-3)">' + esc(m.sku) + '</div></td>' +
          '<td><span class="chip ' + (num(m.qty) > 0 ? 'chip-emerald' : 'chip-rose') + '">' + esc(m.tipe) + '</span></td>' +
          '<td class="num" style="font-weight:750;color:' + (num(m.qty) > 0 ? 'var(--emerald-600)' : 'var(--rose-600)') + '">' + (num(m.qty) > 0 ? '+' : '') + int(m.qty) + '</td>' +
          '<td class="num" style="font-size:12.2px">' + int(m.sebelum) + ' → <b>' + int(m.sesudah) + '</b></td>' +
          '<td style="font-size:11.8px">' + esc(m.ref) + '<div style="color:var(--text-3)">' + esc(m.catatan || '') + '</div></td>' +
          '<td style="font-size:12px">' + esc(m.oleh) + '</td></tr>';
      }).join('') + '</tbody></table></div>';
  });
}
function renderLow(box) {
  box.innerHTML = '<div id="stkLowBox"><div style="padding:16px"><div class="sk sk-line"></div></div></div>';
  call('stock.low', {}, { silent: true }).then(function (r) {
    var list = (r && r.data) || [], rakit = (r && r.meta && r.meta.rakit_terhambat) || [];
    var html = '<div class="grid-dash w2">';
    html += '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Produk Menipis &amp; Habis</h3><p>' + list.length + ' produk butuh restock</p></div>' +
      '<button class="btn btn-primary btn-sm" id="stkPoAll" type="button">' + svgI('plus') + 'Buat PO</button></div>' +
      '<div class="panel-body tight">' + (list.length ? '<div class="list-plain">' + list.map(function (p) {
        return '<div class="list-row"><span class="av-sm" style="background:var(--surface-2)">' +
          (p.gambar ? '<img alt="" src="' + esc(p.gambar) + '" style="width:100%;height:100%;object-fit:cover;border-radius:inherit"/>' : svgI('box')) + '</span>' +
          '<div style="flex:1;min-width:0"><div class="ttl">' + esc(p.nama) + '</div><div class="sub">' + esc(p.sku) + ' · min ' + (p.stok_min || 3) +
          ' · modal ' + rp(p.harga_beli) + '</div></div>' +
          '<span class="chip ' + (p.habis ? 'chip-rose' : 'chip-amber') + '">' + (p.habis ? 'HABIS' : 'Sisa ' + p.stok) + '</span>' +
          '<button class="mini-btn" data-po="' + esc(p.sku) + '" data-tip="Tambah ke PO" type="button">' + svgI('plus') + '</button></div>';
      }).join('') + '</div>' : emptyState('Semua stok di atas batas minimum 👍', 'check')) + '</div></div>';
    html += '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Rakitan Terhambat</h3><p>Paket PC yang tidak bisa dirakit karena komponen kurang</p></div></div>' +
      '<div class="panel-body tight">' + (rakit.length ? '<div class="list-plain">' + rakit.map(function (b) {
        return '<div class="list-row"><span class="av-sm" style="background:#fff1f2;color:#e11d48">' + svgI('layers') + '</span>' +
          '<div style="flex:1;min-width:0"><div class="ttl">' + esc(b.nama) + '</div>' +
          '<div class="sub">Bisa rakit ' + b.max_buildable + ' paket · kurang: ' + b.komponen.map(function (k) { return esc(k.nama) + ' (' + k.stok + '/' + k.qty + ')'; }).join(', ') + '</div></div>' +
          '<button class="btn btn-ghost btn-sm" data-bomid="' + esc(b.sku) + '" type="button">Kelola BOM</button></div>';
      }).join('') + '</div>' : emptyState('Semua paket rakitan siap dirakit 🎉', 'check')) + '</div></div>';
    html += '</div>';
    box.innerHTML = html;
    on($('#stkPoAll'), 'click', function () { nav('po'); });
    $$('#stkLowBox [data-po]').forEach(function (b) { on(b, 'click', function () { nav('po', { sku: b.getAttribute('data-po') }); }); });
    $$('#stkLowBox [data-bomid]').forEach(function (b) { on(b, 'click', function () { nav('bundles', { sku: b.getAttribute('data-bomid') }); }); });
  });
}

/* -------------------------- PURCHASE ORDER ----------------------------- */
var PO = { status: 'ALL', q: '', draft: [] };
function page_po(param) {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Pembelian (Purchase Order)</h1><p>Buat PO ke supplier, pantau pengiriman, dan terima barang otomatis menambah stok.</p></div>' +
    '<button class="btn btn-primary btn-sm" id="poNew" type="button">' + svgI('plus') + 'PO Baru</button></div>' +
    '<div class="panel mb4"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') + '<input class="inp" id="poQ" placeholder="Cari nomor PO atau supplier…" type="text"/></div>' +
    '<select class="sel-mini" id="poStatus"><option value="ALL">Semua Status</option>' +
    [['DRAFT', 'Draft'], ['DIKIRIM', 'Dikirim'], ['DITERIMA', 'Diterima'], ['BATAL', 'Batal']].map(function (x) {
      return '<option value="' + x[0] + '">' + x[1] + '</option>';
    }).join('') + '</select>' +
    '</div><div class="mt4 flex gap2 wrapf" id="poRingkas"></div></div></div>' +
    '<div class="panel"><div class="panel-body tight" id="poList"></div></div></div>';
  on($('#poQ'), 'input', debounce(function (e) { PO.q = e.target.value.trim(); loadPO(); }, 300));
  on($('#poStatus'), 'change', function (e) { PO.status = e.target.value; loadPO(); });
  on($('#poNew'), 'click', function () { poForm(null, param); });
  if (param && param.sku) { poForm(null, param); }
  return loadPO();
}
function loadPO() {
  var box = $('#poList');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  return call('po.list', { q: PO.q, status: PO.status }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [], meta = (r && r.meta) || {};
    $('#poRingkas').innerHTML = '<span class="chip chip-amber">' + int(meta.terbuka) + ' PO terbuka</span>' +
      '<span class="chip">Nilai terbuka ' + rp(meta.nilai_terbuka) + '</span>' +
      '<span class="chip">' + list.length + ' PO ditampilkan</span>';
    if (!list.length) { box.innerHTML = emptyState('Belum ada PO. Buat PO baru untuk menambah stok dari supplier.', 'truck'); return; }
    S.poList = list;
    box.innerHTML = list.map(function (p) {
      var items = p.items || [];
      return '<div class="card card-pad mb4 rv in" style="border-radius:var(--r-lg)">' +
        '<div class="flex between center wrapf mb2" style="gap:10px">' +
        '<div><b style="font-family:var(--f-mono);font-size:13.5px">' + esc(p.id) + '</b>' +
        '<div style="font-size:12.2px;color:var(--text-3)">' + esc(p.supplier) + ' · dibuat ' + esc(p.tanggal) + ' oleh ' + esc(p.oleh) + '</div></div>' +
        '<div class="flex gap2 center wrapf">' +
        '<span class="chip ' + (p.status === 'DITERIMA' ? 'chip-emerald' : p.status === 'BATAL' ? 'chip-rose' : 'chip-amber') + '">' + esc(p.status) + '</span>' +
        (p.eta && p.status !== 'DITERIMA' ? '<span class="chip">ETA ' + esc(p.eta) + '</span>' : '') +
        '<strong style="font-family:var(--f-display)">' + rp(p.total) + '</strong></div></div>' +
        '<div class="table-wrap"><table class="dt" style="min-width:520px"><thead><tr><th>Item</th><th class="num">Qty</th><th class="num">Harga Beli</th><th class="num">Subtotal</th></tr></thead><tbody>' +
        items.map(function (i2) {
          return '<tr><td><div style="font-weight:650;font-size:12.8px">' + esc(i2.nama || i2.sku) + '</div>' +
            '<div style="font-size:11px;color:var(--text-3)">' + esc(i2.sku) + '</div></td>' +
            '<td class="num">' + int(i2.qty) + '</td><td class="num">' + rp(i2.harga_beli || i2.harga) + '</td>' +
            '<td class="num" style="font-weight:700">' + rp(num(i2.qty) * num(i2.harga_beli || i2.harga)) + '</td></tr>';
        }).join('') + '</tbody></table></div>' +
        (p.catatan ? '<p style="font-size:12.2px;color:var(--text-3);margin-top:8px">📝 ' + esc(p.catatan) + '</p>' : '') +
        '<div class="flex gap2 wrapf mt4">' +
        (p.status !== 'DITERIMA' && p.status !== 'BATAL' ? '<button class="btn btn-primary btn-sm" data-rcv="' + esc(p.id) + '" type="button">' + svgI('checkc') + 'Terima Barang</button>' : '') +
        (p.status === 'DRAFT' ? '<button class="btn btn-ghost btn-sm" data-send="' + esc(p.id) + '" type="button">' + svgI('truck') + 'Tandai Dikirim</button>' : '') +
        '<button class="btn btn-ghost btn-sm" data-edit="' + esc(p.id) + '" type="button">' + svgI('edit') + 'Ubah</button>' +
        '<button class="btn btn-ghost btn-sm" data-wa="' + esc(p.id) + '" type="button">' + svgI('wa') + 'Kirim ke Supplier</button>' +
        '<button class="btn btn-ghost btn-sm" data-del="' + esc(p.id) + '" type="button">' + svgI('trash') + 'Hapus</button>' +
        '</div></div>';
    }).join('');
    $$('#poList [data-rcv]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-rcv');
        confirmBox('Terima barang PO?', 'Stok akan otomatis ditambah sesuai item PO ' + id + '. Produk baru otomatis dibuat bila SKU belum ada.', function () {
          call('po.receive', { id: id }, { btn: b }).then(function (r2) {
            if (!r2 || !r2.ok) return;
            successBox('Barang diterima', r2.data.pesan + ' — ' + r2.data.detail, null, null);
            loadPO(); refreshBadges();
          });
        }, 'Ya, Terima');
      });
    });
    $$('#poList [data-send]').forEach(function (b) {
      on(b, 'click', function () { call('po.status', { id: b.getAttribute('data-send'), status: 'DIKIRIM' }, {}).then(function () { toast('Status PO: DIKIRIM', 'ok'); loadPO(); }); });
    });
    $$('#poList [data-edit]').forEach(function (b) { on(b, 'click', function () { poForm(b.getAttribute('data-edit')); }); });
    $$('#poList [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-del');
        confirmBox('Hapus PO?', 'PO ' + id + ' akan dihapus dari daftar pembelian.', function () {
          call('po.delete', { id: id }, {}).then(function () { toast('PO dihapus', 'warn'); loadPO(); });
        }, 'Ya, Hapus');
      });
    });
    $$('#poList [data-wa]').forEach(function (b) {
      on(b, 'click', function () {
        var p = (S.poList || []).filter(function (x) { return x.id === b.getAttribute('data-wa'); })[0]; if (!p) return;
        var teks = 'Halo ' + p.supplier + ', kami ingin memesan:\n' +
          (p.items || []).map(function (i2) { return '• ' + (i2.nama || i2.sku) + ' — ' + i2.qty + ' unit'; }).join('\n') +
          '\n\nNomor PO: ' + p.id + '\nTotal estimasi: ' + rp(p.total) + '\nMohon konfirmasi ketersediaan & ETA pengiriman. Terima kasih.';
        window.open(waLink(p.wa || (S.settings || {}).wa, teks), '_blank');
      });
    });
  });
}
function poForm(id, param) {
  call('po.list', { status: 'ALL' }, { silent: true }).then(function (r0) {
    var existing = (r0 && r0.data || []).filter(function (x) { return x.id === id; })[0];
    var draft = existing ? (existing.items || []).slice() : [];
    if (param && param.sku) {
      call('pos.lookup', { q: param.sku, limit: 1 }, { silent: true }).then(function (rp2) {
        var prod = (rp2 && rp2.data || [])[0];
        if (prod) draft.push({ sku: prod.sku, nama: prod.nama, qty: Math.max(1, (prod.stok_min || 3) * 2 - num(prod.stok)), harga_beli: num(prod.harga_beli), kategori: prod.kategori });
        openPoForm(existing, draft);
      });
      return;
    }
    openPoForm(existing, draft);
  });
}
function openPoForm(existing, draft) {
  var supp = (S.settings || {}).supplier_default || '';
  formModal({
    title: existing ? 'Ubah PO ' + existing.id : (draft.length ? 'PO Baru (dari stok menipis)' : 'PO Baru'),
    sub: 'Supplier akan menerima rincian ini via WhatsApp.', size: 'lg',
    values: existing || { supplier: supp, status: 'DRAFT' },
    fields: [
      { k: 'supplier', l: 'Nama Supplier', t: 'text', req: true, ph: 'PT Distribusi Komputer Nusantara' },
      { k: 'wa', l: 'WhatsApp Supplier', t: 'tel', half: true, ph: '628xxxxxxxxxx' },
      { k: 'eta', l: 'Estimasi Kedatangan', t: 'date', half: true },
      { k: 'status', l: 'Status', t: 'select', opts: [['DRAFT', 'Draft'], ['DIKIRIM', 'Sudah dipesan'], ['DITERIMA', 'Sudah diterima']], half: true },
      { k: 'catatan', l: 'Catatan', t: 'text', ph: 'Termin pembayaran, ongkir, dsb.' },
      { k: 'items', t: 'custom', html: poItemsHtml(draft) }
    ],
    submitLabel: existing ? 'Simpan PO' : 'Buat PO',
    onSubmit: function (v, act) {
      var items = collectPoItems();
      if (!items.length) { toast('Tambahkan minimal satu item terlebih dahulu', 'warn'); return; }
      var payload = Object.assign({}, v, { id: existing ? existing.id : '', items: items });
      call('po.save', payload, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        toast('PO ' + r.data.id + ' tersimpan (' + rp(r.data.total) + ')', 'ok');
        if (S.page === 'po') loadPO(); else nav('po');
      });
    }
  });
  bindPoEditor(draft);
}
function poItemsHtml(draft) {
  return '<div class="lbl" style="margin-bottom:8px">Item Pembelian</div>' +
    '<div class="flex gap2 mb2 wrapf">' +
    '<div class="search-box" style="flex:1;min-width:180px">' + svgI('search') + '<input class="inp" id="poFind" placeholder="Cari SKU / nama produk…" type="text"/></div>' +
    '<button class="btn btn-ghost btn-sm" id="poAddBlank" type="button">' + svgI('plus') + 'Item Manual</button></div>' +
    '<div id="poSug" class="mb2"></div><div id="poItems"></div>' +
    '<div class="tot-row grand" style="border-top:1px solid var(--line)"><span>TOTAL PO</span><span class="v" id="poTotal">Rp0</span></div>';
}
function bindPoEditor(draft) {
  PO.draft = draft || [];
  renderPoItems();
  on($('#poAddBlank'), 'click', function () { PO.draft.push({ sku: '', nama: '', qty: 1, harga_beli: 0 }); renderPoItems(); });
  on($('#poFind'), 'input', debounce(function (e) {
    var q = e.target.value.trim();
    if (q.length < 2) { $('#poSug').innerHTML = ''; return; }
    call('pos.lookup', { q: q, limit: 8 }, { silent: true }).then(function (r) {
      var list = (r && r.data) || [];
      $('#poSug').innerHTML = list.map(function (p) {
        return '<button class="chip-filter" data-pick="' + esc(p.sku) + '" type="button">' + svgI('plus') + esc(p.nama) +
          ' <span style="color:var(--text-3)">· stok ' + p.stok + '</span></button>';
      }).join(' ');
      $$('#poSug [data-pick]').forEach(function (b) {
        on(b, 'click', function () {
          var p = list.filter(function (x) { return x.sku === b.getAttribute('data-pick'); })[0];
          PO.draft.push({ sku: p.sku, nama: p.nama, qty: 1, harga_beli: num(p.harga_beli), kategori: p.kategori });
          renderPoItems(); $('#poSug').innerHTML = ''; $('#poFind').value = '';
        });
      });
    });
  }, 260));
}
function renderPoItems() {
  var box = document.getElementById('poItems');
  if (!box) return;
  box.innerHTML = PO.draft.length ? '<div class="table-wrap"><table class="dt" style="min-width:520px"><thead><tr><th>Item</th>' +
    '<th class="num" style="width:100px">Qty</th><th class="num" style="width:150px">Harga Beli</th><th class="num">Subtotal</th><th></th></tr></thead><tbody>' +
    PO.draft.map(function (i2, ix) {
      return '<tr><td><input class="inp" data-f="nama" data-ix="' + ix + '" placeholder="Nama item" type="text" value="' + esc(i2.nama) + '" style="min-width:140px"/>' +
        '<input class="inp mt2" data-f="sku" data-ix="' + ix + '" placeholder="SKU" style="font-size:11.5px;margin-top:6px" type="text" value="' + esc(i2.sku) + '"/></td>' +
        '<td class="num"><input class="inp num" data-f="qty" data-ix="' + ix + '" style="text-align:right" type="number" value="' + num(i2.qty) + '"/></td>' +
        '<td class="num"><input class="inp num" data-f="harga_beli" data-ix="' + ix + '" style="text-align:right" type="number" value="' + num(i2.harga_beli) + '"/></td>' +
        '<td class="num" style="font-weight:700">' + rp(num(i2.qty) * num(i2.harga_beli)) + '</td>' +
        '<td><button class="mini-btn danger" data-rm="' + ix + '" type="button">' + svgI('trash') + '</button></td></tr>';
    }).join('') + '</tbody></table></div>' : '<div class="card card-pad soft" style="border-radius:var(--r-md);font-size:12.8px;color:var(--text-3)">Belum ada item. Cari produk di atas atau tambahkan item manual.</div>';
  var tot = sum(PO.draft, function (x) { return num(x.qty) * num(x.harga_beli); });
  var t = document.getElementById('poTotal'); if (t) t.textContent = rp(tot);
  $$('#poItems [data-f]').forEach(function (inp) {
    on(inp, 'change', function () {
      var ix = num(inp.getAttribute('data-ix')), f = inp.getAttribute('data-f');
      PO.draft[ix][f] = (f === 'qty' || f === 'harga_beli') ? num(inp.value) : inp.value;
      renderPoItems();
    });
  });
  $$('#poItems [data-rm]').forEach(function (b) {
    on(b, 'click', function () { PO.draft.splice(num(b.getAttribute('data-rm')), 1); renderPoItems(); });
  });
}
function collectPoItems() {
  return PO.draft.filter(function (x) { return x.nama && num(x.qty) > 0; })
    .map(function (x) { return { sku: x.sku || ('SKU-' + Math.random().toString(36).slice(2, 7).toUpperCase()), nama: x.nama, qty: num(x.qty), harga_beli: num(x.harga_beli) }; });
}

/* =========================== 15. CRM, SERVICE, TRADE-IN ================== */
var CRM = { q: '', tier: 'ALL', sort: 'belanja' };
function page_customers() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>CRM Pelanggan</h1><p>Tier otomatis dari total belanja, poin loyalitas, dan riwayat transaksi.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="crmBroadcast" type="button">' + svgI('wa') + 'Broadcast Promo</button>' +
    '<button class="btn btn-primary btn-sm" id="crmNew" type="button">' + svgI('plus') + 'Pelanggan Baru</button></div></div>' +
    '<div class="grid-dash w4 mb6" id="crmStats"></div>' +
    '<div class="panel"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') + '<input class="inp" id="crmQ" placeholder="Cari nama, WhatsApp, email, atau kota…" type="text"/></div>' +
    '<select class="sel-mini" id="crmTier"><option value="ALL">Semua Tier</option>' +
    ['BRONZE', 'SILVER', 'GOLD', 'PLATINUM'].map(function (t) { return '<option value="' + t + '">' + t + '</option>'; }).join('') + '</select>' +
    '<select class="sel-mini" id="crmSort"><option value="belanja">Belanja Terbanyak</option><option value="poin">Poin Terbanyak</option>' +
    '<option value="baru">Terbaru</option><option value="nama">Nama A-Z</option></select>' +
    '</div></div></div>' +
    '<div class="panel mt4"><div class="panel-body tight" id="crmList"></div></div></div>';
  on($('#crmQ'), 'input', debounce(function (e) { CRM.q = e.target.value.trim(); loadCrm(); }, 300));
  on($('#crmTier'), 'change', function (e) { CRM.tier = e.target.value; loadCrm(); });
  on($('#crmSort'), 'change', function (e) { CRM.sort = e.target.value; loadCrm(); });
  on($('#crmNew'), 'click', function () { customerForm(null); });
  on($('#crmBroadcast'), 'click', broadcastDialog);
  return loadCrm();
}
function tierChip(t) {
  var meta = (DEMO.tierMeta ? DEMO.tierMeta(t) : null) || {};
  var color = t === 'PLATINUM' ? 'linear-gradient(135deg,#0f172a,#334155)' : t === 'GOLD' ? 'linear-gradient(135deg,#f59e0b,#d97706)'
    : t === 'SILVER' ? 'linear-gradient(135deg,#94a3b8,#64748b)' : 'linear-gradient(135deg,#c2703a,#a16207)';
  return '<span class="tier-badge" style="background:' + color + ';color:#fff">' + esc(t || 'BRONZE') +
    (meta.diskon_pct ? ' · ' + meta.diskon_pct + '%' : '') + '</span>';
}
function loadCrm() {
  var box = $('#crmList');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  return call('customer.list', { q: CRM.q, tier: CRM.tier, sort: CRM.sort }, { silent: true }).then(function (r) {
    if (!r || !r.ok) { box.innerHTML = emptyState('Gagal memuat data pelanggan.', 'alert'); return; }
    var list = r.data || [], meta = r.meta || {}, tc = meta.tier || {};
    $('#crmStats').innerHTML = [
      ['Total Pelanggan', int(meta.total), 'users', 'var(--grad-brand)'],
      ['Nilai Belanja', rp(meta.total_belanja), 'wallet', 'linear-gradient(135deg,#10b981,#059669)'],
      ['Poin Beredar', int(meta.total_poin), 'gift', 'linear-gradient(135deg,#8b5cf6,#7c3aed)'],
      ['Platinum / Gold', int(tc.PLATINUM) + ' / ' + int(tc.GOLD), 'award', 'linear-gradient(135deg,#f59e0b,#d97706)']
    ].map(function (k) {
      return '<div class="kpi"><div class="top"><span class="ic" style="background:' + k[3] + '">' + svgI(k[2]) + '</span></div>' +
        '<div class="lbl">' + k[0] + '</div><div class="val" style="font-size:20px">' + k[1] + '</div></div>';
    }).join('');
    if (!list.length) { box.innerHTML = emptyState('Belum ada pelanggan terdaftar. Pelanggan otomatis dibuat dari pesanan online atau POS.', 'users'); return; }
    S.crmList = list;
    box.innerHTML = '<div class="table-wrap"><table class="dt"><thead><tr><th>Pelanggan</th><th>Tier</th>' +
      '<th class="num">Total Belanja</th><th class="num">Transaksi</th><th class="num">Poin</th><th></th></tr></thead><tbody>' +
      list.map(function (c) {
        return '<tr data-view="' + esc(c.id) + '" style="cursor:pointer">' +
          '<td><div class="flex gap3 center"><span class="av-sm" style="width:38px;height:38px;border-radius:11px;font-size:13px">' + initials(c.nama) + '</span>' +
          '<div><div style="font-weight:700;font-size:13.2px">' + esc(c.nama) + '</div>' +
          '<div style="font-size:11.5px;color:var(--text-3)">' + esc(c.wa) + (c.kota ? ' · ' + esc(c.kota) : '') + '</div></div></div></td>' +
          '<td>' + tierChip(c.tier) + '</td>' +
          '<td class="num" style="font-weight:750">' + rp(c.total_belanja) + '</td>' +
          '<td class="num">' + int(c.trx) + '×</td>' +
          '<td class="num"><span class="chip chip-brand">' + int(c.poin) + '</span></td>' +
          '<td><div class="row-actions">' +
          '<button class="mini-btn" data-pt="' + esc(c.id) + '" data-tip="Kelola poin" type="button">' + svgI('gift') + '</button>' +
          '<button class="mini-btn" data-wa="' + esc(c.id) + '" data-tip="Chat WA" type="button">' + svgI('wa') + '</button>' +
          '<button class="mini-btn" data-edit="' + esc(c.id) + '" data-tip="Ubah" type="button">' + svgI('edit') + '</button>' +
          '<button class="mini-btn danger" data-del="' + esc(c.id) + '" data-tip="Hapus" type="button">' + svgI('trash') + '</button>' +
          '</div></td></tr>';
      }).join('') + '</tbody></table></div>';
    $$('#crmList tr[data-view]').forEach(function (tr) {
      on(tr, 'click', function (e) { if (e.target.closest('button')) return; openCustomer(tr.getAttribute('data-view')); });
    });
    $$('#crmList [data-edit]').forEach(function (b) { on(b, 'click', function () { customerForm(b.getAttribute('data-edit')); }); });
    $$('#crmList [data-pt]').forEach(function (b) { on(b, 'click', function () { pointsDialog(b.getAttribute('data-pt')); }); });
    $$('#crmList [data-wa]').forEach(function (b) {
      on(b, 'click', function () {
        var c = list.filter(function (x) { return x.id === b.getAttribute('data-wa'); })[0]; if (!c) return;
        window.open(waLink(c.wa, 'Halo ' + c.nama + ', terima kasih telah berbelanja di ' + ((S.settings || {}).nama_toko || 'Sarinata') + '. Ada yang bisa kami bantu?'), '_blank');
      });
    });
    $$('#crmList [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        var c = list.filter(function (x) { return x.id === b.getAttribute('data-del'); })[0] || {};
        confirmBox('Hapus pelanggan?', 'Data ' + (c.nama || '') + ' akan dihapus. Riwayat transaksi tetap tersimpan.', function () {
          call('customer.delete', { id: c.id }, {}).then(function () { toast('Pelanggan dihapus', 'warn'); loadCrm(); });
        }, 'Ya, Hapus');
      });
    });
  });
}
function customerForm(id) {
  call('customer.get', { id: id }, { silent: true }).then(function (r) {
    var c = (!id ? {} : (r && r.data) || {});
    formModal({
      title: id ? 'Ubah ' + c.nama : 'Pelanggan Baru',
      sub: id ? ('Tier ' + c.tier + ' · ' + c.trx + ' transaksi · poin ' + c.poin) : 'Data otomatis tersinkron dengan transaksi POS.',
      size: 'md',
      values: c,
      fields: [
        { k: 'nama', l: 'Nama Lengkap', t: 'text', req: true },
        { k: 'wa', l: 'WhatsApp', t: 'tel', req: true, half: true, ph: '08xxxxxxxxxx' },
        { k: 'email', l: 'Email', t: 'text', half: true },
        { k: 'kota', l: 'Kota', t: 'text', half: true },
        { k: 'alamat', l: 'Alamat', t: 'textarea', style: 'min-height:70px' },
        { k: 'catatan', l: 'Catatan Internal', t: 'textarea', ph: 'Preferensi produk, ukuran, riwayat keluhan…', style: 'min-height:70px' }
      ],
      submitLabel: id ? 'Simpan Perubahan' : 'Simpan Pelanggan',
      onSubmit: function (v, act) {
        v.id = id;
        call('customer.save', v, { btn: act.button }).then(function (r2) {
          if (!r2 || !r2.ok) return;
          act.close(); toast('Data pelanggan tersimpan', 'ok'); loadCrm();
        });
      }
    });
  });
}
function openCustomer(id) {
  call('customer.get', { id: id }, { silent: true }).then(function (r) {
    if (!r || !r.ok) return;
    var c = r.data, m = r.meta || {};
    var nxt = m.next_tier;
    var html = '<div style="display:flex;flex-direction:column;gap:14px">' +
      '<div class="flex gap4 center wrapf">' +
      '<span class="avatar-lg">' + initials(c.nama) + '</span>' +
      '<div style="flex:1;min-width:180px"><h3 style="font-size:19px">' + esc(c.nama) + '</h3>' +
      '<div style="font-size:12.8px;color:var(--text-3)">' + esc(c.wa) + (c.email ? ' · ' + esc(c.email) : '') + '</div>' +
      '<div class="mt2">' + tierChip(c.tier) + '</div></div>' +
      '<div style="text-align:right"><div style="font-size:11.5px;color:var(--text-3)">Total belanja</div>' +
      '<div style="font-family:var(--f-display);font-size:22px;font-weight:800">' + rp(c.total_belanja) + '</div>' +
      '<div style="font-size:12px;color:var(--text-3)">' + int(c.trx) + ' transaksi · ' + int(c.poin) + ' poin (' + rp(m.nilai_poin) + ')</div></div></div>' +
      (nxt ? '<div class="progress" style="height:10px"><i style="width:' + clamp(num(c.total_belanja) / num(nxt.ambang) * 100, 3, 100) + '%"></i></div>' +
        '<p style="font-size:12.3px;color:var(--text-3)">Butuh ' + rp(nxt.butuh) + ' lagi untuk naik ke tier <b>' + nxt.tier + '</b>.</p>' : '') +
      (c.alamat ? '<div class="card card-pad soft" style="border-radius:var(--r-md)"><div class="lbl">Alamat</div><p style="font-size:13px">' + esc(c.alamat) + '</p></div>' : '') +
      '<div class="grid-dash w3">' +
      ['order|Transaksi|receipt', 'service|Service|wrench', 'tradein|Tukar Tambah|refresh'].map(function (x) {
        var p = x.split('|');
        return '<div class="kpi" style="padding:14px"><div class="lbl">' + p[1] + '</div><div class="val" style="font-size:20px">' + ((m[p[0]] || []).length) + '</div></div>';
      }).join('') + '</div>' +
      '<h4 style="font-size:13.5px">Riwayat Transaksi</h4>' +
      ((m.order || []).length ? '<div class="table-wrap"><table class="dt" style="min-width:460px"><thead><tr><th>Invoice</th><th>Tanggal</th><th class="num">Total</th><th>Status</th></tr></thead><tbody>' +
        m.order.slice(0, 8).map(function (o) {
          return '<tr><td style="font-family:var(--f-mono);font-size:12px">' + esc(o.id) + '</td><td style="font-size:12.2px">' + esc(o.tanggal) + '</td>' +
            '<td class="num" style="font-weight:700">' + rp(o.total) + '</td>' +
            '<td><span class="chip ' + (o.status === 'LUNAS' ? 'chip-emerald' : o.status === 'VOID' ? 'chip-rose' : 'chip-amber') + '">' + esc(o.status) + '</span></td></tr>';
        }).join('') + '</tbody></table></div>' : emptyState('Belum ada transaksi.', 'receipt')) +
      ((m.service || []).length ? '<h4 style="font-size:13.5px">Riwayat Service</h4><div class="list-plain">' + m.service.map(function (s0) {
        return '<div class="list-row"><span class="av-sm">' + svgI('wrench') + '</span><div style="flex:1"><div class="ttl">' + esc(s0.perangkat) + '</div>' +
          '<div class="sub">' + esc(s0.keluhan) + '</div></div><span class="chip">' + esc(s0.status) + '</span></div>';
      }).join('') + '</div>' : '') +
      ((m.tradein || []).length ? '<h4 style="font-size:13.5px">Tukar Tambah</h4><div class="list-plain">' + m.tradein.map(function (t) {
        return '<div class="list-row"><span class="av-sm">' + svgI('refresh') + '</span><div style="flex:1"><div class="ttl">' + esc(t.perangkat) + '</div>' +
          '<div class="sub">' + esc(t.id) + ' · ' + rp(t.penawaran) + '</div></div><span class="chip">' + esc(t.status) + '</span></div>';
      }).join('') + '</div>' : '') + '</div>';
    formModal({
      title: 'Profil Pelanggan', sub: c.id + ' · ' + c.wa, size: 'lg', fields: [{ k: 'x', t: 'custom', html: html }],
      submitLabel: 'Kelola Poin',
      onSubmit: function (v, act) { act.close(); pointsDialog(c.id); }
    });
    var foot = $('.modal-panel', $('#mForm')).querySelector('.modal-foot');
    foot.insertAdjacentHTML('afterbegin',
      '<button class="btn btn-ghost" data-a="edit" type="button">' + svgI('edit') + 'Ubah Data</button>' +
      '<button class="btn btn-wa" data-a="wa" type="button">' + svgI('wa') + 'Chat WhatsApp</button>');
    on(foot.querySelector('[data-a="edit"]'), 'click', function () { closeModal('mForm'); customerForm(c.id); });
    on(foot.querySelector('[data-a="wa"]'), 'click', function () {
      window.open(waLink(c.wa, 'Halo ' + c.nama + ', ada penawaran menarik untuk Anda di ' + ((S.settings || {}).nama_toko || 'Sarinadinet') + '!'), '_blank');
    });
  });
}
function pointsDialog(id) {
  call('customer.get', { id: id }, { silent: true }).then(function (r) {
    var c = (r && r.data) || {};
    formModal({
      title: 'Kelola Poin Loyalitas', sub: c.nama + ' · poin saat ini ' + int(c.poin) + ' (≈ ' + rp((r.meta || {}).nilai_poin) + ')', size: 'sm',
      fields: [
        { k: 'poin', l: 'Jumlah Poin', t: 'number', req: true, hint: 'Isi angka positif untuk menambah, negatif untuk mengurangi.' },
        { k: 'alasan', l: 'Alasan', t: 'text', req: true, ph: 'Bonus event, kompensasi keterlambatan, penukaran hadiah…' }
      ],
      submitLabel: 'Simpan Poin',
      onSubmit: function (v, act) {
        call('customer.points', { id: id, poin: num(v.poin), alasan: v.alasan }, { btn: act.button }).then(function (r2) {
          if (!r2 || !r2.ok) return;
          act.close();
          toast('Poin ' + c.nama + ' kini ' + int(r2.data.poin), 'ok');
          if (S.page === 'customers') loadCrm(); else refreshBadges();
        });
      }
    });
  });
}
function broadcastDialog() {
  call('customer.list', { tier: CRM.tier, sort: 'belanja' }, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    var opts = [{ v: 'ALL', l: 'Semua pelanggan (' + list.length + ')' }].concat(['BRONZE', 'SILVER', 'GOLD', 'PLATINUM'].map(function (t) {
      return { v: t, l: 'Tier ' + t + ' (' + list.filter(function (c) { return c.tier === t; }).length + ')' };
    }));
    formModal({
      title: 'Broadcast Promo WhatsApp', sub: 'Pilih audiens lalu kirim pesan satu per satu (wa.me, tanpa API berbayar).', size: 'md',
      fields: [
        { k: 'audiens', l: 'Audiens', t: 'select', opts: opts },
        { k: 'pesan', l: 'Isi Pesan', t: 'textarea', req: true, style: 'min-height:120px',
          def: 'Halo {nama}, ada promo spesial di {toko} minggu ini! Diskon s/d 20% laptop & aksesoris, gratis ongkir min. belanja Rp1.500.000. Balas pesan ini untuk info stok terbaru 🎉' }
      ],
      submitLabel: 'Kirim Sekarang',
      onSubmit: function (v, act) {
        var target = list.filter(function (c) { return v.audiens === 'ALL' || c.tier === v.audiens; });
        if (!target.length) { toast('Tidak ada pelanggan pada audiens ini', 'warn'); return; }
        act.close();
        var i = 0;
        var nextOne = function () {
          if (i >= target.length) { successBox('Broadcast selesai', target.length + ' tab WhatsApp dibuka. Kirim pesan pada setiap tab.', null, null); return; }
          var c = target[i++];
          var msg = String(v.pesan).replace(/\{nama\}/g, c.nama).replace(/\{toko\}/g, (S.settings || {}).nama_toko || 'Sarinadinet');
          window.open(waLink(c.wa, msg), '_blank');
          setTimeout(nextOne, 900);
        };
        confirmBox('Buka ' + target.length + ' tab WhatsApp?', 'Browser akan membuka satu tab per pelanggan. Izinkan popup untuk fitur ini.', nextOne, 'Ya, Mulai');
      }
    });
  });
}

/* ------------------------------ SERVICE -------------------------------- */
var SVC = { q: '', status: 'ALL', teknisi: 'ALL' };
var SVC_FLOW = ['MASUK', 'ANTRI', 'DIAGNOSA', 'MENUNGGU_PART', 'DIKERJAKAN', 'SELESAI', 'DIAMBIL'];
function page_service() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Papan Kerja Service</h1><p>Geser kartu antar kolom (drag &amp; drop) atau gunakan tombol untuk memindahkan status.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="svcExport" type="button">' + svgI('download') + 'Ekspor</button>' +
    '<button class="btn btn-primary btn-sm" id="svcNew" type="button">' + svgI('plus') + 'Job Service Baru</button></div></div>' +
    '<div class="panel mb4"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') + '<input class="inp" id="svcQ" placeholder="Cari tiket, nama pelanggan, atau perangkat…" type="text"/></div>' +
    '<button class="btn btn-ghost btn-sm" id="svcReload" type="button">' + svgI('refresh') + 'Segarkan</button>' +
    '</div><div class="mt4 flex gap2 wrapf" id="svcStats"></div></div></div>' +
    '<div class="kanban" id="svcBoard"></div></div>';
  on($('#svcQ'), 'input', debounce(function (e) { SVC.q = e.target.value.trim(); loadService(); }, 300));
  on($('#svcNew'), 'click', function () { serviceForm(null); });
  on($('#svcReload'), 'click', loadService);
  on($('#svcExport'), 'click', function () {
    var rows = (S.svcList || []).map(function (j) {
      return [j.id, j.tanggal, j.nama, j.wa, j.perangkat, j.keluhan.replace(/\n/g, ' '), j.status, j.teknisi, j.biaya];
    });
    if (!rows.length) { toast('Tidak ada data service', 'warn'); return; }
    downloadCSV('service-' + dayStr() + '.csv', ['Tiket', 'Tanggal', 'Nama', 'WA', 'Perangkat', 'Keluhan', 'Status', 'Teknisi', 'Biaya'], rows);
  });
  return loadService();
}
function loadService() {
  var board = $('#svcBoard');
  board.innerHTML = '<div class="kcol"><div class="sk sk-line"></div><div class="sk sk-line"></div></div><div class="kcol"><div class="sk sk-line"></div></div>';
  return call('service.list', { q: SVC.q, status: 'ALL' }, { silent: true }).then(function (r) {
    if (!r || !r.ok) { board.innerHTML = emptyState('Gagal memuat papan service.', 'alert'); return; }
    var list = r.data || [], meta = r.meta || {}, papan = meta.papan || {};
    S.svcList = list;
    $('#svcStats').innerHTML = '<span class="chip chip-brand">' + list.length + ' job total</span>' +
      '<span class="chip chip-amber">' + int(papan.DIKERJAKAN) + ' dikerjakan</span>' +
      '<span class="chip" style="background:#fff1f2;color:#be123c">' + int(papan.MENUNGGU_PART) + ' menunggu part</span>' +
      '<span class="chip chip-emerald">' + int(papan.SELESAI) + ' selesai</span>' +
      '<span class="chip">Nilai berjalan ' + rp(meta.nilai_berjalan) + '</span>';
    board.innerHTML = SVC_FLOW.map(function (st) {
      var items = list.filter(function (j) { return j.status === st; });
      return '<div class="kcol" data-col="' + st + '">' +
        '<div class="kcol-head"><span class="nm">' + st.replace(/_/g, ' ') + '</span><span class="n">' + items.length + '</span></div>' +
        (items.length ? items.map(function (j) {
          return '<article class="kcard" data-id="' + esc(j.id) + '" draggable="true">' +
            '<div class="flex between center"><span class="id">' + esc(j.id) + '</span><span class="chip ' + (j.biaya > 0 ? 'chip-emerald' : '') + '" style="font-size:10.5px">' + (j.biaya > 0 ? rp(j.biaya) : 'belum ada biaya') + '</span></div>' +
            '<div class="nm">' + esc(j.nama) + '</div>' +
            '<div class="dev">' + esc(j.perangkat) + '</div>' +
            '<div class="progress" style="height:5px;margin-bottom:8px"><i style="width:' + j.progres + '%"></i></div>' +
            '<div class="ft"><span>' + esc(j.teknisi || 'belum ada teknisi') + '</span>' +
            '<span class="flex gap2"><button class="mini-btn" data-open="' + esc(j.id) + '" data-tip="Detail" type="button">' + svgI('eye') + '</button>' +
            (st === 'SELESAI' ? '<button class="mini-btn" data-inv="' + esc(j.id) + '" data-tip="Buat invoice" type="button">' + svgI('receipt') + '</button>' : '') + '</span></div>' +
            '</article>';
        }).join('') : '<div class="empty-mini" style="padding:22px 10px"><p style="font-size:12px">Kosong</p></div>') +
        '</div>';
    }).join('');
    bindKanban();
  });
}
function bindKanban() {
  $$('#svcBoard .kcard').forEach(function (card) {
    card.addEventListener('dragstart', function (e) {
      card.classList.add('dragging');
      e.dataTransfer.setData('text/plain', card.getAttribute('data-id'));
      e.dataTransfer.effectAllowed = 'move';
    });
    card.addEventListener('dragend', function () { card.classList.remove('dragging'); });
    on(card, 'click', function (e) { if (e.target.closest('button')) return; serviceDetail(card.getAttribute('data-id')); });
  });
  $$('#svcBoard .kcol').forEach(function (col) {
    ['dragenter', 'dragover'].forEach(function (ev) {
      col.addEventListener(ev, function (e) { e.preventDefault(); col.classList.add('dragover'); });
    });
    ['dragleave', 'drop'].forEach(function (ev) {
      col.addEventListener(ev, function (e) { e.preventDefault(); col.classList.remove('dragover'); });
    });
    col.addEventListener('drop', function (e) {
      e.preventDefault();
      var id = e.dataTransfer.getData('text/plain');
      var st = col.getAttribute('data-col');
      if (!id) return;
      call('service.status', { id: id, status: st }, { silent: true }).then(function (r) {
        if (!r || !r.ok) return;
        toast('Tiket ' + id + ' → ' + st.replace(/_/g, ' '), 'ok');
        loadService(); refreshBadges();
      });
    });
  });
  $$('#svcBoard [data-open]').forEach(function (b) { on(b, 'click', function (e) { e.stopPropagation(); serviceDetail(b.getAttribute('data-open')); }); });
  $$('#svcBoard [data-inv]').forEach(function (b) { on(b, 'click', function (e) { e.stopPropagation(); invoiceService(b.getAttribute('data-inv')); }); });
}
function serviceForm(id) {
  var j = (S.svcList || []).filter(function (x) { return x.id === id; })[0] || {};
  formModal({
    title: id ? 'Ubah Job ' + id : 'Job Service Baru', sub: 'Data ini muncul di papan kerja dan halaman lacak pelanggan.', size: 'lg',
    values: j,
    fields: [
      { k: 'nama', l: 'Nama Pelanggan', t: 'text', req: true, half: true },
      { k: 'wa', l: 'WhatsApp', t: 'tel', req: true, half: true },
      { k: 'perangkat', l: 'Perangkat', t: 'text', req: true, ph: 'ASUS X441BA / PC Rakitan 2023' },
      { k: 'kategori', l: 'Kategori', t: 'select', opts: ['Laptop', 'PC Desktop', 'Monitor', 'Printer', 'Aksesoris'], half: true },
      { k: 'mode', l: 'Metode', t: 'select', opts: [['BAWA_KE_TOKO', 'Bawa ke toko'], ['PANGGILAN', 'Panggilan / pickup'], ['KONSULTASI', 'Konsultasi']], half: true },
      { k: 'keluhan', l: 'Keluhan Pelanggan', t: 'textarea', req: true, style: 'min-height:80px' },
      { k: 'diagnosa', l: 'Diagnosa Teknisi', t: 'textarea', style: 'min-height:70px' },
      { k: 'teknisi', l: 'Teknisi', t: 'text', half: true, ph: 'Teknisi Dua' },
      { k: 'status', l: 'Status', t: 'select', opts: SVC_FLOW.concat(['BATAL']), half: true },
      { k: 'estimasi', l: 'Estimasi Biaya (Rp)', t: 'money', half: true },
      { k: 'biaya', l: 'Biaya Final (Rp)', t: 'money', half: true },
      { k: 'garansi', l: 'Garansi Service', t: 'select', opts: ['7 hari', '30 hari', '60 hari', '90 hari'], half: true },
      { k: 'catatan', l: 'Catatan Internal', t: 'text' }
    ],
    submitLabel: id ? 'Simpan Job' : 'Buat Job Service',
    onSubmit: function (v, act) {
      v.id = id;
      call('service.save', v, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        toast('Job ' + r.data.id + ' tersimpan', 'ok');
        loadService(); refreshBadges();
      });
    }
  });
}
function serviceDetail(id) {
  var j = (S.svcList || []).filter(function (x) { return x.id === id; })[0];
  if (!j) return;
  var html = '<div style="display:flex;flex-direction:column;gap:14px">' +
    '<div class="detail-grid">' + infoRow('Tiket', j.id) + infoRow('Masuk', j.tanggal) + infoRow('Perangkat', j.perangkat) +
    infoRow('Pelanggan', j.nama + ' · ' + j.wa) + infoRow('Metode', j.mode) + infoRow('Teknisi', j.teknisi || '—') +
    infoRow('Estimasi', rp(j.estimasi)) + infoRow('Biaya final', rp(j.biaya)) + '</div>' +
    '<div><div class="lbl">Keluhan</div><p style="font-size:13px;color:var(--text-2);line-height:1.7">' + esc(j.keluhan) + '</p></div>' +
    (j.diagnosa ? '<div><div class="lbl">Diagnosa</div><p style="font-size:13px;color:var(--text-2);line-height:1.7">' + esc(j.diagnosa) + '</p></div>' : '') +
    '<div><div class="lbl">Progres (' + j.progres + '%)</div><div class="progress"><i style="width:' + j.progres + '%"></i></div></div>' +
    '<div class="flex gap2 wrapf">' + SVC_FLOW.map(function (st) {
      return '<button class="chip-filter ' + (j.status === st ? 'on' : '') + '" data-st="' + st + '" type="button">' + st.replace(/_/g, ' ') + '</button>';
    }).join('') + '</div></div>';
  formModal({
    title: 'Job ' + j.id, sub: j.perangkat + ' · ' + j.status, size: 'lg',
    fields: [{ k: 'x', t: 'custom', html: html }],
    submitLabel: 'Buat Invoice',
    onSubmit: function (v, act) { act.close(); invoiceService(j.id); }
  });
  var foot = $('.modal-panel', $('#mForm')).querySelector('.modal-foot');
  foot.insertAdjacentHTML('afterbegin',
    '<button class="btn btn-ghost" data-a="edit" type="button">' + svgI('edit') + 'Ubah</button>' +
    '<button class="btn btn-ghost" data-a="wa" type="button">' + svgI('wa') + 'Update WA</button>' +
    '<button class="btn btn-ghost" data-a="del" type="button" style="color:#e11d48">' + svgI('trash') + 'Hapus</button>');
  on(foot.querySelector('[data-a="edit"]'), 'click', function () { closeModal('mForm'); serviceForm(j.id); });
  on(foot.querySelector('[data-a="wa"]'), 'click', function () {
    window.open(waLink(j.wa, 'Halo ' + j.nama + ', update service ' + j.id + ' (' + j.perangkat + '): status saat ini *' + j.status.replace(/_/g, ' ') + '* (' + j.progres + '% selesai).' +
      (j.biaya ? ' Estimasi biaya ' + rp(j.biaya) + '.' : '') + ' Terima kasih telah mempercayakan perangkat Anda kepada kami.'), '_blank');
  });
  on(foot.querySelector('[data-a="del"]'), 'click', function () {
    confirmBox('Hapus job service?', 'Tiket ' + j.id + ' akan dihapus permanen dari papan kerja.', function () {
      call('service.delete', { id: j.id }, {}).then(function () { closeModal('mForm'); toast('Job dihapus', 'warn'); loadService(); });
    }, 'Ya, Hapus');
  });
  $$('#fmForm [data-st]').forEach(function (b) {
    on(b, 'click', function () {
      call('service.status', { id: j.id, status: b.getAttribute('data-st') }, {}).then(function (r) {
        if (!r || !r.ok) return;
        closeModal('mForm'); toast('Status → ' + b.getAttribute('data-st').replace(/_/g, ' '), 'ok');
        loadService(); refreshBadges();
      });
    });
  });
}
function invoiceService(id) {
  var j = (S.svcList || []).filter(function (x) { return x.id === id; })[0] || {};
  formModal({
    title: 'Invoice Service ' + id, sub: 'Tagihan akan tercatat sebagai transaksi tipe SERVICE dan stok part berkurang otomatis.', size: 'md',
    values: { biaya: j.biaya || j.estimasi, metode: 'TUNAI' },
    fields: [
      { k: 'biaya', l: 'Biaya Jasa Service (Rp)', t: 'money', req: true },
      { k: 'metode', l: 'Metode Pembayaran', t: 'select', opts: ['TUNAI', 'TRANSFER', 'QRIS', 'DEBIT', 'KREDIT'] },
      { k: 'partsku', l: 'SKU Sparepart (opsional)', t: 'text', ph: 'SSD-SAM-980-500', half: true },
      { k: 'partqty', l: 'Qty Sparepart', t: 'number', def: 1, half: true }
    ],
    submitLabel: 'Buat Invoice',
    onSubmit: function (v, act) {
      var parts = v.partsku ? [{ sku: v.partsku, qty: num(v.partqty) || 1 }] : [];
      call('service.invoice', { id: id, biaya: v.biaya, metode: v.metode, parts: parts, bayar: num(v.biaya) }, { btn: act.button })
        .then(function (r) {
          if (!r || !r.ok) return;
          act.close();
          showReceipt(r.data.order, r.data.struk, r.data.wa_struk);
          loadService(); refreshBadges();
        });
    }
  });
}

/* ----------------------------- TRADE-IN -------------------------------- */
var TI = { status: 'ALL', q: '' };
function page_tradein() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Tukar Tambah</h1><p>Review pengajuan, simulasi harga, lalu setujui untuk membuat produk bekas otomatis.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="tiSim" type="button">' + svgI('cpu') + 'Simulator</button>' +
    '<button class="btn btn-primary btn-sm" id="tiNew" type="button">' + svgI('plus') + 'Catat Pengajuan</button></div></div>' +
    '<div class="grid-dash w4 mb6" id="tiStats"></div>' +
    '<div class="panel"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') + '<input class="inp" id="tiQ" placeholder="Cari kode, nama, atau perangkat…" type="text"/></div>' +
    '<select class="sel-mini" id="tiStatus"><option value="ALL">Semua Status</option>' +
    ['BARU', 'DISETUJUI', 'DITOLAK'].map(function (s0) { return '<option value="' + s0 + '">' + s0 + '</option>'; }).join('') + '</select>' +
    '</div></div></div>' +
    '<div class="panel mt4"><div class="panel-body tight" id="tiList"></div></div></div>';
  on($('#tiQ'), 'input', debounce(function (e) { TI.q = e.target.value.trim(); loadTradein(); }, 300));
  on($('#tiStatus'), 'change', function (e) { TI.status = e.target.value; loadTradein(); });
  on($('#tiSim'), 'click', tiSimulator);
  on($('#tiNew'), 'click', tiManualForm);
  return loadTradein();
}
function loadTradein() {
  var box = $('#tiList');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  return call('tradein.list', { q: TI.q, status: TI.status }, { silent: true }).then(function (r) {
    if (!r || !r.ok) { box.innerHTML = emptyState('Gagal memuat data tukar tambah.', 'alert'); return; }
    var list = r.data || [], ring = (r.meta || {}).ringkas || {};
    $('#tiStats').innerHTML = [
      ['Pengajuan Baru', int(ring.BARU), 'clock', 'linear-gradient(135deg,#f59e0b,#d97706)'],
      ['Disetujui', int(ring.DISETUJUI), 'checkc', 'linear-gradient(135deg,#10b981,#059669)'],
      ['Ditolak', int(ring.DITOLAK), 'alert', 'linear-gradient(135deg,#f43f5e,#e11d48)'],
      ['Nilai Disetujui', rp(ring.nilai_disetujui), 'wallet', 'var(--grad-brand)']
    ].map(function (k) {
      return '<div class="kpi"><div class="top"><span class="ic" style="background:' + k[3] + '">' + svgI(k[2]) + '</span></div>' +
        '<div class="lbl">' + k[0] + '</div><div class="val" style="font-size:20px">' + k[1] + '</div></div>';
    }).join('');
    if (!list.length) { box.innerHTML = emptyState('Belum ada pengajuan tukar tambah. Pelanggan dapat mengajukan dari halaman situs.', 'refresh'); return; }
    S.tiList = list;
    box.innerHTML = '<div class="table-wrap"><table class="dt"><thead><tr><th>Kode</th><th>Pelanggan</th><th>Perangkat</th>' +
      '<th class="num">Estimasi</th><th class="num">Penawaran</th><th>Status</th><th></th></tr></thead><tbody>' +
      list.map(function (t) {
        return '<tr><td><div style="font-family:var(--f-mono);font-size:12.2px;font-weight:700">' + esc(t.id) + '</div>' +
          '<div style="font-size:11px;color:var(--text-3)">' + esc(t.tanggal) + '</div></td>' +
          '<td><div style="font-weight:650;font-size:13px">' + esc(t.nama) + '</div>' +
          '<div style="font-size:11.5px;color:var(--text-3)">' + esc(t.wa) + '</div></td>' +
          '<td><div style="font-weight:650;font-size:12.8px">' + esc(t.perangkat) + '</div>' +
          '<div style="font-size:11px;color:var(--text-3)">' + esc(t.kategori) + ' · ' + esc(t.tahun) + ' · ' + esc(t.kondisi) + '</div></td>' +
          '<td class="num" style="font-size:12.5px">' + rp(t.estimasi_lo) + ' — ' + rp(t.estimasi_hi) + '</td>' +
          '<td class="num" style="font-weight:750">' + rp(t.penawaran) + '</td>' +
          '<td><span class="chip ' + (t.status === 'DISETUJUI' ? 'chip-emerald' : t.status === 'DITOLAK' ? 'chip-rose' : 'chip-amber') + '">' + esc(t.status) + '</span></td>' +
          '<td><div class="row-actions">' +
          (t.status === 'BARU' ? '<button class="mini-btn" data-appr="' + esc(t.id) + '" data-tip="Setujui" type="button">' + svgI('check') + '</button>' +
            '<button class="mini-btn danger" data-rej="' + esc(t.id) + '" data-tip="Tolak" type="button">' + svgI('x') + '</button>' : '') +
          '<button class="mini-btn" data-wa="' + esc(t.id) + '" data-tip="Chat WA" type="button">' + svgI('wa') + '</button>' +
          '</div></td></tr>';
      }).join('') + '</tbody></table></div>';
    $$('#tiList [data-appr]').forEach(function (b) { on(b, 'click', function () { approveTradein(b.getAttribute('data-appr')); }); });
    $$('#tiList [data-rej]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-rej');
        formModal({
          title: 'Tolak Pengajuan', sub: 'Alasan tercatat di audit trail dan dapat dikirim ke pelanggan.', size: 'sm',
          fields: [{ k: 'alasan', l: 'Alasan penolakan', t: 'textarea', req: true, ph: 'Unit tidak lulus verifikasi fisik / harga tidak sesuai' }],
          submitLabel: 'Tolak Pengajuan',
          onSubmit: function (v, act) {
            call('tradein.reject', { id: id, alasan: v.alasan }, { btn: act.button }).then(function (r2) {
              if (!r2 || !r2.ok) return;
              act.close(); toast('Pengajuan ' + id + ' ditolak', 'warn'); loadTradein();
            });
          }
        });
      });
    });
    $$('#tiList [data-wa]').forEach(function (b) {
      on(b, 'click', function () {
        var t = list.filter(function (x) { return x.id === b.getAttribute('data-wa'); })[0]; if (!t) return;
        window.open(waLink(t.wa, 'Halo ' + t.nama + ', pengajuan tukar tambah ' + t.id + ' untuk ' + t.perangkat +
          ' saat ini berstatus *' + t.status + '* dengan penawaran ' + rp(t.penawaran) + '.'), '_blank');
      });
    });
  });
}
function approveTradein(id) {
  var t = (S.tiList || []).filter(function (x) { return x.id === id; })[0] || {};
  var s = S.settings || {};
  var margin = num(s.tradein_margin_pct) || 25;
  formModal({
    title: 'Setujui Tukar Tambah ' + id, sub: 'Produk bekas akan dibuat otomatis dengan margin markup ' + margin + '%.', size: 'md',
    values: { penawaran: t.penawaran || t.estimasi_hi, margin_pct: margin, kategori: t.kategori, nama: t.perangkat + ' (Bekas)' },
    fields: [
      { k: 'penawaran', l: 'Harga Beli dari Pelanggan (Rp)', t: 'money', req: true, hint: 'Dasar perhitungan harga jual produk bekas.' },
      { k: 'margin_pct', l: 'Margin Markup (%)', t: 'number', req: true, half: true },
      { k: 'kategori', l: 'Kategori Produk', t: 'select', opts: ['Laptop', 'PC Rakitan', 'Komponen', 'Monitor', 'Aksesoris'], half: true },
      { k: 'nama', l: 'Nama Produk Bekas', t: 'text', req: true },
      { k: 'sku', l: 'SKU (opsional)', t: 'text', half: true, ph: 'USED-ZEN14' },
      { k: 'garansi', l: 'Garansi Toko', t: 'select', opts: ['14 hari', '30 hari toko', '60 hari toko'], half: true },
      { k: 'gambar', l: 'URL Foto Unit', t: 'text' },
      { k: 'deskripsi', l: 'Deskripsi', t: 'textarea', style: 'min-height:70px' }
    ],
    submitLabel: 'Setujui & Buat Produk',
    onSubmit: function (v, act) {
      call('tradein.approve', Object.assign({ id: id }, v), { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        var d = r.data;
        successBox('Tukar tambah disetujui', 'Produk bekas “' + d.produk.nama + '” dibuat dengan harga jual ' + rp(d.produk.harga) +
          ' (modal ' + rp(d.produk.harga_beli) + ').', [['Kode trade-in', id], ['SKU baru', d.produk.sku], ['Harga jual', rp(d.produk.harga)]],
          d.wa || null, 'Kirim Penawaran via WA');
        loadTradein(); refreshBadges();
      });
    }
  });
}
function tiSimulator() {
  formModal({
    title: 'Simulator Harga Tukar Tambah', sub: 'Hitung estimasi cepat tanpa membuat pengajuan.', size: 'md',
    fields: [
      { k: 'kategori', l: 'Kategori', t: 'select', opts: ['laptop', 'komponen', 'pc', 'monitor', 'aksesoris'], half: true },
      { k: 'brand', l: 'Merek', t: 'text', half: true },
      { k: 'perangkat', l: 'Perangkat', t: 'text' },
      { k: 'tahun', l: 'Tahun', t: 'number', def: new Date().getFullYear() - 2, half: true },
      { k: 'kondisi', l: 'Kondisi', t: 'select', opts: ['MULUS', 'BAIK', 'NORMAL', 'MINUS', 'RUSAK'], half: true },
      { k: 'harga_beli_dulu', l: 'Harga Beli Dulu (Rp)', t: 'money', req: true }
    ],
    submitLabel: 'Hitung Estimasi',
    onSubmit: function (v, act) {
      call('tradein.simulate', v, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        var e = r.data;
        successBox('Estimasi ' + v.perangkat, 'Berdasarkan umur ' + e.umur_tahun + ' tahun, kondisi ' + e.kondisi_label +
          ', dan faktor pasar saat ini.', [['Range harga', rp(e.estimasi_lo) + ' — ' + rp(e.estimasi_hi)],
          ['Bonus tukar tambah (' + e.bonus_pct + '%)', rp(e.bonus_rp)], ['Nilai maksimal', rp(e.nilai_maksimal)]], null);
      });
    }
  });
}
function tiManualForm() {
  formModal({
    title: 'Catat Pengajuan Tukar Tambah', sub: 'Untuk pengajuan yang diterima di toko / via telepon.', size: 'md',
    fields: [
      { k: 'nama', l: 'Nama Pelanggan', t: 'text', req: true, half: true },
      { k: 'wa', l: 'WhatsApp', t: 'tel', req: true, half: true },
      { k: 'perangkat', l: 'Perangkat', t: 'text', req: true },
      { k: 'kategori', l: 'Kategori', t: 'select', opts: ['Laptop', 'PC Rakitan', 'Komponen', 'Monitor', 'Aksesoris'], half: true },
      { k: 'tahun', l: 'Tahun Pembelian', t: 'number', half: true, def: new Date().getFullYear() - 2 },
      { k: 'kondisi', l: 'Kondisi', t: 'select', opts: ['MULUS', 'BAIK', 'NORMAL', 'MINUS', 'RUSAK'], half: true },
      { k: 'harga_beli_dulu', l: 'Harga Beli Dulu (Rp)', t: 'money', req: true, half: true },
      { k: 'catatan', l: 'Catatan Kelengkapan', t: 'text', ph: 'Box lengkap, charger original' }
    ],
    submitLabel: 'Simpan Pengajuan',
    onSubmit: function (v, act) {
      call('public.tradein.apply', v, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close();
        toast('Pengajuan ' + r.data.tradein.id + ' tercatat', 'ok');
        loadTradein(); refreshBadges();
      });
