}

/* =========================== 16. PROMO & KONTEN ========================= */
function page_promo() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Promo &amp; Voucher</h1><p>Atur diskon persentase/nominal, minimum belanja, kuota, dan masa berlaku.</p></div>' +
    '<button class="btn btn-primary btn-sm" id="pmNew" type="button">' + svgI('plus') + 'Buat Promo</button></div>' +
    '<div class="grid-dash w3" id="pmList"></div></div>';
  on($('#pmNew'), 'click', function () { promoForm(null); });
  return loadPromo();
}
function loadPromo() {
  var box = $('#pmList');
  box.innerHTML = '<div class="panel"><div class="panel-body"><div class="sk sk-line"></div></div></div>';
  return call('promo.list', {}, { silent: true }).then(function (r) {
    var list = (r && r.data) || [], meta = (r && r.meta) || {};
    if (!list.length) { box.innerHTML = emptyState('Belum ada promo. Buat voucher pertama untuk mendongkrak penjualan.', 'tag'); return; }
    S.pmList = list;
    box.innerHTML = list.map(function (p) {
      var nilai = p.tipe === 'PERCENT' ? p.nilai + '%' : rp(p.nilai);
      return '<div class="panel rv in"><div class="panel-body">' +
        '<div class="flex between center mb2 wrapf"><span class="chip ' + (p.berlaku ? 'chip-emerald' : 'chip-rose') + '">' +
        (p.berlaku ? 'AKTIF' : 'TIDAK BERLAKU') + '</span>' +
        '<strong style="font-family:var(--f-mono);font-size:15px;letter-spacing:.04em">' + esc(p.kode) + '</strong></div>' +
        '<h3 style="font-size:15px;margin-bottom:6px">' + esc(p.judul || '(tanpa judul)') + '</h3>' +
        '<div style="font-size:12.5px;color:var(--text-3);line-height:1.75">' +
        'Diskon <b style="color:var(--brand-700)">' + nilai + '</b>' + (p.maks_diskon ? ' (maks ' + rp(p.maks_diskon) + ')' : '') + '<br>' +
        'Min. belanja ' + (num(p.min_belanja) ? rp(p.min_belanja) : 'tanpa minimum') + '<br>' +
        'Periode ' + (p.mulai || '—') + ' s/d ' + (p.akhir || 'tanpa batas') + '<br>' +
        'Terpakai ' + int(p.terpakai) + '× ' + (p.sisa !== null && p.sisa !== undefined ? '· sisa kuota ' + int(p.sisa) : '· kuota tak terbatas') + '</div>' +
        '<div class="flex gap2 mt4 wrapf">' +
        '<button class="btn btn-ghost btn-sm" data-edit="' + esc(p.id) + '" type="button">' + svgI('edit') + 'Ubah</button>' +
        '<button class="btn btn-ghost btn-sm" data-tog="' + esc(p.id) + '" type="button">' + svgI(p.aktif ? 'eye' : 'check') + (p.aktif ? 'Nonaktifkan' : 'Aktifkan') + '</button>' +
        '<button class="btn btn-ghost btn-sm" data-copy="' + esc(p.kode) + '" type="button">' + svgI('clipboard') + 'Salin Kode</button>' +
        '<button class="btn btn-ghost btn-sm" data-del="' + esc(p.id) + '" type="button" style="color:#e11d48">' + svgI('trash') + '</button>' +
        '</div></div></div>';
    }).join('');
    $$('#pmList [data-edit]').forEach(function (b) { on(b, 'click', function () { promoForm(b.getAttribute('data-edit')); }); });
    $$('#pmList [data-tog]').forEach(function (b) {
      on(b, 'click', function () {
        call('promo.toggle', { id: b.getAttribute('data-tog') }, {}).then(function (r2) {
          if (!r2 || !r2.ok) return;
          toast('Promo ' + r2.data.kode + (num(r2.data.aktif) ? ' diaktifkan' : ' dinonaktifkan'), 'ok');
          loadPromo();
        });
      });
    });
    $$('#pmList [data-copy]').forEach(function (b) {
      on(b, 'click', function () { copyText(b.getAttribute('data-copy')).then(function () { toast('Kode promo disalin', 'ok'); }); });
    });
    $$('#pmList [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        confirmBox('Hapus promo?', 'Kode promo akan dihapus dan tidak bisa dipakai lagi di checkout.', function () {
          call('promo.delete', { id: b.getAttribute('data-del') }, {}).then(function () { toast('Promo dihapus', 'warn'); loadPromo(); });
        }, 'Ya, Hapus');
      });
    });
  });
}
function promoForm(id) {
  var p = (S.pmList || []).filter(function (x) { return x.id === id; })[0] || {};
  formModal({
    title: id ? 'Ubah Promo ' + p.kode : 'Buat Promo Baru', sub: 'Promo dapat dipakai pelanggan online maupun kasir POS.', size: 'md',
    values: p,
    fields: [
      { k: 'kode', l: 'Kode Promo', t: 'text', req: true, ph: 'HEMAT10', hint: 'Huruf kapital tanpa spasi' },
      { k: 'judul', l: 'Judul Promo', t: 'text', req: true, ph: 'Diskon 10% Laptop Gaming' },
      { k: 'tipe', l: 'Tipe Diskon', t: 'select', opts: [['PERCENT', 'Persentase (%)'], ['NOMINAL', 'Nominal (Rp)']], half: true },
      { k: 'nilai', l: 'Nilai Diskon', t: 'number', req: true, half: true, hint: 'Contoh: 10 untuk 10%, atau 150000 untuk Rp150.000' },
      { k: 'min_belanja', l: 'Minimum Belanja (Rp)', t: 'money', half: true },
