/* --------------------------- KONTEN SITUS ------------------------------- */
function page_content() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Konten Situs</h1><p>Banner promo, testimoni pelanggan, dan konten yang tampil di halaman publik.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="ctTesti" type="button">' + svgI('plus') + 'Testimoni</button>' +
    '<button class="btn btn-primary btn-sm" id="ctBanner" type="button">' + svgI('plus') + 'Banner</button></div></div>' +
    '<div class="tabs-app mb6" id="ctTabs"><button class="tab on" data-t="banner">Banner Promo</button>' +
    '<button class="tab" data-t="testi">Testimoni</button></div>' +
    '<div id="ctBody"></div></div>';
  var tab = 'banner';
  function render() {
    var box = $('#ctBody');
    call('content.get', {}, { silent: true }).then(function (r) {
      var d = (r && r.data) || {};
      if (tab === 'banner') {
        var list = d.banner || [];
        box.innerHTML = list.length ? '<div class="grid-dash w2">' + list.map(function (b) {
          return '<div class="panel rv in"><div class="panel-body">' +
            '<div class="flex between center mb2 wrapf"><span class="chip ' + (num(b.aktif) ? 'chip-emerald' : 'chip-rose') + '">' + (num(b.aktif) ? 'Tampil' : 'Draft') + '</span>' +
            '<span style="font-size:11.5px;color:var(--text-3)">Urutan ' + num(b.urutan) + '</span></div>' +
            '<h3 style="font-size:15px;margin-bottom:4px">' + esc(b.judul) + '</h3>' +
            '<p style="font-size:12.6px;color:var(--text-3);line-height:1.65">' + esc(b.subjek || '') + '</p>' +
            (b.gambar ? '<img alt="" src="' + esc(b.gambar) + '" style="width:100%;height:120px;object-fit:cover;border-radius:var(--r-md);margin-top:10px"/>' : '') +
            '<div class="flex gap2 mt4"><button class="btn btn-ghost btn-sm" data-edit="' + esc(b.id) + '" type="button">' + svgI('edit') + 'Ubah</button>' +
            '<button class="btn btn-ghost btn-sm" data-del="' + esc(b.id) + '" type="button" style="color:#e11d48">' + svgI('trash') + '</button></div>' +
            '</div></div>';
        }).join('') + '</div>' : emptyState('Belum ada banner. Tambahkan banner untuk menyorot promo di beranda.', 'sparkles');
        $$('#ctBody [data-edit]').forEach(function (b) { on(b, 'click', function () { bannerForm(b.getAttribute('data-edit'), d.banner); }); });
        $$('#ctBody [data-del]').forEach(function (b) {
          on(b, 'click', function () {
            confirmBox('Hapus banner?', 'Banner akan dihapus dari halaman utama.', function () {
              call('banner.delete', { id: b.getAttribute('data-del') }, {}).then(function () { toast('Banner dihapus', 'warn'); render(); });
            }, 'Ya, Hapus');
          });
        });
      } else {
        var t = d.testimoni || [];
        box.innerHTML = t.length ? '<div class="grid-dash w2">' + t.map(function (x) {
          return '<div class="panel rv in"><div class="panel-body">' +
            '<div class="flex between center mb2">' + starHtml(num(x.rating) || 5) +
            '<span class="chip ' + (num(x.aktif) ? 'chip-emerald' : 'chip-rose') + '">' + (num(x.aktif) ? 'Tampil' : 'Draft') + '</span></div>' +
            '<p style="font-size:13px;color:var(--text-2);line-height:1.75;font-style:italic">“' + esc(x.pesan) + '”</p>' +
            '<div class="mt4 flex gap3 center">' + imgTag(x.avatar, x.nama, '', 'width:38px;height:38px;border-radius:50%') +
            '<div><b style="font-size:13px">' + esc(x.nama) + '</b><div style="font-size:11.5px;color:var(--text-3)">' + esc(x.kota || '') + ' · ' + esc(x.produk || '') + '</div></div></div>' +
            '<div class="flex gap2 mt4"><button class="btn btn-ghost btn-sm" data-edit="' + esc(x.id) + '" type="button">' + svgI('edit') + 'Ubah</button>' +
            '<button class="btn btn-ghost btn-sm" data-del="' + esc(x.id) + '" type="button" style="color:#e11d48">' + svgI('trash') + '</button></div>' +
            '</div></div>';
        }).join('') + '</div>' : emptyState('Belum ada testimoni. Tambahkan ulasan pelanggan untuk memperkuat kepercayaan.', 'star');
        $$('#ctBody [data-edit]').forEach(function (b) { on(b, 'click', function () { testiForm(b.getAttribute('data-edit'), d.testimoni); }); });
        $$('#ctBody [data-del]').forEach(function (b) {
          on(b, 'click', function () {
            confirmBox('Hapus testimoni?', 'Testimoni akan hilang dari halaman publik.', function () {
              call('testi.delete', { id: b.getAttribute('data-del') }, {}).then(function () { toast('Testimoni dihapus', 'warn'); render(); });
            }, 'Ya, Hapus');
          });
        });
      }
    });
  }
  on($('#ctTabs'), 'click', function (e) {
    var t = e.target.closest('.tab'); if (!t) return;
    tab = t.getAttribute('data-t');
    $$('#ctTabs .tab').forEach(function (x) { x.classList.toggle('on', x === t); });
    render();
  });
  on($('#ctBanner'), 'click', function () { tab = 'banner'; $$('#ctTabs .tab').forEach(function (x) { x.classList.toggle('on', x.getAttribute('data-t') === 'banner'); }); bannerForm(null); });
  on($('#ctTesti'), 'click', function () { tab = 'testi'; $$('#ctTabs .tab').forEach(function (x) { x.classList.toggle('on', x.getAttribute('data-t') === 'testi'); }); testiForm(null); });
  render();
}
function bannerForm(id, list) {
  var b = (list || []).filter(function (x) { return x.id === id; })[0] || {};
  formModal({
    title: id ? 'Ubah Banner' : 'Banner Baru', sub: 'Banner tampil di bagian atas halaman utama.', size: 'md', values: b,
    fields: [
      { k: 'judul', l: 'Judul Banner', t: 'text', req: true, ph: 'Flash Sale Akhir Bulan' },
      { k: 'subjek', l: 'Deskripsi Singkat', t: 'text', ph: 'Diskon hingga 25% untuk laptop pilihan' },
      { k: 'gambar', l: 'URL Gambar', t: 'text', ph: 'https://images.unsplash.com/…' },
      { k: 'link', l: 'Link Tujuan', t: 'text', def: '#katalog', half: true },
      { k: 'urutan', l: 'Urutan Tampil', t: 'number', def: 1, half: true },
      { k: 'aktif', l: 'Tampilkan banner ini', t: 'switch', def: id ? num(b.aktif) : 1 }
    ],
    submitLabel: 'Simpan Banner',
    onSubmit: function (v, act) {
      v.id = id; v.aktif = num(v.aktif) ? 1 : 0;
      call('banner.save', v, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close(); toast('Banner tersimpan', 'ok');
        if (S.page === 'content') nav('content', null, true);
      });
    }
  });
}
function testiForm(id, list) {
  var t = (list || []).filter(function (x) { return x.id === id; })[0] || {};
  formModal({
    title: id ? 'Ubah Testimoni' : 'Testimoni Baru', sub: 'Testimoni tampil pada marquee halaman utama.', size: 'md', values: t,
    fields: [
      { k: 'nama', l: 'Nama Pelanggan', t: 'text', req: true, half: true },
      { k: 'kota', l: 'Kota', t: 'text', half: true },
      { k: 'produk', l: 'Produk yang Dibeli', t: 'text', ph: 'ASUS Vivobook 14' },
      { k: 'rating', l: 'Rating (1-5)', t: 'select', opts: ['5', '4', '3', '2', '1'], half: true },
      { k: 'urutan', l: 'Urutan', t: 'number', def: 1, half: true },
      { k: 'avatar', l: 'URL Foto (opsional)', t: 'text' },
      { k: 'pesan', l: 'Isi Testimoni', t: 'textarea', req: true, style: 'min-height:90px' },
