  });
}

/* =========================== 17. STAF, PENGATURAN, AUDIT =================== */
function page_staff() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Staf &amp; Hak Akses</h1><p>Kelola akun staf, role, dan PIN untuk login POS.</p></div>' +
    '<button class="btn btn-primary btn-sm" id="stfNew" type="button">' + svgI('plus') + 'Tambah Staf</button></div>' +
    '<div class="alert alert-info mb6" style="display:flex;gap:12px;align-items:flex-start;padding:14px 16px;border-radius:var(--r-md);background:var(--brand-50);border:1px solid var(--brand-100)">' +
    svgI('info') + '<div style="font-size:12.8px;color:var(--text-2);line-height:1.7"><b>Role &amp; akses:</b><br>' +
    Object.keys(DEMO.roleDesc()).map(function (r) { return '• <b>' + r + '</b> — ' + DEMO.roleDesc()[r]; }).join('<br>') + '</div></div>' +
    '<div class="grid-dash w3" id="stfList"></div></div>';
  on($('#stfNew'), 'click', function () { staffForm(null); });
  return loadStaff();
}
function loadStaff() {
  var box = $('#stfList');
  box.innerHTML = '<div class="panel"><div class="panel-body"><div class="sk sk-line"></div></div></div>';
  return call('staff.list', {}, { silent: true }).then(function (r) {
    var list = (r && r.data) || [];
    S.stfList = list;
    box.innerHTML = list.map(function (s0) {
      return '<div class="panel rv in"><div class="panel-body">' +
        '<div class="flex gap3 center mb2">' +
        '<span class="avatar-lg" style="width:46px;height:46px;border-radius:14px;font-size:16px;background:' +
        (s0.role === 'OWNER' ? 'linear-gradient(135deg,#0f172a,#334155)' : s0.role === 'ADMIN' ? 'linear-gradient(135deg,#8b5cf6,#7c3aed)' :
          s0.role === 'KASIR' ? 'var(--grad-brand)' : s0.role === 'GUDANG' ? 'linear-gradient(135deg,#f59e0b,#d97706)' : 'linear-gradient(135deg,#10b981,#059669)') + '">' +
        initials(s0.nama) + '</span>' +
        '<div style="flex:1;min-width:0"><b style="font-size:14.5px">' + esc(s0.nama) + '</b>' +
        '<div style="font-size:11.8px;color:var(--text-3)">' + esc(s0.role) + (s0.aktif ? ' · aktif' : ' · nonaktif') + '</div></div>' +
        '<span class="chip ' + (s0.aktif ? 'chip-emerald' : 'chip-rose') + '">' + (s0.aktif ? 'AKTIF' : 'OFF') + '</span></div>' +
        '<p style="font-size:12.4px;color:var(--text-3);line-height:1.6;min-height:38px">' + esc(s0.deskripsi) + '</p>' +
        '<div style="font-size:11.8px;color:var(--text-3)">Login terakhir: ' + esc(s0.last_login || 'belum pernah') + '</div>' +
        '<div class="flex gap2 mt4 wrapf">' +
        '<button class="btn btn-ghost btn-sm" data-edit="' + esc(s0.id) + '" type="button">' + svgI('edit') + 'Ubah</button>' +
        '<button class="btn btn-ghost btn-sm" data-pin="' + esc(s0.id) + '" type="button">' + svgI('key') + 'Reset PIN</button>' +
        (s0.role !== 'OWNER' ? '<button class="btn btn-ghost btn-sm" data-del="' + esc(s0.id) + '" type="button" style="color:#e11d48">' + svgI('trash') + '</button>' : '') +
        '</div></div></div>';
    }).join('');
    $$('#stfList [data-edit]').forEach(function (b) { on(b, 'click', function () { staffForm(list.filter(function (x) { return x.id === b.getAttribute('data-edit'); })[0]); }); });
    $$('#stfList [data-pin]').forEach(function (b) {
      on(b, 'click', function () {
        var id = b.getAttribute('data-pin');
        var s0 = list.filter(function (x) { return x.id === id; })[0] || {};
        formModal({
          title: 'Reset PIN ' + s0.nama, sub: 'PIN dipakai untuk login POS. Berikan hanya kepada staf bersangkutan.', size: 'sm',
          fields: [{ k: 'pin', l: 'PIN Baru', t: 'text', req: true, def: String(Math.floor(1000 + Math.random() * 8999)), hint: '4-8 digit angka' }],
          submitLabel: 'Reset PIN',
          onSubmit: function (v, act) {
            call('staff.resetPin', { id: id, pin: v.pin }, { btn: act.button }).then(function (r2) {
              if (!r2 || !r2.ok) return;
              act.close();
              successBox('PIN direset', 'Sampaikan PIN baru ini kepada ' + s0.nama + ' secara langsung.', [['Nama', s0.nama], ['PIN Baru', r2.data.pin]], null);
            });
          }
        });
      });
    });
    $$('#stfList [data-del]').forEach(function (b) {
      on(b, 'click', function () {
        var s0 = list.filter(function (x) { return x.id === b.getAttribute('data-del'); })[0] || {};
        confirmBox('Hapus staf?', s0.nama + ' tidak akan bisa login lagi ke sistem.', function () {
          call('staff.delete', { id: s0.id }, {}).then(function () { toast('Staf dihapus', 'warn'); loadStaff(); });
        }, 'Ya, Hapus');
      });
    });
  });
}
function staffForm(s0) {
  var isNew = !s0;
  s0 = s0 || {};
  formModal({
    title: isNew ? 'Tambah Staf' : 'Ubah ' + s0.nama, sub: 'PIN hanya bisa diubah oleh Owner/Admin.', size: 'md', values: s0,
    fields: [
      { k: 'nama', l: 'Nama Staf', t: 'text', req: true },
      { k: 'role', l: 'Role', t: 'select', req: true, opts: Object.keys(DEMO.roleDesc()) },
      { k: 'wa', l: 'WhatsApp', t: 'tel', half: true },
      { k: 'email', l: 'Email', t: 'text', half: true },
      { k: 'pin', l: isNew ? 'PIN Awal' : 'PIN Baru (opsional)', t: 'text', ph: '4-8 digit', hint: 'Kosongkan bila tidak ingin mengubah PIN' },
      { k: 'aktif', l: 'Akun aktif', t: 'switch', def: isNew ? 1 : num(s0.aktif) }
    ],
    submitLabel: isNew ? 'Tambah Staf' : 'Simpan Perubahan',
    onSubmit: function (v, act) {
      if (isNew && (!v.pin || String(v.pin).length < 4)) { toast('PIN awal wajib 4-8 digit', 'warn'); return; }
      v.id = s0.id || ''; v.aktif = num(v.aktif) ? 1 : 0;
      call('staff.save', v, { btn: act.button }).then(function (r) {
        if (!r || !r.ok) return;
        act.close(); toast('Data staf tersimpan', 'ok'); loadStaff();
      });
    }
  });
}

