  ['Profil Toko', [['nama_toko', 'Nama Toko', 'text'], ['tagline', 'Tagline', 'text'], ['alamat', 'Alamat', 'textarea'],
    ['kota', 'Kota', 'text'], ['wa', 'WhatsApp Toko', 'tel'], ['email', 'Email', 'text'], ['jam_buka', 'Jam Buka', 'text'],
    ['ig', 'Instagram', 'text'], ['fb', 'Facebook', 'text'], ['tiktok', 'TikTok', 'text'], ['maps', 'Link Google Maps', 'text']]],
  ['Poin & Tier', [['poin_per_1000', 'Poin per Rp1.000', 'number'], ['poin_nilai', 'Nilai 1 Poin (Rp)', 'number'],
    ['poin_maks_pct', 'Maksimal Tukar Poin (%)', 'number'], ['tier_silver', 'Ambang Silver (Rp)', 'money'],
    ['tier_gold', 'Ambang Gold (Rp)', 'money'], ['tier_platinum', 'Ambang Platinum (Rp)', 'money']]],
  ['Harga & Pengiriman', [['ongkir_min', 'Ongkir Minimum (Rp)', 'money'], ['gratis_ongkir', 'Gratis Ongkir Mulai (Rp)', 'money'],
    ['pajak_pct', 'Pajak / PPN (%)', 'number']]],
  ['Tukar Tambah', [['tradein_aktif', 'Fitur Tukar Tambah', 'switch'], ['tradein_bonus_pct', 'Bonus Tukar Tambah (%)', 'number'],
    ['tradein_margin_pct', 'Margin Markup Produk Bekas (%)', 'number']]]
];
function page_settings() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Pengaturan Sistem</h1><p>Profil toko, aturan poin, pengiriman, dan template WhatsApp.</p></div>' +
    '<div class="flex gap2 wrapf"><button class="btn btn-ghost btn-sm" id="setReload" type="button">' + svgI('refresh') + 'Muat Ulang</button>' +
    '<button class="btn btn-primary btn-sm" id="setSave" type="button">' + svgI('save') + 'Simpan Pengaturan</button></div></div>' +
    '<div class="grid-dash w2" id="setWrap"></div>' +
    '<div class="panel mt6"><div class="panel-head"><div style="flex:1"><h3>Template Pesan WhatsApp</h3>' +
    '<p>Tersedia variabel: {toko} {items} {total} {nama} {wa} {alamat} {kode} {perangkat} {keluhan} {estimasi} {diskon} {subtotal} {tahun} {kondisi} {harga}</p></div></div>' +
    '<div class="panel-body" id="setTmpl"></div></div>' +
    '<div class="panel mt6"><div class="panel-head"><div style="flex:1"><h3>Utilitas Sistem</h3><p>Perawatan database, backup, dan pengaturan lanjutan.</p></div></div>' +
    '<div class="panel-body"><div class="flex gap2 wrapf">' +
    '<button class="btn btn-ghost" id="sysInfo" type="button">' + svgI('info') + 'Info Sistem</button>' +
    '<button class="btn btn-ghost" id="sysWarm" type="button">' + svgI('refresh') + 'Warm Cache</button>' +
    '<button class="btn btn-ghost" id="sysBackup" type="button">' + svgI('download') + 'Backup DB</button>' +
    '<button class="btn btn-ghost" id="sysReset" type="button" style="color:#e11d48">' + svgI('alert') + 'Reset Data Demo</button>' +
    '</div><div class="mt4" id="sysOut"></div></div></div></div>';
  on($('#setSave'), 'click', saveSettings);
  on($('#setReload'), 'click', function () { loadSettings(); toast('Pengaturan dimuat ulang', 'ok'); });
  on($('#sysInfo'), 'click', function () {
    call('system.info', {}, {}).then(function (r) {
      if (!r || !r.ok) return;
      var d = r.data;
      $('#sysOut').innerHTML = '<div class="card card-pad soft" style="border-radius:var(--r-md);font-size:12.8px;line-height:1.8">' +
        '<b>' + esc(d.app.nama) + '</b> · versi ' + esc(d.app.versi) + '<br>' +
        'Waktu server: ' + esc(d.waktu) + ' · zona ' + esc(d.app.zona) + '<br>' +
        'Zona waktu: ' + esc(d.app.zona) + ' · Token TTL: ' + int(d.app.token_ttl) + ' detik<br>' +
        'Total baris data: <b>' + int(d.total_baris) + '</b><br>' +
        Object.keys(d.tabel).map(function (k) { return esc(k) + ': ' + int(d.tabel[k]); }).join(' · ') + '<br>' +
        'API URL: ' + (d.api_url ? esc(d.api_url) : '<span style="color:#d97706">belum diisi (mode demo)</span>') + '</div>';
    });
  });
  on($('#sysWarm'), 'click', function () {
    call('system.warm', {}, { btn: $('#sysWarm') }).then(function (r) { if (r && r.ok) toast(r.data.pesan, 'ok'); });
  });
  on($('#sysBackup'), 'click', function () {
    call('system.backup', {}, { btn: $('#sysBackup') }).then(function (r) {
      if (!r || !r.ok) return;
      var d = r.data;
      successBox('Backup', d.pesan + (d.url ? ' Tautan: ' + d.url : ''), null, null);
    });
  });
  on($('#sysReset'), 'click', function () {
    confirmBox('Reset data demo?', 'Semua transaksi, service, trade-in, mutasi stok, dan audit trail demo akan dikosongkan. Produk & pengaturan tetap.', function () {
      call('system.resetDemo', {}, {}).then(function (r) {
        if (!r || !r.ok) return;
        toast(r.data.pesan, 'warn'); refreshBadges();
      });
    }, 'Ya, Reset');
  });
  return loadSettings();
}
function loadSettings() {
  var wrap = $('#setWrap');
  wrap.innerHTML = '<div class="panel"><div class="panel-body"><div class="sk sk-line"></div><div class="sk sk-line"></div></div></div>';
  return call('settings.get', {}, { silent: true }).then(function (r) {
    var d = (r && r.data) || {};
    S.settings = d;
    wrap.innerHTML = SET_GROUPS.map(function (g) {
      return '<div class="panel rv in"><div class="panel-head"><div style="flex:1"><h3>' + g[0] + '</h3></div></div>' +
        '<div class="panel-body">' + g[1].map(function (f) {
          var k = f[0], lbl = f[1], t = f[2], val = d[k] === undefined ? '' : d[k];
          if (t === 'switch') return '<label class="switch mb4" style="margin-bottom:14px"><input data-k="' + k + '" type="checkbox"' + (num(val) ? ' checked="checked"' : '') + '/><span class="track"></span><span>' + lbl + '</span></label>';
          if (t === 'textarea') return '<label class="field"><span class="lbl">' + lbl + '</span><textarea class="txt" data-k="' + k + '" style="min-height:70px">' + esc(val) + '</textarea></label>';
          if (t === 'money' || t === 'number') return '<label class="field"><span class="lbl">' + lbl + '</span><input class="inp num" data-k="' + k + '" inputmode="numeric" type="number" value="' + esc(numInputVal(val)) + '"/></label>';
          return '<label class="field"><span class="lbl">' + lbl + '</span><input class="inp" data-k="' + k + '" type="' + (t === 'tel' ? 'tel' : 'text') + '" value="' + esc(val) + '"/></label>';
        }).join('') + '</div></div>';
    }).join('');
    $('#setTmpl').innerHTML = [['wa_template_order', 'Pesanan Online'], ['wa_template_service', 'Pengajuan Service'], ['wa_template_tradein', 'Pengajuan Tukar Tambah']]
      .map(function (t2) {
        return '<label class="field"><span class="lbl">' + t2[1] + '</span>' +
          '<textarea class="txt" data-k="' + t2[0] + '" style="min-height:130px;font-family:var(--f-mono);font-size:12.3px">' + esc(d[t2[0]] || '') + '</textarea></label>';
      }).join('');
  });
}
function saveSettings() {
  var payload = {};
  $$('#setWrap [data-k], #setTmpl [data-k]').forEach(function (el) {
    var k = el.getAttribute('data-k');
    payload[k] = el.type === 'checkbox' ? (el.checked ? '1' : '0') : el.value;
  });
  call('settings.save', payload, { btn: $('#setSave') }).then(function (r) {
    if (!r || !r.ok) return;
    S.settings = r.data;
    renderFooter(r.data);
    toast('Pengaturan tersimpan (' + (r.meta.diubah || 0) + ' kunci)', 'ok');
  });
}

/* ---------------------------- AUDIT TRAIL ------------------------------ */
var AUD = { q: '', aksi: 'ALL', entitas: 'ALL', page: 1, limit: 40, pages: 1 };
function page_audit() {
  $('#viewBox').innerHTML =
    '<div class="page">' +
    '<div class="page-head"><div><h1>Audit Trail</h1><p>Jejak semua tindakan vital: login, checkout, void, ubah harga, dan hapus data.</p></div>' +
    '<button class="btn btn-ghost btn-sm" id="audExport" type="button">' + svgI('download') + 'Ekspor CSV</button></div>' +
    '<div class="panel mb4"><div class="panel-body"><div class="toolbar">' +
    '<div class="search-box" style="flex:1;min-width:220px">' + svgI('search') + '<input class="inp" id="audQ" placeholder="Cari aksi, nama staf, atau detail…" type="text"/></div>' +
    '<input class="inp" id="audAksi" placeholder="Filter aksi (mis. CHECKOUT)" style="max-width:230px" type="text"/>' +
    '<select class="sel-mini" id="audEntitas"><option value="ALL">Semua Entitas</option>' +
    ['ORDER', 'PRODUCT', 'CUSTOMER', 'SERVICE', 'TRADEIN', 'STOCKMOVE', 'PO', 'PROMO', 'STAFF', 'SETTING', 'BANNER', 'TESTI'].map(function (e) {
      return '<option value="' + e + '">' + e + '</option>';
    }).join('') + '</select></div></div></div>' +
    '<div class="panel"><div class="panel-head"><div style="flex:1"><h3>Riwayat Aksi</h3><p id="audCount">Memuat…</p></div></div>' +
    '<div class="panel-body tight" id="audTable"></div></div>' +
    '<div class="tc mt6" id="audPager"></div></div>';
  on($('#audQ'), 'input', debounce(function (e) { AUD.q = e.target.value.trim(); AUD.page = 1; loadAudit(); }, 300));
  on($('#audAksi'), 'input', debounce(function (e) { AUD.aksi = e.target.value.trim() || 'ALL'; AUD.page = 1; loadAudit(); }, 320));
  on($('#audEntitas'), 'change', function (e) { AUD.entitas = e.target.value; AUD.page = 1; loadAudit(); });
  on($('#audExport'), 'click', function () {
    var rows = (S.audList || []).map(function (a) { return [a.tanggal, a.user, a.role, a.aksi, a.entitas, a.entitas_id, a.detail]; });
    if (!rows.length) { toast('Tidak ada data audit', 'warn'); return; }
    downloadCSV('audit-' + dayStr() + '.csv', ['Waktu', 'Pengguna', 'Role', 'Aksi', 'Entitas', 'ID', 'Detail'], rows);
  });
  return loadAudit();
}
function loadAudit() {
  var box = $('#audTable');
  box.innerHTML = '<div style="padding:16px"><div class="sk sk-line"></div><div class="sk sk-line"></div></div>';
  return call('audit.list', { q: AUD.q, aksi: AUD.aksi, entitas: AUD.entitas, page: AUD.page, limit: AUD.limit }, { silent: true }).then(function (r) {
    if (!r || !r.ok) { box.innerHTML = emptyState('Gagal memuat audit trail.', 'alert'); return; }
    var list = r.data || [], meta = r.meta || {};
    S.audList = list;
    AUD.pages = meta.pages || 1;
    $('#audCount').innerHTML = '<strong>' + int(meta.total) + '</strong> catatan · halaman ' + (meta.page || 1) + '/' + AUD.pages +
      ' · ' + int(meta.jenis_aksi) + ' jenis aksi tercatat';
    if (!list.length) { box.innerHTML = emptyState('Belum ada catatan audit yang cocok dengan filter.', 'clipboard'); $('#audPager').innerHTML = ''; return; }
    function color(a) {
      if (/HAPUS|VOID|GAGAL|TOLAK/.test(a)) return 'chip-rose';
      if (/TAMBAH|CHECKOUT|LOGIN|TERIMA|SETUJUI/.test(a)) return 'chip-emerald';
      if (/UBAH|STATUS|REVIEW|RESET|OPNAME/.test(a)) return 'chip-amber';
      return '';
    }
    box.innerHTML = '<div class="table-wrap"><table class="dt"><thead><tr><th style="width:150px">Waktu</th><th>Pengguna</th>' +
      '<th>Aksi</th><th>Entitas</th><th>Detail</th></tr></thead><tbody>' + list.map(function (a) {
        return '<tr><td style="font-size:12.2px;white-space:nowrap">' + esc(a.tanggal) + '</td>' +
          '<td><div style="font-weight:650;font-size:12.8px">' + esc(a.user) + '</div><div style="font-size:11px;color:var(--text-3)">' + esc(a.role) + '</div></td>' +
          '<td><span class="chip ' + color(String(a.aksi)) + '">' + esc(a.aksi) + '</span></td>' +
          '<td style="font-size:12.2px">' + esc(a.entitas) + (a.entitas_id ? '<div style="font-size:11px;color:var(--text-3)">' + esc(a.entitas_id) + '</div>' : '') + '</td>' +
          '<td style="font-size:12.3px;color:var(--text-2)">' + esc(a.detail || '—') + '</td></tr>';
      }).join('') + '</tbody></table></div>';
    $('#audPager').innerHTML = AUD.pages > 1 ? '<div class="pager">' +
      '<button class="btn btn-ghost btn-sm" ' + (AUD.page <= 1 ? 'disabled="disabled"' : '') + ' data-pg="-1" type="button">Sebelumnya</button>' +
      '<span style="font-size:12.5px;color:var(--text-3);font-weight:650">Halaman ' + AUD.page + ' / ' + AUD.pages + '</span>' +
      '<button class="btn btn-ghost btn-sm" ' + (AUD.page >= AUD.pages ? 'disabled="disabled"' : '') + ' data-pg="1" type="button">Berikutnya</button></div>' : '';
    $$('#audPager [data-pg]').forEach(function (b) {
      on(b, 'click', function () { AUD.page = clamp(AUD.page + num(b.getAttribute('data-pg')), 1, AUD.pages); loadAudit(); });
    });
  });
}

/* =========================== 18. BOOTSTRAP APLIKASI ===================== */
function bindGlobal() {
  on(window, 'error', function (e) {
    if (e && e.message && /Script error/i.test(e.message)) return;
  });
  /* --- masuk / keluar aplikasi --- */
  function tryLogin() {
    if (restoreSession()) { toast('Sesi ditemukan — melanjutkan sebagai ' + S.user.nama, 'ok'); enterApp(); }
    else showLogin();
  }
  on($('#loginBtn'), 'click', tryLogin);
  on($('#loginDrawerBtn'), 'click', function () {
    $('#drawer').classList.remove('open');
    document.body.classList.remove('no-scroll');
    tryLogin();
  });
  on($('#userChip'), 'click', function () {
    if (!S.user) return;
    confirmBox('Kelola sesi POS', 'Masuk sebagai <b>' + S.user.nama + '</b> (' + S.user.role + '). Pilih tindakan:', function () {
      logoutApp();
    }, 'Keluar dari Akun');
  });
  /* --- tombol WhatsApp (button, bukan <a>) --- */
  $$('#heroWaBtn,#ctaWaBtn,#ctWaBtn,#faqWaBtn,#fabWa,#mnavWa,#waDrawer,#fWa,#fWa2').forEach(function (el) {
    if (!el || el.tagName === 'A') return;
    on(el, 'click', function () {
      var s = S.settings || {};
      window.open(waLink(s.wa || CONFIG.WA_DEFAULT, 'Halo ' + (s.nama_toko || 'Sarinadinet') +
        ', saya ingin konsultasi pembelian laptop / PC. Bisa bantu rekomendasi sesuai budget saya?'), '_blank');
    });
  });
  /* --- navigasi halus untuk anchor landing --- */
  $$('a[href^="#"]').forEach(function (a) {
    on(a, 'click', function (e) {
      var id = a.getAttribute('href');
      if (id === '#' || id.length < 2) return;
      var t = document.getElementById(id.slice(1));
      if (!t) return;
      e.preventDefault();
      var off = $('#nav') ? 70 : 0;
      var y = t.getBoundingClientRect().top + window.pageYOffset - off;
      window.scrollTo({ top: y, behavior: 'smooth' });
    });
  });
  on($('#navLogo'), 'click', function (e) { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); });
  /* --- modal: klik backdrop & escape --- */
  on(document, 'click', function (e) {
    var bg = e.target.closest('.modal-bg');
    if (bg) { var m = bg.closest('.modal'); if (m) closeModal(m.id); }
  });
  on(document, 'keydown', function (e) {
    if (e.key !== 'Escape') return;
    var open = $$('.modal.open').slice(-1)[0];
    if (open) { closeModal(open.id); return; }
    if ($('#drawer').classList.contains('open')) { $('#drawer').classList.remove('open'); document.body.classList.remove('no-scroll'); }
  });
  /* --- FAB WA: sembunyikan saat modal terbuka --- */
  var fab = $('#fabWa');
  if (fab) {
    var mo = new MutationObserver(function () {
      var anyOpen = !!$$('.modal.open').length;
      fab.style.opacity = anyOpen ? '0' : '';
      fab.style.pointerEvents = anyOpen ? 'none' : '';
    });
    mo.observe(document.body, { attributes: true, attributeFilter: ['class'], subtree: true });
  }
}
function boot() {
  /* tema: pilihan tersimpan → preferensi sistem → terang */
  var simpan = ls(CONFIG.THEME_KEY);
  var sistem = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  applyTheme(simpan || sistem);
  cartLoad(); cartBadge();
  initNav();
  initReveal();
  bindGlobal();
  bootLanding();
  /* hash #pos / #admin membuka langsung panel staf */
  if (/^#(pos|admin|dashboard)$/.test(location.hash)) {
    setTimeout(function () {
      if (restoreSession()) enterApp(); else showLogin();
    }, 400);
  }
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
//
